window.__PURENISTA_CONTENT={"ae-comp": "\n    <div class=\"card\">\n      <h3>構圖圖解 <span class=\"tag ok\">看圖秒懂</span></h3>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 180 120\" role=\"img\">\n<rect x=\"1\" y=\"1\" width=\"178\" height=\"118\" rx=\"8\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<g stroke=\"#7B6BB5\" stroke-width=\"1.2\" stroke-dasharray=\"4 4\" opacity=\".85\">\n<line x1=\"60\" y1=\"4\" x2=\"60\" y2=\"116\"/><line x1=\"120\" y1=\"4\" x2=\"120\" y2=\"116\"/>\n<line x1=\"4\" y1=\"40\" x2=\"176\" y2=\"40\"/><line x1=\"4\" y1=\"80\" x2=\"176\" y2=\"80\"/></g>\n<circle cx=\"60\" cy=\"40\" r=\"4\" fill=\"#DDD6E8\"/><circle cx=\"120\" cy=\"80\" r=\"4\" fill=\"#DDD6E8\"/><circle cx=\"60\" cy=\"80\" r=\"4\" fill=\"#DDD6E8\"/>\n<circle cx=\"120\" cy=\"40\" r=\"8\" fill=\"#8A5FC0\"/><circle cx=\"120\" cy=\"40\" r=\"13\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"1.5\" opacity=\".5\"/>\n<text x=\"127\" y=\"32\" font-size=\"9\" fill=\"#2A2138\">主角</text></svg></div><figcaption>三分法：主角放在交叉點，比放正中央更有呼吸感</figcaption></figure>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"16\" fill=\"#8A5FC0\"/><line x1=\"60\" y1=\"6\" x2=\"60\" y2=\"84\" stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".5\"/></svg></div><figcaption>中央構圖・莊重聚焦</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"12\" y1=\"80\" x2=\"108\" y2=\"14\" stroke=\"#7B6BB5\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/><circle cx=\"45\" cy=\"60\" r=\"9\" fill=\"#8A5FC0\"/><circle cx=\"80\" cy=\"36\" r=\"6\" fill=\"#8A5FC0\" opacity=\".55\"/></svg></div><figcaption>對角線・動感方向</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><polygon points=\"60,18 96,74 24,74\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/><circle cx=\"60\" cy=\"26\" r=\"8\" fill=\"#8A5FC0\"/><circle cx=\"34\" cy=\"68\" r=\"7\" fill=\"#8A5FC0\" opacity=\".6\"/><circle cx=\"86\" cy=\"68\" r=\"7\" fill=\"#8A5FC0\" opacity=\".6\"/></svg></div><figcaption>三角構圖・穩定</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"20\" y=\"14\" width=\"80\" height=\"62\" rx=\"6\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"6\" opacity=\".35\"/><circle cx=\"60\" cy=\"45\" r=\"13\" fill=\"#8A5FC0\"/></svg></div><figcaption>框架式・鎖定視線</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"1.4\" opacity=\".7\"><line x1=\"4\" y1=\"86\" x2=\"56\" y2=\"44\"/><line x1=\"116\" y1=\"86\" x2=\"64\" y2=\"44\"/><line x1=\"60\" y1=\"88\" x2=\"60\" y2=\"52\"/></g><circle cx=\"60\" cy=\"38\" r=\"11\" fill=\"#8A5FC0\"/></svg></div><figcaption>引導線・帶向主角</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"92\" cy=\"45\" r=\"12\" fill=\"#8A5FC0\"/><rect x=\"10\" y=\"10\" width=\"60\" height=\"70\" rx=\"6\" fill=\"#7B6BB5\" opacity=\".07\"/><text x=\"18\" y=\"49\" font-size=\"9\" fill=\"#7B6BB5\">留白</text></svg></div><figcaption>留白・凸顯主體</figcaption></figure>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3>基本構圖法 <span class=\"tag gold\">先學這幾招</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">構圖＝決定「主角放哪裡、視線怎麼走」。不確定時，先用三分法就不會出錯。</p>\n      <details><summary>三分法（井字構圖）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".8\"><line x1=\"38\" y1=\"4\" x2=\"38\" y2=\"62\"/><line x1=\"73\" y1=\"4\" x2=\"73\" y2=\"62\"/><line x1=\"4\" y1=\"23\" x2=\"106\" y2=\"23\"/><line x1=\"4\" y1=\"43\" x2=\"106\" y2=\"43\"/></g><circle cx=\"73\" cy=\"23\" r=\"7\" fill=\"#8A5FC0\"/></svg></span>把畫面橫豎各切三等分，形成四個交叉點。<b>把主角的臉、眼睛或最想被看見的細節放在交叉點上</b>，畫面會比放正中央更自然、更有呼吸感。最泛用、最不易失手的一招。</p></details>\n      <details><summary>中央構圖（日之丸構圖）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"55\" y1=\"6\" x2=\"55\" y2=\"60\" stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".5\"/><circle cx=\"55\" cy=\"33\" r=\"13\" fill=\"#8A5FC0\"/></svg></span>主角放正中央。優點是<b>強烈、莊重、聚焦</b>，適合對稱華麗的裙裝、正面禮服照；缺點是容易呆板——解法是讓<b>背景或配件不對稱</b>，或讓人物視線偏一側。</p></details>\n      <details><summary>對角線構圖</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"10\" y1=\"56\" x2=\"100\" y2=\"12\" stroke=\"#7B6BB5\" stroke-width=\"1.4\" stroke-dasharray=\"4 3\"/><circle cx=\"40\" cy=\"42\" r=\"8\" fill=\"#8A5FC0\"/><circle cx=\"72\" cy=\"26\" r=\"5\" fill=\"#8A5FC0\" opacity=\".55\"/></svg></span>把主體沿著畫面的對角線安排。斜線天生帶有<b>動感與方向性</b>，適合走動、飛揚的裙擺、飄帶；比水平垂直更有活力。</p></details>\n      <details><summary>三角構圖</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><polygon points=\"55,12 92,54 18,54\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.4\" stroke-dasharray=\"4 3\"/><circle cx=\"55\" cy=\"20\" r=\"7\" fill=\"#8A5FC0\"/><circle cx=\"26\" cy=\"49\" r=\"6\" fill=\"#8A5FC0\" opacity=\".6\"/><circle cx=\"84\" cy=\"49\" r=\"6\" fill=\"#8A5FC0\" opacity=\".6\"/></svg></span>主體或主體群構成三角形。<b>正三角＝穩定、莊嚴</b>（適合裙擺展開的坐姿）；<b>倒三角＝不安、張力</b>（適合暗黑主題）。雙人照最常用的排法。</p></details>\n      <details><summary>框架式構圖</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"16\" y=\"10\" width=\"78\" height=\"46\" rx=\"5\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"5\" opacity=\".35\"/><circle cx=\"55\" cy=\"33\" r=\"11\" fill=\"#8A5FC0\"/></svg></span>用<b>前景的東西框住主角</b>——窗框、拱門、樹枝、簾幕、垂下的花。可以增加景深、把視線牢牢鎖在人物身上，也讓畫面更有「故事感」。</p></details>\n      <details><summary>引導線</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"1.3\" opacity=\".7\"><line x1=\"6\" y1=\"60\" x2=\"50\" y2=\"30\"/><line x1=\"104\" y1=\"60\" x2=\"60\" y2=\"30\"/></g><circle cx=\"55\" cy=\"24\" r=\"9\" fill=\"#8A5FC0\"/></svg></span>利用地板線條、階梯、緞帶、光束把視線<b>引向主角</b>。看不出主角是誰的照片，通常就是缺了引導線。</p></details>\n      <details><summary>留白（負空間）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"82\" cy=\"33\" r=\"11\" fill=\"#8A5FC0\"/><rect x=\"8\" y=\"8\" width=\"52\" height=\"50\" rx=\"5\" fill=\"#7B6BB5\" opacity=\".08\"/></svg></span>不是所有地方都要填滿。<b>大面積留白會讓主角更突出</b>，也更有高級感與孤寂感。留白通常留在<b>人物視線的前方</b>，看起來才不會像被牆擋住。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>進階：視覺重量與層次 <span class=\"tag ok\">讓畫面站得穩</span></h3>\n      <ul class=\"tips\">\n        <li><b>視覺重量</b>深色、高彩度、細節密、面積大的東西「比較重」。一邊太重畫面就會傾斜——用另一側的<b>小而亮</b>的元素就能平衡。</li>\n        <li><b>三層景深</b>前景／中景／背景都安排一點東西（例：前景花瓣 → 中景人物 → 背景建築），畫面立刻從「貼紙」變「空間」。</li>\n        <li><b>視線方向留空間</b>人物看向哪邊，那邊就多留一點空白，叫做<b>視線空間</b>；反之會有壓迫感。</li>\n        <li><b>奇數法則</b>元素用 1、3、5 個比 2、4 個更自然生動。</li>\n        <li><b>避免切關節</b>裁切時避開手腕、膝蓋、腳踝等關節處，改切大腿或腰腹會更好看。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>進階構圖法 <span class=\"tag gold\">再上一層</span></h3>\n      <details><summary>黃金螺旋 / 費波那契</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M92 12 A40 40 0 0 1 92 52 A28 28 0 0 1 44 52 A18 18 0 0 1 62 34 A10 10 0 0 1 62 46\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.6\"/><circle cx=\"62\" cy=\"40\" r=\"4\" fill=\"#8A5FC0\"/></svg></span>把黃金矩形不斷分割會形成一條<b>向內收束的螺旋</b>。把主角（或最重要的細節，如眼睛）放在<b>螺旋收束的中心點</b>，畫面會有一種說不出的自然與流動感。名畫與經典攝影大量使用。</p></details>\n      <details><summary>對稱與倒影</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"8\" y1=\"33\" x2=\"102\" y2=\"33\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"22\" r=\"9\" fill=\"#8A5FC0\"/><circle cx=\"55\" cy=\"44\" r=\"9\" fill=\"#8A5FC0\" opacity=\".4\"/></svg></span><b>完全對稱</b>帶來莊嚴、神聖、儀式感；水面、鏡子的<b>倒影對稱</b>則多一層夢幻與虛實。鏡像主題（如 melem）用倒影構圖再貼切不過。</p></details>\n      <details><summary>填充式構圖 / 破格</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"30\" fill=\"#8A5FC0\"/></svg></span>讓主體<b>撐滿整個畫面、甚至超出邊界</b>被裁切。製造強烈的張力、壓迫感與親密感，適合特寫與情緒強烈的畫面。與「留白」是兩個極端，各有力量。</p></details>\n      <details><summary>三角形的方向性</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><polygon points=\"30,50 88,50 74,16\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/></svg></span>不只正三角（穩定）與倒三角（不安）——<b>斜三角</b>帶來動勢與方向感。多人構圖時，讓頭部連線形成三角，是最穩的group pose。</p></details>\n      <details><summary>前景框 / 隧道效果</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#7B6BB5\" opacity=\".25\"/><ellipse cx=\"55\" cy=\"33\" rx=\"30\" ry=\"22\" fill=\"#F6F4FB\"/><circle cx=\"55\" cy=\"33\" r=\"11\" fill=\"#8A5FC0\"/></svg></span>用大面積、模糊的前景（花叢、欄杆、光斑）包住主角，形成<b>「透過某物看過去」的隧道感</b>。景深瞬間變深，也讓畫面更有偷窺般的故事性。</p></details>\n      <details><summary>視覺節奏與停頓</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"21\" width=\"8\" height=\"24\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".8\"/><rect x=\"23\" y=\"30\" width=\"8\" height=\"6\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".8\"/><rect x=\"36\" y=\"21\" width=\"8\" height=\"24\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".8\"/><rect x=\"49\" y=\"30\" width=\"8\" height=\"6\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".8\"/><rect x=\"62\" y=\"21\" width=\"8\" height=\"24\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".8\"/><rect x=\"75\" y=\"30\" width=\"8\" height=\"6\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".8\"/><rect x=\"88\" y=\"21\" width=\"8\" height=\"24\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".8\"/></svg></span>好構圖像音樂：<b>密集（細節多）與留白（停頓）要交錯</b>。全部塞滿會讓眼睛疲勞，適當的「空」是讓重點被聽見的休止符。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>構圖法則全覽 <span class=\"tag hot\">攝影 × 繪畫 × 設計</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\">同一條法則在三個領域的用法不同。左邊是攝影師怎麼用，中間是畫家怎麼用，右邊是設計師怎麼用。</p>\n    </div>\n    <div class=\"card\">\n      <h3>一、基本佈局 <span class=\"tag gold\">決定主角站在哪裡</span></h3>\n      <details><summary>三分法（九宮格）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".8\"><line x1=\"38\" y1=\"4\" x2=\"38\" y2=\"62\"/><line x1=\"73\" y1=\"4\" x2=\"73\" y2=\"62\"/><line x1=\"4\" y1=\"23\" x2=\"106\" y2=\"23\"/><line x1=\"4\" y1=\"43\" x2=\"106\" y2=\"43\"/></g><circle cx=\"73\" cy=\"23\" r=\"7\" fill=\"#8A5FC0\"/></svg></span><i><b>攝影</b>避免呆板的置中，把主體放在交點或沿線分佈，留出呼吸感。</i><i><b>繪畫</b>常用來劃分天空與地面、前景與遠景的比例，避免地平線把畫面一刀切。</i><i><b>設計</b>海報與網頁的隱形骨架；Logo、主標、按鈕壓在交點上引導閱讀動線。</i></p></details>\n      <details><summary>對稱構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"55\" y1=\"4\" x2=\"55\" y2=\"62\" stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".6\"/><circle cx=\"33\" cy=\"33\" r=\"12\" fill=\"#8A5FC0\"/><circle cx=\"77\" cy=\"33\" r=\"12\" fill=\"#8A5FC0\"/></svg></span><i><b>攝影</b>追求絕對平整的鏡像，多用於建築與倒影，傳達莊嚴與安寧。</i><i><b>繪畫</b>宗教畫、宮廷肖像的核心手法，用絕對對稱突出神權或王權的中心地位。</i><i><b>設計</b>高端品牌標誌、邀請函常用；書脊本身就是天然對稱軸，典雅而平衡。</i></p></details>\n      <details><summary>中心構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"55\" y1=\"6\" x2=\"55\" y2=\"60\" stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".5\"/><circle cx=\"55\" cy=\"33\" r=\"14\" fill=\"#8A5FC0\"/></svg></span><i><b>攝影</b>主體直接放正中央，強調力量、直接與莊重，常見於時尚肖像與極簡攝影。</i><i><b>繪畫</b>文藝復興的聖像構圖，把最重要的主角置於絕對中心，周圍元素環繞呼應。</i><i><b>設計</b>產品海報、唱片封面最愛，用最直白的方式讓主體成為唯一焦點，帶有宣言感。</i></p></details>\n      <details><summary>對角線構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"10\" y1=\"56\" x2=\"100\" y2=\"12\" stroke=\"#7B6BB5\" stroke-width=\"1.6\" stroke-dasharray=\"4 3\"/><circle cx=\"40\" cy=\"42\" r=\"8\" fill=\"#8A5FC0\"/><circle cx=\"72\" cy=\"26\" r=\"5\" fill=\"#8A5FC0\" opacity=\".55\"/></svg></span><i><b>攝影</b>傾斜線條貫穿畫面，打破靜止感，帶來速度、動感與延伸感。</i><i><b>繪畫</b>巴洛克時期的大對角線，把衝突、運動與戲劇性推向前方，視線順著斜線滑過全幅。</i><i><b>設計</b>傾斜的標題字、斜切色塊，能瞬間讓版面變活潑、有現代感與衝擊力。</i></p></details>\n      <details><summary>水平線構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"1.5\" opacity=\".75\"><line x1=\"6\" y1=\"22\" x2=\"104\" y2=\"22\"/><line x1=\"6\" y1=\"38\" x2=\"104\" y2=\"38\"/><line x1=\"6\" y1=\"52\" x2=\"104\" y2=\"52\"/></g></svg></span><i><b>攝影</b>拍草原、海平面，傳達平靜、遼闊、穩定與時間的靜止感。</i><i><b>繪畫</b>風景畫中層層疊加的水平線，區分前中遠景，建構最基礎的空間層次。</i><i><b>設計</b>橫幅 Banner、分欄佈局，用水平線劃分資訊區塊，讓閱讀節奏穩定清晰。</i></p></details>\n      <details><summary>垂直線構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"1.5\" opacity=\".75\"><line x1=\"26\" y1=\"6\" x2=\"26\" y2=\"60\"/><line x1=\"46\" y1=\"6\" x2=\"46\" y2=\"60\"/><line x1=\"66\" y1=\"6\" x2=\"66\" y2=\"60\"/><line x1=\"86\" y1=\"6\" x2=\"86\" y2=\"60\"/></g></svg></span><i><b>攝影</b>拍樹林、高樓、柱列，強化高度、力量、挺拔與整齊的秩序感。</i><i><b>繪畫</b>哥德式祭壇畫常見垂直延伸，藉站立人物與柱式把視線向上引導至天國。</i><i><b>設計</b>手機端長圖海報、豎版選單，垂直線條貼合閱讀方向，動線連貫順暢。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>二、線條引導 <span class=\"tag ok\">決定視線怎麼走</span></h3>\n      <details><summary>引導線構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"1.3\" opacity=\".75\"><line x1=\"6\" y1=\"60\" x2=\"50\" y2=\"30\"/><line x1=\"104\" y1=\"60\" x2=\"60\" y2=\"30\"/></g><circle cx=\"55\" cy=\"24\" r=\"9\" fill=\"#8A5FC0\"/></svg></span><i><b>攝影</b>利用道路、欄杆、河流等真實線條，把視線自然牽引到遠方的主體。</i><i><b>繪畫</b>刻意安排肢體、衣紋或矛戟的朝向，創造無形的「視線流」匯聚到主角身上。</i><i><b>設計</b>用箭頭、數字、模特兒的眼神當作視覺路標，帶讀者去看核心資訊。</i></p></details>\n      <details><summary>曲線構圖（S 形、C 形）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M20 60 C60 52 30 34 55 26 C78 18 60 10 92 8\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.8\"/></svg></span><i><b>攝影</b>蜿蜒的河流、盤山公路，讓視線緩慢柔和地穿梭，營造優雅流暢的縱深。</i><i><b>繪畫</b>洛可可的華麗曲線與人體姿態，用 S 形傳達豐腴、流動、嫵媚的韻律。</i><i><b>設計</b>時間軸設計、曲線排版，讓閱讀過程有起伏節奏，避開直線版面的單調。</i></p></details>\n      <details><summary>放射線構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"1.2\" opacity=\".8\"><line x1=\"55\" y1=\"33\" x2=\"6\" y2=\"8\"/><line x1=\"55\" y1=\"33\" x2=\"55\" y2=\"4\"/><line x1=\"55\" y1=\"33\" x2=\"104\" y2=\"8\"/><line x1=\"55\" y1=\"33\" x2=\"6\" y2=\"58\"/><line x1=\"55\" y1=\"33\" x2=\"55\" y2=\"62\"/><line x1=\"55\" y1=\"33\" x2=\"104\" y2=\"58\"/><line x1=\"55\" y1=\"33\" x2=\"4\" y2=\"33\"/><line x1=\"55\" y1=\"33\" x2=\"106\" y2=\"33\"/></g><circle cx=\"55\" cy=\"33\" r=\"6\" fill=\"#8A5FC0\"/></svg></span><i><b>攝影</b>從中心向四周發散的光線、花蕊、隧道口，產生強烈的匯聚或爆發感。</i><i><b>繪畫</b>文藝復興透視法的極致，所有消失線從滅點放射開來，把空間推到無限遠。</i><i><b>設計</b>促銷海報的放射狀背景，從標題向外擴張，製造爆炸性的視覺吸引力。</i></p></details>\n      <details><summary>螺旋線構圖（黃金螺旋）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M92 12 A40 40 0 0 1 92 52 A28 28 0 0 1 44 52 A18 18 0 0 1 62 34 A10 10 0 0 1 62 46\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.6\"/><circle cx=\"62\" cy=\"40\" r=\"4\" fill=\"#8A5FC0\"/></svg></span><i><b>攝影</b>把主體放在蝸牛殼般旋轉的末端，視線順螺旋環繞一圈後聚焦，極度和諧。</i><i><b>繪畫</b>古典大師經營群像的隱藏密碼，眾多人物沿螺旋軌跡分佈，雜而不亂。</i><i><b>設計</b>Logo 圖形、圓形標誌的內部結構，用黃金螺旋反覆微調比例，追求數學般的精確。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>三、形狀構圖 <span class=\"tag warn\">用幾何把元素綁在一起</span></h3>\n      <details><summary>三角形構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><polygon points=\"55,12 92,54 18,54\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.4\" stroke-dasharray=\"4 3\"/><circle cx=\"55\" cy=\"20\" r=\"7\" fill=\"#8A5FC0\"/><circle cx=\"26\" cy=\"49\" r=\"6\" fill=\"#8A5FC0\" opacity=\".6\"/><circle cx=\"84\" cy=\"49\" r=\"6\" fill=\"#8A5FC0\" opacity=\".6\"/></svg></span><i><b>攝影</b>多人合照時讓頭部連成三角形，畫面立刻緊密、穩固又自然。</i><i><b>繪畫</b>古典群像油畫的萬能公式：正三角穩如泰山，倒三角營造搖搖欲墜的緊張。</i><i><b>設計</b>視覺重心不穩時，在關鍵資訊旁加個小三角箭頭或幾何點綴，像秤砣一樣壓住版面。</i></p></details>\n      <details><summary>圓形構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"33\" r=\"24\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/><circle cx=\"55\" cy=\"33\" r=\"11\" fill=\"#8A5FC0\"/></svg></span><i><b>攝影</b>利用圓形洞口、窗戶框住主體，或拍旋轉對稱物體，視線在圓內迴圈流轉。</i><i><b>繪畫</b>曼陀羅、聖母子圓形畫；圓象徵永恆與完整，把注意力封閉在神聖空間中。</i><i><b>設計</b>App 圖標、徽章大量使用圓形，統一、聚焦，在任何方形版面中都極具辨識度。</i></p></details>\n      <details><summary>矩形／L 形構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M14 8 L14 58 L96 58\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"5\" opacity=\".35\"/><circle cx=\"60\" cy=\"34\" r=\"11\" fill=\"#8A5FC0\"/></svg></span><i><b>攝影</b>利用牆角、門框形成 L 形，或用明暗圍出一塊矩形，把視線框在重點上。</i><i><b>繪畫</b>室內景或建築畫用 L 形牆面與地面界定空間，同時留一邊讓視線逃逸、呼吸。</i><i><b>設計</b>圖文常沿 L 形排布：頂部橫排標題、左側豎排副文，既包圍主題又留出通透區塊。</i></p></details>\n      <details><summary>十字形構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"6\" y1=\"33\" x2=\"104\" y2=\"33\" stroke=\"#7B6BB5\" stroke-width=\"1.6\"/><line x1=\"55\" y1=\"4\" x2=\"55\" y2=\"62\" stroke=\"#7B6BB5\" stroke-width=\"1.6\"/><circle cx=\"55\" cy=\"33\" r=\"6\" fill=\"#8A5FC0\"/></svg></span><i><b>攝影</b>地平線與垂直的樹幹、燈柱相交，形成穩固的十字結構，安定且肅穆。</i><i><b>繪畫</b>宗教畫的十字形直接呼應十字架符號；即使是風景，也能用隱藏的十字軸線傳達靜穆。</i><i><b>設計</b>極簡海報一橫一豎的交叉，就能把複雜元素歸於秩序，構成最純粹的平衡。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>四、空間與層次 <span class=\"tag ok\">把平面變成空間</span></h3>\n      <details><summary>前景構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"30\" r=\"12\" fill=\"#8A5FC0\"/><path d=\"M2 66 C24 44 34 60 46 66 Z\" fill=\"#7B6BB5\" opacity=\".55\"/><path d=\"M108 66 C86 42 74 58 62 66 Z\" fill=\"#7B6BB5\" opacity=\".55\"/></svg></span><i><b>攝影</b>刻意在鏡頭前安排花草、石頭或虛化人影，增加二維照片的破層感與深度。</i><i><b>繪畫</b>用前景大塊深色剪影（樹影、門廊）把中景主角與遠景風景往後推好幾層。</i><i><b>設計</b>合成時在前方疊加虛化光斑、葉片，讓扁平素材瞬間有前中後的立體空間。</i></p></details>\n      <details><summary>框架式構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"16\" y=\"10\" width=\"78\" height=\"46\" rx=\"5\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"5\" opacity=\".35\"/><circle cx=\"55\" cy=\"33\" r=\"11\" fill=\"#8A5FC0\"/></svg></span><i><b>攝影</b>透過門窗、拱門、樹洞拍遠方景物，形成戲中戲的窺視感，隔絕周邊雜亂。</i><i><b>繪畫</b>在肖像背景畫一扇窗或拱門，不只框住人物，更暗示了室內外兩個空間的故事關係。</i><i><b>設計</b>彈出視窗、縮圖預覽本身就是「框」的邏輯，區隔層級，讓你在複雜資訊中聚焦。</i></p></details>\n      <details><summary>留白構圖（負空間）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"86\" cy=\"33\" r=\"10\" fill=\"#8A5FC0\"/><rect x=\"8\" y=\"8\" width=\"56\" height=\"50\" rx=\"5\" fill=\"#7B6BB5\" opacity=\".08\"/></svg></span><i><b>攝影</b>大面積天空、水面、白牆，主體極小，營造極簡、孤獨、空靈的氣氛。</i><i><b>繪畫</b>水墨畫的「計白當黑」：沒畫的地方可能是雲、是水、是天，更是意境延伸之處。</i><i><b>設計</b>奢侈品廣告的大面積留白就是高級感本身，也是讓核心文字被瞬間看到的呼吸帶。</i></p></details>\n      <details><summary>填滿畫面構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"34\" fill=\"#8A5FC0\"/></svg></span><i><b>攝影</b>超近特寫或微距，讓主體充滿甚至衝破邊框，剝奪背景，帶來壓迫或親密感。</i><i><b>繪畫</b>超寫實肖像的毛孔與髮絲填滿畫面，消除距離，迫使觀眾進行幾乎不適的對視。</i><i><b>設計</b>雜誌封面的近臉特寫、產品細節放大，用溢出邊框的張力營造「就在你眼前」。</i></p></details>\n      <details><summary>圖層疊加構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"14\" y=\"12\" width=\"52\" height=\"42\" rx=\"4\" fill=\"#8A5FC0\" opacity=\".55\"/><rect x=\"44\" y=\"22\" width=\"52\" height=\"34\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".45\"/></svg></span><i><b>攝影</b>利用玻璃反光、雙重曝光，把不同空間的景物壓縮在同一畫面，虛實交疊。</i><i><b>繪畫</b>透明油彩層層罩染，底色透過薄塗隱約顯現，產生攝影無法複製的微妙光澤。</i><i><b>設計</b>半透明色塊疊在圖片上、文字壓在色塊上，既保住圖片氛圍又確保文字可讀。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>五、動態與張力 <span class=\"tag hot\">讓畫面不安分</span></h3>\n      <details><summary>傾斜構圖（荷蘭角）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"6\" y1=\"46\" x2=\"104\" y2=\"20\" stroke=\"#7B6BB5\" stroke-width=\"1.8\"/><rect x=\"42\" y=\"14\" width=\"16\" height=\"26\" rx=\"3\" fill=\"#8A5FC0\" transform=\"rotate(-15 50 27)\"/></svg></span><i><b>攝影</b>故意讓水平線歪斜，製造不安、失重、混亂與緊張，常見於電影與街拍。</i><i><b>繪畫</b>表現主義、未來主義用傾斜的筆觸與構圖，傳達情緒躁動或都市的高速眩暈。</i><i><b>設計</b>運動品牌、街頭潮牌海報，傾斜排版注入強烈的動態能量與叛逆感。</i></p></details>\n      <details><summary>圖案與打破圖案</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#7B6BB5\" opacity=\".7\"><rect x=\"12\" y=\"14\" width=\"14\" height=\"14\" rx=\"3\"/><rect x=\"32\" y=\"14\" width=\"14\" height=\"14\" rx=\"3\"/><rect x=\"52\" y=\"14\" width=\"14\" height=\"14\" rx=\"3\"/><rect x=\"72\" y=\"14\" width=\"14\" height=\"14\" rx=\"3\"/><rect x=\"12\" y=\"38\" width=\"14\" height=\"14\" rx=\"3\"/><rect x=\"32\" y=\"38\" width=\"14\" height=\"14\" rx=\"3\"/><rect x=\"72\" y=\"38\" width=\"14\" height=\"14\" rx=\"3\"/></g><rect x=\"52\" y=\"38\" width=\"14\" height=\"14\" rx=\"3\" fill=\"#E08A3C\"/></svg></span><i><b>攝影</b>一片整齊的窗戶或椅子中，突然有一個顏色不同、方向相反的元素，立刻成為視覺炸彈。</i><i><b>繪畫</b>普普藝術最愛的重複排列，然後在規律矩陣中插入異類，用重複凸顯差異。</i><i><b>設計</b>整齊的圖標陣列中讓重點款跳色或放大，利用規律「被打破」精準引導點擊。</i></p></details>\n      <details><summary>視線引導構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"34\" cy=\"33\" r=\"12\" fill=\"#8A5FC0\"/><g stroke=\"#7B6BB5\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\"><line x1=\"48\" y1=\"30\" x2=\"96\" y2=\"26\"/></g><rect x=\"60\" y=\"8\" width=\"42\" height=\"50\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".08\"/></svg></span><i><b>攝影</b>拍人物或動物時，在視線朝向的一方多留空間，觀眾會不由自主順著看過去。</i><i><b>繪畫</b>群像畫中所有人物的視線構成隱形網絡，畫家藉此告訴你誰才是真正的主角。</i><i><b>設計</b>Banner 中模特兒的眼神直接望向文案或按鈕，是點擊率最高的視線誘導術。</i></p></details>\n      <details><summary>視覺張力構圖（邊緣張力）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"14\" cy=\"33\" r=\"11\" fill=\"#8A5FC0\"/><rect x=\"34\" y=\"8\" width=\"68\" height=\"50\" rx=\"5\" fill=\"#7B6BB5\" opacity=\".07\"/></svg></span><i><b>攝影</b>把主體推到畫面極邊緣，中央大面積放空，用不平衡創造極強的心理張力。</i><i><b>繪畫</b>主角緊貼畫框邊緣、留下大片空白，彷彿下一秒就要被擠出畫面或闖入未知。</i><i><b>設計</b>把核心文案放在海報角落，違反舒適區，反而能激起年輕族群的好奇與叛逆認同。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>六、特殊與實驗 <span class=\"tag gold\">先懂規則，再打破它</span></h3>\n      <details><summary>散點透視構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.2\"><rect x=\"10\" y=\"12\" width=\"22\" height=\"16\" rx=\"3\"/><rect x=\"44\" y=\"30\" width=\"22\" height=\"16\" rx=\"3\"/><rect x=\"76\" y=\"14\" width=\"22\" height=\"16\" rx=\"3\"/><rect x=\"24\" y=\"44\" width=\"22\" height=\"14\" rx=\"3\"/></g></svg></span><i><b>攝影</b>接圖或移軸刻意消除單一滅點，遠近都清晰，營造微縮模型或扁平化的超現實感。</i><i><b>繪畫</b>中國長卷山水的核心透視法，不固定視點而是步步移、面面觀，把不同時空並置於同一幅。</i><i><b>設計</b>資訊圖表、插畫式地圖沒有統一透視，每個圖標都以最清晰的角度呈現，服務說明而非仿真。</i></p></details>\n      <details><summary>底片留邊構圖（畫框中的畫框）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"6\" width=\"94\" height=\"54\" rx=\"3\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"4\" opacity=\".45\"/><rect x=\"20\" y=\"14\" width=\"70\" height=\"38\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".25\"/><circle cx=\"55\" cy=\"33\" r=\"9\" fill=\"#8A5FC0\"/></svg></span><i><b>攝影</b>故意拍下膠片齒孔、拍立得白框，或利用螢幕取景框，強調「這是個被觀看的影像」。</i><i><b>繪畫</b>畫中畫的後設手法，如委拉斯蓋茲《宮娥》把畫布、鏡子、門框全部框入，提問真實與虛構。</i><i><b>設計</b>在版面中模擬拍立得邊框或瀏覽器截圖，創造隨手記錄的真實感或復古情懷。</i></p></details>\n      <details><summary>隨機／有機構圖（去構圖化）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#8A5FC0\" opacity=\".6\"><circle cx=\"24\" cy=\"20\" r=\"7\"/><circle cx=\"70\" cy=\"14\" r=\"5\"/><circle cx=\"44\" cy=\"42\" r=\"9\"/><circle cx=\"88\" cy=\"46\" r=\"6\"/><circle cx=\"16\" cy=\"50\" r=\"4\"/></g></svg></span><i><b>攝影</b>街拍中的無心之眼，看似隨手拍、沒有明確主體，卻捕捉到渾然天成的混雜詩意。</i><i><b>繪畫</b>抽象表現主義的滴灑，波拉克讓顏料自由落下，徹底放棄構圖，讓作品成為能量場的紀錄。</i><i><b>設計</b>解構主義海報讓文字碎片化、重疊、亂序，故意不讓你舒服地讀，用反構圖表達態度。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <p class=\"cond\" style=\"margin:0\">以上每一條都不是死板的教條，而是理解視覺邏輯的工具。上方「開始分析」會自動辨識其中十餘種型態並標出吻合程度——掌握了全部，你就可以隨心所欲地運用，甚至故意打破它們來創造新的表達。</p>\n    </div>\n", "ae-prin": "\n    <div class=\"card\">\n      <h3>格式塔圖解 <span class=\"tag ok\">大腦怎麼分組</span></h3>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"22\" cy=\"32\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"36\" cy=\"32\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"29\" cy=\"48\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"22\" cy=\"64\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"36\" cy=\"64\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"84\" cy=\"32\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"98\" cy=\"32\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"91\" cy=\"48\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"84\" cy=\"64\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"98\" cy=\"64\" r=\"5\" fill=\"#7B6BB5\"/></svg></div><figcaption>接近性：靠近＝同一組</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"24\" cy=\"28\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"48\" cy=\"28\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"72\" cy=\"28\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"96\" cy=\"28\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"24\" cy=\"62\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"72\" cy=\"62\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"96\" cy=\"62\" r=\"5\" fill=\"#7B6BB5\"/><rect x=\"42\" y=\"56\" width=\"12\" height=\"12\" rx=\"2\" fill=\"#8A5FC0\"/></svg></div><figcaption>相似性：不同的那個＝強調</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"4\" stroke-linecap=\"round\"><path d=\"M60 20 A25 25 0 0 1 85 45\"/><path d=\"M85 45 A25 25 0 0 1 60 70\"/><path d=\"M60 70 A25 25 0 0 1 35 45\"/></g><text x=\"47\" y=\"49\" font-size=\"8\" fill=\"#DDD6E8\">?</text></svg></div><figcaption>閉合性：缺口會被自動補完</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M8 70 Q60 8 112 70\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.4\" stroke-dasharray=\"3 3\" opacity=\".6\"/><circle cx=\"14\" cy=\"64\" r=\"4\" fill=\"#8A5FC0\"/><circle cx=\"34\" cy=\"40\" r=\"4\" fill=\"#8A5FC0\"/><circle cx=\"60\" cy=\"26\" r=\"4\" fill=\"#8A5FC0\"/><circle cx=\"86\" cy=\"40\" r=\"4\" fill=\"#8A5FC0\"/><circle cx=\"106\" cy=\"64\" r=\"4\" fill=\"#8A5FC0\"/></svg></div><figcaption>連續性：視線沿線前進</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"8\" width=\"104\" height=\"74\" rx=\"6\" fill=\"#2A2138\"/><circle cx=\"60\" cy=\"45\" r=\"20\" fill=\"#F6F4FB\"/></svg></div><figcaption>圖與地：對比足才分得出主體</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"2\" stroke-linecap=\"round\" opacity=\".8\"><path d=\"M18 26 l14 8\"/><path d=\"M18 46 l14 8\"/><path d=\"M18 66 l14 8\"/><path d=\"M58 22 l14 8\"/><path d=\"M58 42 l14 8\"/><path d=\"M58 62 l14 8\"/></g><text x=\"86\" y=\"49\" font-size=\"9\" fill=\"#8A5FC0\">→</text></svg></div><figcaption>共同命運：同向＝一體</figcaption></figure>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3>美的形式原理 <span class=\"tag gold\">設計的共同語言</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">所有「好看」的東西幾乎都逃不出這幾條原理。搭配、排版、構圖通用。</p>\n      <details><summary>統一與變化</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"24\" cy=\"24\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"40\" cy=\"24\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"56\" cy=\"24\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"24\" cy=\"42\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"40\" cy=\"42\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"56\" cy=\"42\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"82\" cy=\"33\" r=\"8\" fill=\"#B8892E\"/></svg></span><b>最核心的一條。</b>統一＝有共同元素（同色系、同材質、同風格）讓畫面整齊；變化＝加入差異避免無聊。<br>只有統一 → 單調；只有變化 → 雜亂。正解是<b>大統一、小變化</b>：主色調統一，用一兩個亮點做變化。</p></details>\n      <details><summary>平衡</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"38\" cy=\"34\" r=\"12\" fill=\"#8A5FC0\"/><circle cx=\"80\" cy=\"34\" r=\"12\" fill=\"#8A5FC0\"/><line x1=\"59\" y1=\"8\" x2=\"59\" y2=\"58\" stroke=\"#DDD6E8\" stroke-dasharray=\"3 3\"/></svg></span><b>對稱平衡</b>：左右一樣，莊重、正式、古典（適合禮服、王冠、教堂背景）。<br><b>非對稱平衡</b>：兩邊不同但視覺重量相等，活潑自然、更現代。<br><b>放射平衡</b>：從中心向外擴散，強調中心點，華麗感強。</p></details>\n      <details><summary>比例（黃金比例・三分）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"20\" y=\"12\" width=\"70\" height=\"16\" rx=\"3\" fill=\"#7B6BB5\" opacity=\".4\"/><rect x=\"20\" y=\"30\" width=\"70\" height=\"30\" rx=\"3\" fill=\"#8A5FC0\"/></svg></span>黃金比例約 <b>1:1.618</b>，被認為最舒服的分割比。實務上用<b>三分法（1:2）</b>近似即可。服裝上下身、頭身比、留白與主體的面積比，都可以套。</p></details>\n      <details><summary>節奏與韻律</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"18\" cy=\"33\" r=\"4.0\" fill=\"#8A5FC0\" opacity=\".8\"/><circle cx=\"33\" cy=\"33\" r=\"5.4\" fill=\"#8A5FC0\" opacity=\".8\"/><circle cx=\"48\" cy=\"33\" r=\"6.8\" fill=\"#8A5FC0\" opacity=\".8\"/><circle cx=\"63\" cy=\"33\" r=\"8.2\" fill=\"#8A5FC0\" opacity=\".8\"/><circle cx=\"78\" cy=\"33\" r=\"9.6\" fill=\"#8A5FC0\" opacity=\".8\"/><circle cx=\"93\" cy=\"33\" r=\"11.0\" fill=\"#8A5FC0\" opacity=\".8\"/></svg></span>同樣元素<b>重複</b>出現形成節奏（例：一排蕾絲、連續的蝴蝶）；大小或顏色<b>漸變</b>形成韻律（例：花朵由大到小散開）。能讓視線流動起來，是華麗系搭配的關鍵。</p></details>\n      <details><summary>對比</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#2A2138\"/><circle cx=\"55\" cy=\"33\" r=\"13\" fill=\"#F3E9C0\"/></svg></span>製造差異來凸顯重點——<b>明暗、冷暖、大小、疏密、粗細、動靜</b>。畫面平淡通常就是對比不足；<b>暗背景 + 亮主角</b>是最快見效的解法。</p></details>\n      <details><summary>調和</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"14\" y=\"22\" width=\"15\" height=\"22\" rx=\"3\" fill=\"#6E5FA8\"/><rect x=\"31\" y=\"22\" width=\"15\" height=\"22\" rx=\"3\" fill=\"#7E6FB4\"/><rect x=\"48\" y=\"22\" width=\"15\" height=\"22\" rx=\"3\" fill=\"#8E80C0\"/><rect x=\"65\" y=\"22\" width=\"15\" height=\"22\" rx=\"3\" fill=\"#9E90CC\"/><rect x=\"82\" y=\"22\" width=\"15\" height=\"22\" rx=\"3\" fill=\"#AEA0D8\"/></svg></span>對比的反面：讓元素<b>彼此接近</b>而和諧。相鄰色（藍＋藍紫）、同材質、同明度都能製造調和。太多對比時，就靠調和收回來。</p></details>\n      <details><summary>強調（主從關係）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"24\" cy=\"24\" r=\"5\" fill=\"#DDD6E8\"/><circle cx=\"44\" cy=\"24\" r=\"5\" fill=\"#DDD6E8\"/><circle cx=\"86\" cy=\"24\" r=\"5\" fill=\"#DDD6E8\"/><circle cx=\"24\" cy=\"44\" r=\"5\" fill=\"#DDD6E8\"/><circle cx=\"44\" cy=\"44\" r=\"5\" fill=\"#DDD6E8\"/><circle cx=\"86\" cy=\"44\" r=\"5\" fill=\"#DDD6E8\"/><circle cx=\"65\" cy=\"34\" r=\"9\" fill=\"#8A5FC0\"/></svg></span>一張畫面<b>只能有一個主角</b>。決定誰是主角後，其他元素都要退讓——降低彩度、縮小、模糊、移到邊緣。什麼都想強調＝什麼都不突出。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>少即是多 <span class=\"tag hot\">Less is More</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">建築師密斯・凡德羅的名言。<b>不是東西越少越好，而是「每一樣都必須有存在的理由」</b>——刪到不能再刪，剩下的才有力量。</p>\n      <ul class=\"tips\">\n        <li><b>為什麼有效</b>元素越少，每個元素分到的<b>注意力越多</b>；畫面越乾淨，主角越響亮。</li>\n        <li><b>怎麼判斷該刪</b>問自己：拿掉它，訊息會變弱嗎？不會 → 刪。<b>可有可無＝該刪</b>。</li>\n        <li><b>克制的三處</b>①配件數量　②顏色數量（建議 3 色以內）　③字體數量（2 種以內）。</li>\n        <li><b>留白不是浪費</b>空白是設計的一部分，它讓主角有呼吸空間、讓畫面顯得高級。</li>\n        <li><b>但要避免「空洞」</b>少 ≠ 隨便。剩下的元素必須<b>質感更好、位置更準</b>，否則只是簡陋。</li>\n        <li><b>相對的一句</b>Less is a bore（少即無聊）——後現代對它的反擊。<b>華麗堆疊也是一種美</b>，只是需要更強的統一與秩序來撐住。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>格式塔理論 <span class=\"tag hot\">Gestalt Principles</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">德文 Gestalt ＝「整體形態」。核心主張：<b>整體大於部分的總和</b>——人腦會自動把零散元素<b>組織成有意義的整體</b>。這是所有版面與構圖的心理學基礎。</p>\n      <details><summary>接近性 Proximity</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"20\" cy=\"24\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"32\" cy=\"24\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"26\" cy=\"42\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"78\" cy=\"24\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"90\" cy=\"24\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"84\" cy=\"42\" r=\"4\" fill=\"#7B6BB5\"/></svg></span><b>靠得近的東西會被視為一組。</b>這是最強的分組力量——比顏色、比外框都強。<br>應用：想讓兩件事有關聯，就把它們放近；想切開，就拉開距離。版面亂，往往是<b>該近的不夠近、該遠的不夠遠</b>。</p></details>\n      <details><summary>相似性 Similarity</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"22\" cy=\"26\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"42\" cy=\"26\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"62\" cy=\"26\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"82\" cy=\"26\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"22\" cy=\"46\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"62\" cy=\"46\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"82\" cy=\"46\" r=\"4\" fill=\"#7B6BB5\"/><rect x=\"37\" y=\"41\" width=\"10\" height=\"10\" rx=\"2\" fill=\"#8A5FC0\"/></svg></span><b>長得像的東西會被視為同一類</b>（相同顏色、形狀、大小、方向）。<br>應用：用同一個顏色標記同類項目；反過來，<b>打破相似＝製造強調</b>（一片白花中的一朵紅花）。</p></details>\n      <details><summary>閉合性 Closure</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"4\" stroke-linecap=\"round\"><path d=\"M55 16 A18 18 0 0 1 73 34\"/><path d=\"M73 34 A18 18 0 0 1 55 52\"/><path d=\"M55 52 A18 18 0 0 1 37 34\"/></g></svg></span><b>大腦會自動補完缺口</b>，把不完整的形狀看成完整的。<br>應用：不必畫完整個輪廓，留白反而更高級（很多 logo 就是這樣設計的）。人物被前景遮住一部分，觀者仍能自動補全。</p></details>\n      <details><summary>連續性 Continuity</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M6 54 Q55 8 104 54\" fill=\"none\" stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".6\"/><circle cx=\"12\" cy=\"50\" r=\"3.4\" fill=\"#8A5FC0\"/><circle cx=\"34\" cy=\"28\" r=\"3.4\" fill=\"#8A5FC0\"/><circle cx=\"55\" cy=\"20\" r=\"3.4\" fill=\"#8A5FC0\"/><circle cx=\"76\" cy=\"28\" r=\"3.4\" fill=\"#8A5FC0\"/><circle cx=\"98\" cy=\"50\" r=\"3.4\" fill=\"#8A5FC0\"/></svg></span><b>視線會沿著線條或曲線持續前進</b>，即使線斷了也會自動接上。<br>應用：這就是「引導線」的心理學原理；元素排成一條隱形線，視線就會照著走。</p></details>\n      <details><summary>共同命運 Common Fate</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"2\" stroke-linecap=\"round\" opacity=\".8\"><path d=\"M16 20 l12 6\"/><path d=\"M16 34 l12 6\"/><path d=\"M16 48 l12 6\"/><path d=\"M52 20 l12 6\"/><path d=\"M52 34 l12 6\"/></g><text x=\"82\" y=\"39\" font-size=\"11\" fill=\"#8A5FC0\">→</text></svg></span><b>朝同一方向移動（或指向）的元素會被視為一組。</b><br>應用：飄向同一方向的花瓣、髮絲、裙擺，會讓畫面產生統一的動勢；讓所有元素「順著同一股風」，畫面立刻有整體感。</p></details>\n      <details><summary>圖與地 Figure–Ground</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#2A2138\"/><circle cx=\"55\" cy=\"33\" r=\"16\" fill=\"#F6F4FB\"/></svg></span><b>人腦會自動把畫面分成「主體（圖）」與「背景（地）」。</b>對比不足時大腦會混淆，主角就會「沉」進背景。<br>應用：確保主角與背景在<b>明度、彩度或清晰度</b>至少一項有明顯差異。著名的<b>魯賓花瓶</b>（可看成花瓶也可看成兩張臉）就是圖地反轉。</p></details>\n      <details><summary>簡潔法則 Prägnanz（好形）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"33\" r=\"15\" fill=\"#8A5FC0\"/></svg></span>格式塔的總原則：<b>人會用最簡單、最穩定的方式解讀所看到的東西。</b><br>應用：越簡潔的形狀越容易被記住、越舒服。這就是<b>「少即是多」的科學根據</b>——複雜的畫面會增加大腦負擔。</p></details>\n      <details><summary>對稱性 Symmetry</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"55\" y1=\"6\" x2=\"55\" y2=\"60\" stroke=\"#DDD6E8\" stroke-dasharray=\"3 3\"/><circle cx=\"38\" cy=\"33\" r=\"10\" fill=\"#8A5FC0\"/><circle cx=\"72\" cy=\"33\" r=\"10\" fill=\"#8A5FC0\"/></svg></span><b>對稱的元素會被視為一組、且令人感到穩定完整。</b><br>應用：對稱帶來莊嚴與秩序（適合禮服、王座、教堂）；但要小心過度對稱＝呆板，可用<b>細節不對稱</b>來破。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>形式原理圖解 <span class=\"tag ok\">平衡・對比・比例</span></h3>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 82\"><rect width=\"120\" height=\"82\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"6\" x2=\"60\" y2=\"76\" stroke=\"#DDD6E8\" stroke-dasharray=\"2 3\"/><circle cx=\"40\" cy=\"45\" r=\"14\" fill=\"#8A5FC0\"/><circle cx=\"80\" cy=\"45\" r=\"14\" fill=\"#8A5FC0\"/><text x=\"8\" y=\"76\" font-size=\"10\" fill=\"#2A2138\">對稱・莊重</text></svg></div><figcaption>對稱平衡</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 82\"><rect width=\"120\" height=\"82\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"6\" x2=\"60\" y2=\"76\" stroke=\"#DDD6E8\" stroke-dasharray=\"2 3\"/><circle cx=\"38\" cy=\"45\" r=\"18\" fill=\"#8A5FC0\"/><circle cx=\"86\" cy=\"38\" r=\"7\" fill=\"#8A5FC0\"/><circle cx=\"82\" cy=\"58\" r=\"5\" fill=\"#7B6BB5\"/><text x=\"8\" y=\"76\" font-size=\"10\" fill=\"#2A2138\">非對稱・活潑</text></svg></div><figcaption>非對稱平衡</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 82\"><rect width=\"120\" height=\"82\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"6\" x2=\"60\" y2=\"76\" stroke=\"#DDD6E8\" stroke-dasharray=\"2 3\"/><circle cx=\"82.0\" cy=\"45.0\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"71.0000168525543\" cy=\"64.05254915342096\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"49.00003370513441\" cy=\"64.05257834288632\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"38.000000000077456\" cy=\"45.00005837897546\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"48.99993258983446\" cy=\"25.947480036178575\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"70.99991573709944\" cy=\"25.947392467782475\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"60\" cy=\"45\" r=\"9\" fill=\"#8A5FC0\"/><text x=\"8\" y=\"76\" font-size=\"10\" fill=\"#2A2138\">放射・聚焦中心</text></svg></div><figcaption>放射平衡</figcaption></figure></div>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 200 70\"><rect width=\"200\" height=\"70\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<rect x=\"8\" y=\"12\" width=\"86\" height=\"46\" rx=\"5\" fill=\"#CFC7E0\"/><circle cx=\"51\" cy=\"35\" r=\"10\" fill=\"#C3BAD8\"/><text x=\"14\" y=\"24\" font-size=\"9\" fill=\"#8880A0\">✗ 對比不足・糊在一起</text>\n<rect x=\"106\" y=\"12\" width=\"86\" height=\"46\" rx=\"5\" fill=\"#22182E\"/><circle cx=\"149\" cy=\"35\" r=\"10\" fill=\"#F3ECFA\"/><text x=\"112\" y=\"24\" font-size=\"9\" fill=\"#B0A6C8\">✓ 暗底＋亮主角</text></svg></div><figcaption>對比：暗背景＋亮主角，最快見效</figcaption></figure>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 200 60\"><rect width=\"200\" height=\"60\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<rect x=\"8\" y=\"16\" width=\"88\" height=\"28\" rx=\"4\" fill=\"#D6CEE8\"/><line x1=\"52\" y1=\"16\" x2=\"52\" y2=\"44\" stroke=\"#C0554E\" stroke-width=\"2\"/><text x=\"14\" y=\"55\" font-size=\"9\" fill=\"#C0554E\">✗ 對半分・呆板</text>\n<rect x=\"106\" y=\"16\" width=\"88\" height=\"28\" rx=\"4\" fill=\"#D6CEE8\"/><line x1=\"164\" y1=\"16\" x2=\"164\" y2=\"44\" stroke=\"#3D8E8A\" stroke-width=\"2\"/><text x=\"112\" y=\"55\" font-size=\"9\" fill=\"#3D8E8A\">✓ 1:2（三分）・有張力</text></svg></div><figcaption>比例：放在 1/3 處比對半分更有張力</figcaption></figure>\n    </div>\n    <div class=\"card\">\n      <h3>形式原理圖解・其二 <span class=\"tag ok\">圖地・比例</span></h3>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"10\" x2=\"60\" y2=\"72\" stroke=\"#DDD6E8\" stroke-dasharray=\"3 3\"/><circle cx=\"38\" cy=\"40\" r=\"13\" fill=\"#8A5FC0\"/><circle cx=\"82\" cy=\"40\" r=\"13\" fill=\"#8A5FC0\"/><text x=\"60\" y=\"84\" font-size=\"9.5\" fill=\"#2A2138\" text-anchor=\"middle\">對稱・莊重</text></svg></div><figcaption>對稱平衡</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"10\" x2=\"60\" y2=\"72\" stroke=\"#DDD6E8\" stroke-dasharray=\"3 3\"/><circle cx=\"36\" cy=\"40\" r=\"16\" fill=\"#8A5FC0\"/><circle cx=\"86\" cy=\"34\" r=\"7\" fill=\"#7B6BB5\"/><circle cx=\"88\" cy=\"52\" r=\"5\" fill=\"#7B6BB5\"/><text x=\"60\" y=\"84\" font-size=\"9.5\" fill=\"#2A2138\" text-anchor=\"middle\">非對稱・活潑</text></svg></div><figcaption>非對稱平衡</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"10\" x2=\"60\" y2=\"72\" stroke=\"#DDD6E8\" stroke-dasharray=\"3 3\"/><line x1=\"60\" y1=\"40\" x2=\"88.0\" y2=\"40.0\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><line x1=\"60\" y1=\"40\" x2=\"79.79898987322333\" y2=\"59.79898987322333\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><line x1=\"60\" y1=\"40\" x2=\"60.0\" y2=\"68.0\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><line x1=\"60\" y1=\"40\" x2=\"40.20101012677667\" y2=\"59.798989873223334\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><line x1=\"60\" y1=\"40\" x2=\"32.0\" y2=\"40.0\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><line x1=\"60\" y1=\"40\" x2=\"40.201010126776666\" y2=\"20.201010126776673\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><line x1=\"60\" y1=\"40\" x2=\"59.99999999999999\" y2=\"12.0\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><line x1=\"60\" y1=\"40\" x2=\"79.79898987322332\" y2=\"20.201010126776666\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><circle cx=\"60\" cy=\"40\" r=\"8\" fill=\"#8A5FC0\"/><text x=\"60\" y=\"84\" font-size=\"9.5\" fill=\"#2A2138\" text-anchor=\"middle\">放射・華麗</text></svg></div><figcaption>放射平衡</figcaption></figure></div>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#2A2138\"/><circle cx=\"60\" cy=\"42\" r=\"15\" fill=\"#F3E9C0\"/><text x=\"60\" y=\"80\" font-size=\"9.5\" fill=\"#fff\" text-anchor=\"middle\">對比・暗襯亮</text></svg></div><figcaption>對比</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<rect x=\"20\" y=\"14\" width=\"80\" height=\"20\" rx=\"3\" fill=\"#7B6BB5\" opacity=\".4\"/><rect x=\"20\" y=\"36\" width=\"80\" height=\"40\" rx=\"3\" fill=\"#8A5FC0\"/>\n<text x=\"60\" y=\"86\" font-size=\"9.5\" fill=\"#2A2138\" text-anchor=\"middle\">比例・1:2 三分</text></svg></div><figcaption>比例</figcaption></figure></div>\n    </div>\n    <div class=\"card\">\n      <h3>進階形式原理 <span class=\"tag gold\">高手在用</span></h3>\n      <details><summary>張力 Tension</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"40\" cy=\"33\" r=\"14\" fill=\"#8A5FC0\"/><circle cx=\"72\" cy=\"33\" r=\"14\" fill=\"#7B6BB5\"/><line x1=\"55\" y1=\"20\" x2=\"55\" y2=\"46\" stroke=\"#C0554E\" stroke-dasharray=\"2 2\" opacity=\".5\"/></svg></span>把元素放在<b>快要碰到卻沒碰到</b>、或快要出界的位置，會產生一種心理張力，讓畫面「活」起來。安全的正中央最沒張力；<b>刻意的不平衡</b>反而更抓人。</p></details>\n      <details><summary>動勢 Movement / 導引</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M14 50 Q55 10 98 40\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"2.4\" marker-end=\"url(#am)\"/><defs><marker id=\"am\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\"><path d=\"M0 0 L7 3.5 L0 7 z\" fill=\"#8A5FC0\"/></marker></defs></svg></span>透過方向性元素（傾斜線、視線、伸出的手、飄動的布）製造<b>「看不見的箭頭」</b>，牽著觀者的視線在畫面裡移動。靜止的圖也能有流動感。</p></details>\n      <details><summary>層次與景深 Depth</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"24\" width=\"90\" height=\"30\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".25\"/><rect x=\"26\" y=\"30\" width=\"60\" height=\"24\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".5\"/><rect x=\"44\" y=\"34\" width=\"24\" height=\"24\" rx=\"5\" fill=\"#8A5FC0\"/></svg></span>前景、中景、背景三層各有內容，並用<b>虛實、明暗、冷暖、大小</b>拉開距離。平面因此有了「進得去」的空間感——這是業餘與專業最明顯的差距之一。</p></details>\n      <details><summary>質感對比 Texture contrast</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"16\" width=\"44\" height=\"34\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".3\"/><rect x=\"58\" y=\"16\" width=\"44\" height=\"34\" rx=\"4\" fill=\"#2A2138\"/></svg></span>粗與細、光滑與粗糙、硬與軟並置，能大幅增加畫面的豐富度與觸覺感。全部同一種質感會顯得平；<b>一個對比質感就能救活整個畫面</b>。</p></details>\n      <details><summary>簡化與取捨 Simplification</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"33\" r=\"12\" fill=\"#8A5FC0\"/></svg></span>設計的一半是「決定放什麼」，另一半是<b>「決定拿掉什麼」</b>。好作品往往不是加出來的，而是<b>減出來的</b>——留下最能表達主題的，其餘忍痛捨去。</p></details>\n      <details><summary>格式塔的「群組化」實作</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"22\" cy=\"26\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"33\" cy=\"26\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"44\" cy=\"26\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"70\" cy=\"44\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"81\" cy=\"44\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"92\" cy=\"44\" r=\"4\" fill=\"#7B6BB5\"/></svg></span>把畫面元素<b>刻意分成 2～3 個群組</b>（用接近、相似、共同框住），比一堆散落的元素好讀得多。眼睛喜歡「塊」，不喜歡「碎」。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>十大形式原理 <span class=\"tag hot\">為什麼這樣安排會覺得美</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\">構圖是「怎麼安排元素」的具體方法，形式原理是這些方法背後共通的底層邏輯。上面所有的構圖法，本質上都是這十項原理的排列組合。每條一樣分攝影／繪畫／設計三個角度看。</p>\n    </div>\n    <div class=\"card\">\n      <h3>十大形式原理 <span class=\"tag gold\">十項全展開</span></h3>\n      <details><summary>1. 反覆與重複</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#8A5FC0\" opacity=\".75\"><rect x=\"12\" y=\"22\" width=\"12\" height=\"22\" rx=\"3\"/><rect x=\"31\" y=\"22\" width=\"12\" height=\"22\" rx=\"3\"/><rect x=\"50\" y=\"22\" width=\"12\" height=\"22\" rx=\"3\"/><rect x=\"69\" y=\"22\" width=\"12\" height=\"22\" rx=\"3\"/><rect x=\"88\" y=\"22\" width=\"12\" height=\"22\" rx=\"3\"/></g></svg></span><b class=\"fp-lede\">相同或相似的形狀、色彩、線條，有規律地連續出現。</b><i><b>攝影</b>整排的路燈、窗戶、椅子，透過規律排列產生視覺節奏感。</i><i><b>繪畫</b>點描派的無數小色點、裝飾畫的連續圖案，用重複筆觸建立畫面的肌理密度。</i><i><b>設計</b>網站按鈕風格統一、包裝上的連續印花，讓視覺語言一致，降低認知負擔。</i></p></details>\n      <details><summary>2. 漸變</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><defs><linearGradient id=\"fpg\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\"><stop offset=\"0\" stop-color=\"#8A5FC0\"/><stop offset=\"1\" stop-color=\"#8A5FC0\" stop-opacity=\".08\"/></linearGradient></defs><rect x=\"6\" y=\"14\" width=\"98\" height=\"38\" rx=\"4\" fill=\"url(#fpg)\"/></svg></span><b class=\"fp-lede\">元素在大小、色彩、疏密、明暗上，呈現逐步變化的過程。</b><i><b>攝影</b>夕陽天空從橙紅到深藍的色階、道路兩旁路燈由近到遠越來越小。</i><i><b>繪畫</b>水墨畫的「墨分五色」、透視法中物體越遠越淡的空氣透視，都是漸變。</i><i><b>設計</b>漸層色背景、字重由粗到細的階梯式排版，讓過渡自然不突兀。</i></p></details>\n      <details><summary>3. 對稱</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"55\" y1=\"4\" x2=\"55\" y2=\"62\" stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".6\"/><circle cx=\"34\" cy=\"33\" r=\"13\" fill=\"#8A5FC0\"/><circle cx=\"76\" cy=\"33\" r=\"13\" fill=\"#8A5FC0\"/></svg></span><b class=\"fp-lede\">以中軸為基準，兩邊的形狀、數量、色彩完全相同或近似。</b><i><b>攝影</b>水中倒影、建築正面，營造絕對的莊重、穩定與儀式感。</i><i><b>繪畫</b>宗教祭壇畫、宮廷肖像把最重要的人放正中央，兩側完全對稱呼應，用形式上的絕對平衡傳達不可動搖的神權或王權。</i><i><b>設計</b>書封、邀請函、品牌標誌，傳達典雅、可信賴的正式感。</i></p></details>\n      <details><summary>4. 均衡</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M55 50 L46 58 L64 58 Z\" fill=\"#7B6BB5\" opacity=\".6\"/><line x1=\"14\" y1=\"46\" x2=\"96\" y2=\"46\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><circle cx=\"30\" cy=\"32\" r=\"14\" fill=\"#8A5FC0\"/><circle cx=\"84\" cy=\"38\" r=\"7\" fill=\"#E08A3C\"/></svg></span><b class=\"fp-lede\">不是鏡像複製，而是靠「重量感」達到視覺平衡。對稱是雙胞胎，均衡是蹺蹺板——兩邊不一樣，但重量相等。</b><i><b>攝影</b>左邊一個大人物，右邊一小片文字或一個小物件，輕重互相制衡。</i><i><b>繪畫</b>一側是實體人物群像，另一側用大面積的布料皺褶、光影或遠景來對抗重量，達到動態平衡。</i><i><b>設計</b>主圖很大放在左邊，右邊用粗體大標題壓住，避免版面歪斜。</i></p></details>\n      <details><summary>5. 調和</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g><rect x=\"12\" y=\"20\" width=\"20\" height=\"26\" rx=\"4\" fill=\"#8A5FC0\" opacity=\".45\"/><rect x=\"36\" y=\"20\" width=\"20\" height=\"26\" rx=\"4\" fill=\"#8A5FC0\" opacity=\".65\"/><rect x=\"60\" y=\"20\" width=\"20\" height=\"26\" rx=\"4\" fill=\"#8A5FC0\" opacity=\".85\"/><rect x=\"84\" y=\"20\" width=\"14\" height=\"26\" rx=\"4\" fill=\"#8A5FC0\"/></g></svg></span><b class=\"fp-lede\">不同元素之間具有共通性或相似性，放在一起感覺和諧、不衝突。</b><i><b>攝影</b>同色系的秋天黃葉、青藍色調的海景，整張照片的色相都在一個窄範圍內。</i><i><b>繪畫</b>古典油畫的統調處理：整幅畫罩上一層琥珀色或青色的透明色，讓所有顏色都吃進同一種氛圍。</i><i><b>設計</b>簡報模板的統一配色、整套 UI 用同一種圓角弧度，讓整體感強烈。</i></p></details>\n      <details><summary>6. 對比</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"54\" height=\"64\" rx=\"6\" fill=\"#2A2138\"/><circle cx=\"28\" cy=\"33\" r=\"12\" fill=\"#F6F4FB\"/><circle cx=\"82\" cy=\"33\" r=\"12\" fill=\"#2A2138\"/></svg></span><b class=\"fp-lede\">把兩種以上的異質元素放在一起，互相襯托出各自的特質。沒有對比就沒有焦點。</b><i><b>攝影</b>明暗對比（剪影）、大小對比（人站在巨幅廣告下）、色彩對比（萬綠叢中一點紅）。</i><i><b>繪畫</b>卡拉瓦喬的強烈明暗對比法，人物從漆黑背景中浮現，戲劇性極強；印象派用冷暖並置讓顏色互相振動。</i><i><b>設計</b>大字對小字、留白對密集資訊、冷色對暖色，建立清晰的資訊層級。</i></p></details>\n      <details><summary>7. 比例</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"10\" width=\"60\" height=\"46\" rx=\"3\" fill=\"#7B6BB5\" opacity=\".25\"/><rect x=\"68\" y=\"10\" width=\"34\" height=\"46\" rx=\"3\" fill=\"#8A5FC0\" opacity=\".7\"/><text x=\"12\" y=\"38\" font-size=\"8\" fill=\"#7B6BB5\">1</text><text x=\"80\" y=\"38\" font-size=\"8\" fill=\"#fff\">.618</text></svg></span><b class=\"fp-lede\">元素之間的大小關係，以及部分與整體之間的關係。</b><i><b>攝影</b>人物在巨大自然景觀中所佔的微小比例，凸顯壯闊與渺小。</i><i><b>繪畫</b>人體解剖學的比例：頭身比決定人物的神性（拉長）或寫實感；黃金比例被反覆用於畫面分割。</i><i><b>設計</b>標題、內文、圖片的相對大小決定閱讀順序；黃金比例大量用在 Logo 與版心設定上。</i></p></details>\n      <details><summary>8. 節奏</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#8A5FC0\"><rect x=\"10\" y=\"18\" width=\"9\" height=\"30\" rx=\"2\"/><rect x=\"25\" y=\"28\" width=\"9\" height=\"10\" rx=\"2\" opacity=\".55\"/><rect x=\"40\" y=\"18\" width=\"9\" height=\"30\" rx=\"2\"/><rect x=\"55\" y=\"28\" width=\"9\" height=\"10\" rx=\"2\" opacity=\".55\"/><rect x=\"70\" y=\"18\" width=\"9\" height=\"30\" rx=\"2\"/><rect x=\"85\" y=\"28\" width=\"9\" height=\"10\" rx=\"2\" opacity=\".55\"/></g></svg></span><b class=\"fp-lede\">透過反覆、漸變、抑揚頓挫，讓視覺產生類似音樂的流動感與韻律。</b><i><b>攝影</b>柵欄投影在地上形成一道道光影條紋，視線跟著條紋跳動。</i><i><b>繪畫</b>長卷山水的山巒起伏、樹木疏密交替，視線在「緊—鬆—緊—鬆」之間像呼吸一樣流動。</i><i><b>設計</b>長型網頁中文字、圖片、留白交替出現，讓使用者在滑動時有喘息的段落感。</i></p></details>\n      <details><summary>9. 單純</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"33\" r=\"12\" fill=\"#8A5FC0\"/></svg></span><b class=\"fp-lede\">去除一切不必要的裝飾，提煉出最核心的形與色。</b><i><b>攝影</b>極簡攝影只剩一盞燈、一面牆，強迫觀眾凝視最純粹的幾何本質。</i><i><b>繪畫</b>從具象逐步抽離，只留下最基本的形狀與色彩關係，剝除敘事，直指形式本身。</i><i><b>設計</b>極簡海報、無印良品式的風格，用最少的元素傳遞最清晰的訊息。</i></p></details>\n      <details><summary>10. 統一與多樣</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#8A5FC0\"><circle cx=\"22\" cy=\"26\" r=\"9\"/><rect x=\"40\" y=\"16\" width=\"18\" height=\"18\" rx=\"4\"/><circle cx=\"76\" cy=\"24\" r=\"7\"/><rect x=\"18\" y=\"42\" width=\"14\" height=\"14\" rx=\"3\"/><circle cx=\"52\" cy=\"48\" r=\"7\"/><rect x=\"70\" y=\"40\" width=\"18\" height=\"16\" rx=\"4\"/></g></svg></span><b class=\"fp-lede\">在整體秩序中求變化，在變化中又維持整體感——最高的統合原理。太統一會單調，太多樣會混亂，難在拿捏。</b><i><b>攝影</b>群像合影中大家姿勢不同、表情各異（多樣），但穿一樣的衣服、站在同一個背景中（統一）。</i><i><b>繪畫</b>大幅群像畫裡每個人各有動態表情，但色彩統合在同一光源下，構圖又被一個更大的幾何形（三角或螺旋）收束。</i><i><b>設計</b>整套品牌視覺中，不同頁面各有版式變化，但色彩、字型、標誌位置嚴格一致，辨識度與趣味並存。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>構圖法 ↔ 背後原理 <span class=\"tag ok\">對照表</span></h3>\n      <table><thead><tr><th>構圖法</th><th>背後的主要原理</th></tr></thead><tbody>\n        <tr><td>三分法</td><td>比例、均衡</td></tr>\n        <tr><td>對稱構圖</td><td>對稱、均衡</td></tr>\n        <tr><td>引導線構圖</td><td>節奏、漸變</td></tr>\n        <tr><td>三角形構圖</td><td>均衡、比例</td></tr>\n        <tr><td>留白構圖</td><td>單純、對比</td></tr>\n        <tr><td>填滿構圖</td><td>對比、反覆</td></tr>\n        <tr><td>圖案與打破</td><td>反覆、對比</td></tr>\n        <tr><td>放射線構圖</td><td>漸變、節奏</td></tr>\n        <tr><td>曲線構圖</td><td>節奏、調和</td></tr>\n        <tr><td>框架式構圖</td><td>對比、單純</td></tr>\n        <tr><td>散點透視構圖</td><td>多樣、均衡</td></tr>\n        <tr><td>傾斜構圖</td><td>對比、節奏</td></tr>\n      </tbody></table>\n      <p class=\"cond\" style=\"margin:10px 0 0\">每一種構圖都不是單一原理在作用，而是多項原理的疊加。當你不再只是背「把主體放交點上」，而是理解「這是因為比例和均衡在起作用」，你就掌握了視覺語言的底層文法，可以自由組合、打破規則，創造屬於自己的審美判斷。</p>\n    </div>\n", "ae-light": "\n    <div class=\"card\">\n      <h3>光位圖解 <span class=\"tag ok\">光在哪、影在哪</span></h3>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"#F6E7DC\" stroke=\"#DDD6E8\"/>\n<circle cx=\"60\" cy=\"80\" r=\"5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1.2\">\n<line x1=\"51\" y1=\"80\" x2=\"54\" y2=\"80\"/><line x1=\"66\" y1=\"80\" x2=\"69\" y2=\"80\"/>\n<line x1=\"60\" y1=\"71\" x2=\"60\" y2=\"74\"/><line x1=\"60\" y1=\"86\" x2=\"60\" y2=\"89\"/></g></svg></div><figcaption>順光・平整明亮、立體感弱</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"#F6E7DC\" stroke=\"#DDD6E8\"/><path d=\"M60 21 A24 24 0 0 1 60 69 Z\" fill=\"#8B7B93\" opacity=\".55\"/>\n<circle cx=\"14\" cy=\"45\" r=\"5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1.2\">\n<line x1=\"5\" y1=\"45\" x2=\"8\" y2=\"45\"/><line x1=\"20\" y1=\"45\" x2=\"23\" y2=\"45\"/>\n<line x1=\"14\" y1=\"36\" x2=\"14\" y2=\"39\"/><line x1=\"14\" y1=\"51\" x2=\"14\" y2=\"54\"/></g></svg></div><figcaption>側光・立體感最強</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"#F6E7DC\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"#8B7B93\" opacity=\".72\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"none\" stroke=\"#FFF3C4\" stroke-width=\"3\"/>\n<circle cx=\"60\" cy=\"10\" r=\"5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1.2\">\n<line x1=\"51\" y1=\"10\" x2=\"54\" y2=\"10\"/><line x1=\"66\" y1=\"10\" x2=\"69\" y2=\"10\"/>\n<line x1=\"60\" y1=\"1\" x2=\"60\" y2=\"4\"/><line x1=\"60\" y1=\"16\" x2=\"60\" y2=\"19\"/></g></svg></div><figcaption>逆光・剪影＋輪廓光</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"#F6E7DC\" stroke=\"#DDD6E8\"/><path d=\"M60 21 A24 24 0 0 1 60 69 Z\" fill=\"#8B7B93\" opacity=\".55\"/><polygon points=\"66,44 76,50 66,56\" fill=\"#F6E7DC\"/>\n<circle cx=\"22\" cy=\"14\" r=\"5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1.2\">\n<line x1=\"13\" y1=\"14\" x2=\"16\" y2=\"14\"/><line x1=\"28\" y1=\"14\" x2=\"31\" y2=\"14\"/>\n<line x1=\"22\" y1=\"5\" x2=\"22\" y2=\"8\"/><line x1=\"22\" y1=\"20\" x2=\"22\" y2=\"23\"/></g></svg></div><figcaption>林布蘭光・暗頰倒三角</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"#F6E7DC\" stroke=\"#DDD6E8\"/><path d=\"M36 45 A24 24 0 0 0 84 45 Z\" fill=\"#8B7B93\" opacity=\".35\"/><ellipse cx=\"60\" cy=\"53\" rx=\"7\" ry=\"3.5\" fill=\"#8B7B93\" opacity=\".7\"/>\n<circle cx=\"60\" cy=\"8\" r=\"5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1.2\">\n<line x1=\"51\" y1=\"8\" x2=\"54\" y2=\"8\"/><line x1=\"66\" y1=\"8\" x2=\"69\" y2=\"8\"/>\n<line x1=\"60\" y1=\"-1\" x2=\"60\" y2=\"2\"/><line x1=\"60\" y1=\"14\" x2=\"60\" y2=\"17\"/></g></svg></div><figcaption>蝴蝶光・鼻下蝶形影</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"#F6E7DC\" stroke=\"#DDD6E8\"/><path d=\"M36 45 A24 24 0 0 1 84 45 Z\" fill=\"#8B7B93\" opacity=\".6\"/>\n<circle cx=\"60\" cy=\"82\" r=\"5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1.2\">\n<line x1=\"51\" y1=\"82\" x2=\"54\" y2=\"82\"/><line x1=\"66\" y1=\"82\" x2=\"69\" y2=\"82\"/>\n<line x1=\"60\" y1=\"73\" x2=\"60\" y2=\"76\"/><line x1=\"60\" y1=\"88\" x2=\"60\" y2=\"91\"/></g></svg></div><figcaption>底光・詭異不安</figcaption></figure>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3>光的方向 <span class=\"tag gold\">最影響氛圍</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">同一套衣服，換個光的方向，氣氛完全不同。</p>\n      <details><summary>順光（正面光）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><circle cx=\"55\" cy=\"58\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>光從正前方來。<b>清楚、明亮、平整</b>，缺點是<b>立體感弱</b>、容易平板。適合想完整展示衣服細節時。</p></details>\n      <details><summary>側光（90°）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><path d=\"M55 19 A17 17 0 0 1 55 53 Z\" fill=\"#8B7B93\" opacity=\".55\"/><circle cx=\"10\" cy=\"36\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>光從側邊來，一半亮一半暗。<b>立體感最強</b>，能凸顯布料的皺褶與質感。想讓照片有「厚度」就用側光。</p></details>\n      <details><summary>逆光</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#8B7B93\" opacity=\".7\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"none\" stroke=\"#FFF3C4\" stroke-width=\"2.5\"/><circle cx=\"55\" cy=\"8\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>光在人物後方。人物壓暗成<b>剪影</b>，邊緣被光鑲一圈——最夢幻、最有氛圍。透光的紗、蕾絲、髮絲在逆光下會發亮，非常適合仙氣路線。</p></details>\n      <details><summary>林布蘭光（45°）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><path d=\"M55 19 A17 17 0 0 1 55 53 Z\" fill=\"#8B7B93\" opacity=\".55\"/><polygon points=\"60,35 69,40 60,45\" fill=\"#F3E7DC\"/><circle cx=\"16\" cy=\"10\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>光從斜前上方 45° 打下，在暗側臉頰形成一個<b>倒三角形亮塊</b>。古典油畫感、優雅又有戲劇性，是肖像的經典打法。</p></details>\n      <details><summary>蝴蝶光（正上方）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><ellipse cx=\"55\" cy=\"44\" rx=\"6\" ry=\"3\" fill=\"#8B7B93\" opacity=\".7\"/><circle cx=\"55\" cy=\"7\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>光從正前上方打下，鼻下形成<b>蝴蝶形陰影</b>。臉部乾淨、華麗、有明星感，適合正面美人照。</p></details>\n      <details><summary>底光（自下而上）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><path d=\"M38 36 A17 17 0 0 1 72 36 Z\" fill=\"#8B7B93\" opacity=\".6\"/><circle cx=\"55\" cy=\"60\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>光從下方打上來。違反自然直覺，會產生<b>不安、詭異、恐怖感</b>——暗黑系、鏡像系主題可以刻意使用。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>光的質感與明暗 <span class=\"tag ok\">硬光・軟光</span></h3>\n      <ul class=\"tips\">\n        <li><b>硬光</b>光源小而直接，陰影<b>邊緣銳利</b>、對比強。戲劇性、銳利、冷峻。</li>\n        <li><b>軟光</b>光源大而擴散（陰天、紗簾），陰影<b>邊緣柔和</b>。溫柔、夢幻、朦朧。</li>\n        <li><b>明暗法（Chiaroscuro）</b>強烈明暗對比的古典技法，大片暗中一束光——文藝復興油畫的招牌，最適合哥德暗黑主題。</li>\n        <li><b>輪廓光（Rim light）</b>從背後側邊打一道光勾勒邊緣，<b>把人物從背景中「切」出來</b>；深色背景配深色衣服時的救星。</li>\n        <li><b>環境光遮蔽</b>物體交界、褶皺深處會更暗。記得這點，畫面才不會浮在背景上。</li>\n        <li><b>色溫</b>暖光（黃橙）＝溫暖、懷舊、日落；冷光（藍青）＝冷靜、孤寂、月夜。<b>冷暖對比</b>（冷背景＋暖主光）是最討喜的配法。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>進階光影 <span class=\"tag gold\">再細一點</span></h3>\n      <details><summary>三點打光法</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><path d=\"M55 19 A17 17 0 0 1 55 53 Z\" fill=\"#8B7B93\" opacity=\".4\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"none\" stroke=\"#FFF3C4\" stroke-width=\"2\"/><circle cx=\"96\" cy=\"52\" r=\"3\" fill=\"#3D8E8A\"/><circle cx=\"16\" cy=\"12\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>專業棚拍基礎：<b>主光</b>（塑造明暗與立體）＋<b>補光</b>（填暗部、控制反差，通常較弱）＋<b>輪廓光/背光</b>（勾邊、分離背景）。三者一到位，人物立刻「站」出來。</p></details>\n      <details><summary>高調 vs 低調 High/Low Key</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#EFEAF6\"/><circle cx=\"55\" cy=\"33\" r=\"15\" fill=\"#CFC5E4\"/></svg></span><b>高調</b>：整體明亮、以中間到亮調為主、陰影極少——清新、純潔、夢幻、廣告感。<b>低調</b>：整體偏暗、大片陰影中少量亮部——神秘、戲劇、情緒、電影感。先決定調性，再決定打光。</p></details>\n      <details><summary>光的品質：擴散與衰減</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><path d=\"M55 19 A17 17 0 0 1 55 53 Z\" fill=\"#8B7B93\" opacity=\".5\"/><circle cx=\"14\" cy=\"36\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>光源<b>越大越近＝越柔</b>（陰影邊緣糊）；<b>越小越遠＝越硬</b>（陰影邊緣利）。另外光有「平方反比衰減」——<b>離光源越遠掉得越快</b>，善用它能讓背景自然變暗、凸顯主角。</p></details>\n      <details><summary>反光與補光</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><path d=\"M55 19 A17 17 0 0 1 55 53 Z\" fill=\"#8B7B93\" opacity=\".35\"/><rect x=\"86\" y=\"24\" width=\"8\" height=\"24\" rx=\"2\" fill=\"#EFE7C8\"/><circle cx=\"16\" cy=\"12\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>暗部不是死黑——用<b>反光板/淺色物件</b>把主光反彈回暗部，能保留細節、柔化反差。暗部有沒有「透氣」，是照片高級與否的關鍵之一。</p></details>\n      <details><summary>色光與冷暖交叉</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><path d=\"M55 19 A17 17 0 0 0 55 53 Z\" fill=\"#5A78C0\" opacity=\".5\"/><path d=\"M55 19 A17 17 0 0 1 55 53 Z\" fill=\"#E0813F\" opacity=\".45\"/><circle cx=\"55\" cy=\"7\" r=\"3.5\" fill=\"#B8892E\"/></svg></span><b>主光暖、補光冷</b>（或反之）是電影感的萬用配方：臉的一側暖橙、另一側冷藍，立體感與氛圍一次到位。日落的暖光配天空的冷影就是天然範例。</p></details>\n      <details><summary>剪影與半剪影</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#EDE6D6\"/><circle cx=\"55\" cy=\"30\" r=\"12\" fill=\"#2A2138\"/><rect x=\"45\" y=\"40\" width=\"20\" height=\"22\" rx=\"6\" fill=\"#2A2138\"/></svg></span>強逆光下讓主體<b>完全壓黑成剪影</b>＝極簡、詩意、神祕（只靠輪廓說話）；<b>半剪影</b>（保留一點正面細節）則兼具氛圍與資訊。輪廓要夠乾淨、姿態要夠清楚，剪影才成立。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>光影全解 <span class=\"tag hot\">光決定觀眾感受到什麼</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\">構圖是骨架，形式原理是文法，光影是血肉。同樣的構圖，光線一變，情感可以從希望瞬間變成絕望。上面「開始分析」現在會判讀光的質地、影調、陰影的環境色、冷暖分離與體積光。</p>\n    </div>\n    <div class=\"card\">\n      <h3>一、光的方向 <span class=\"tag gold\">陰影落在哪，決定主體的立體感與性格</span></h3>\n      <details><summary>1. 正面光（順光）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"55\" cy=\"34\" rx=\"20\" ry=\"25\" fill=\"#EDE6F5\"/><path d=\"M55 9 A20 25 0 0 0 55 59 Z\" fill=\"#EDE6F5\"/><circle cx=\"55\" cy=\"-2\" r=\"0\"/><circle cx=\"55\" cy=\"62\" r=\"5\" fill=\"#7B6BB5\" opacity=\".25\"/></svg></span><b class=\"fp-lede\">光源從你背後直射主體，陰影落在主體後方，幾乎看不到。</b><i><b>攝影</b>證件照、商業產品照的基礎打光，最清晰還原細節，但缺乏立體感，容易讓臉顯平。</i><i><b>繪畫</b>古典肖像極少單用純正面光，它會吃掉所有凹凸起伏的筆觸。但敦煌壁畫、工筆人物大量採用正面光邏輯，用均勻光線表現超越塵世陰影的永恆。</i><i><b>設計</b>電商白底圖的標準做法，去影去雜，讓消費者毫無干擾地檢視產品本身。</i></p></details>\n      <details><summary>2. 側光</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"55\" cy=\"34\" rx=\"20\" ry=\"25\" fill=\"#3B3348\"/><path d=\"M55 9 A20 25 0 0 0 55 59 Z\" fill=\"#EDE6F5\"/></svg></span><b class=\"fp-lede\">光源從左或右打來，一半亮一半暗。</b><i><b>攝影</b>拍男性肖像、老人肌膚時常用，能極端強調紋理、質感與粗糙的表面細節。</i><i><b>繪畫</b>林布蘭的標誌性用光：光從側面打在臉上，另一側留下一小塊倒三角亮區，人物如雕塑般從黑暗中浮現。</i><i><b>設計</b>字體特效、遊戲原畫用側光塑造肌肉線條與裝備質感，讓扁平圖像瞬間立體。</i></p></details>\n      <details><summary>3. 逆光</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"55\" cy=\"34\" rx=\"20\" ry=\"25\" fill=\"#2A2138\"/><ellipse cx=\"55\" cy=\"34\" rx=\"24\" ry=\"29\" fill=\"none\" stroke=\"#E08A3C\" stroke-width=\"3\" opacity=\".55\"/></svg></span><b class=\"fp-lede\">光源在主體正後方。</b><i><b>攝影</b>剪影的專用光，剝離色彩與細節，只留下最純粹的輪廓，充滿詩意與故事性。</i><i><b>繪畫</b>透納晚期的海景，太陽從畫面深處射出，船隻與海浪都融化在刺目的光裡，形體邊緣被光侵蝕，接近抽象。</i><i><b>設計</b>海報中人物背後透出的光芒，營造神聖降臨或希望感；逆光眩光也用來增加畫面通透度。</i></p></details>\n      <details><summary>4. 頂光</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"55\" cy=\"34\" rx=\"20\" ry=\"25\" fill=\"#EDE6F5\"/><path d=\"M55 9 A20 25 0 0 0 55 59 Z\" fill=\"#EDE6F5\"/><ellipse cx=\"55\" cy=\"46\" rx=\"14\" ry=\"8\" fill=\"#3B3348\" opacity=\".75\"/><path d=\"M40 4 L70 4 L64 12 L46 12 Z\" fill=\"#E08A3C\" opacity=\".5\"/></svg></span><b class=\"fp-lede\">光從正上方打下，眼眶與下巴下方產生深重陰影。</b><i><b>攝影</b>正午陽光或舞台追光，眼窩深陷產生熊貓眼，帶審判、威嚴、壓抑或疲憊的暗示。</i><i><b>繪畫</b>常被歸給卡拉瓦喬，但要小心：他的招牌其實是從高處斜射的側光（所謂「地窖光」），不是純頂光。真正接近頂光的效果是把陰影垂直拖向地面，讓構圖本身訴說下墜與沉重。</i><i><b>設計</b>恐怖遊戲海報、懸疑電影的關鍵光法，製造不安與邪惡感。</i></p></details>\n      <details><summary>5. 底光</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"55\" cy=\"34\" rx=\"20\" ry=\"25\" fill=\"#3B3348\"/><path d=\"M55 9 A20 25 0 0 0 55 59 Z\" fill=\"#3B3348\"/><ellipse cx=\"55\" cy=\"24\" rx=\"15\" ry=\"10\" fill=\"#EDE6F5\" opacity=\".55\"/><path d=\"M40 62 L70 62 L64 54 L46 54 Z\" fill=\"#E08A3C\" opacity=\".5\"/></svg></span><b class=\"fp-lede\">光從下方往上打，顛覆日常經驗。</b><i><b>攝影</b>恐怖片、萬聖節的經典打光，把熟悉的臉孔變得詭異。</i><i><b>繪畫</b>常舉拉圖爾的燭光畫為例，但他的蠟燭多半置於畫面之中、與臉同高或略低，還常被手掌遮擋，並非嚴格的底光。它的價值在於單一微弱光源製造的冥想氣氛。嚴格底光請看舞台與恐怖片的打光。</i><i><b>設計</b>舞台劇、驚悚電影海報常見，製造反常的視覺驚悚。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>二、光的質地 <span class=\"tag ok\">軟硬決定影子邊緣是銳利還是柔和</span></h3>\n      <details><summary>6. 硬光</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"14\" width=\"40\" height=\"38\" rx=\"4\" fill=\"#EDE6F5\"/><rect x=\"52\" y=\"14\" width=\"46\" height=\"38\" rx=\"4\" fill=\"#2A2138\"/></svg></span><b class=\"fp-lede\">點狀光源直射（正午太陽、聚光燈），影子邊緣清晰銳利，明暗反差極大。</b><i><b>攝影</b>紀實攝影、街拍常用，帶來強烈的戲劇衝突與陽剛氣質。</i><i><b>繪畫</b>卡拉瓦喬式明暗對比法，亮部直接跳到暗部，中間幾乎沒有過渡，人物像被一道閃電從深淵中抽出來。</i><i><b>設計</b>金屬質感、科技感產品的渲染圖，用硬光強調邊緣輪廓的銳利與力量。</i></p></details>\n      <details><summary>7. 軟光（柔光、漫射光）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><defs><linearGradient id=\"lqs\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\"><stop offset=\"0\" stop-color=\"#EDE6F5\"/><stop offset=\"1\" stop-color=\"#2A2138\"/></linearGradient></defs><rect x=\"10\" y=\"14\" width=\"88\" height=\"38\" rx=\"4\" fill=\"url(#lqs)\"/></svg></span><b class=\"fp-lede\">透過雲層或柔光罩的大面積散射，影子邊緣模糊，明暗過渡平滑。</b><i><b>攝影</b>人像寫真最安全的光，隱藏毛孔細紋，營造溫柔唯美的氣氛。</i><i><b>繪畫</b>維梅爾的荷蘭室內，從左側窗戶漫射進來的銀灰色天光包裹著衣服與臉龐，輪廓柔和到幾乎融入空氣。</i><i><b>設計</b>日系、北歐風平面設計常用柔光漸層，象徵舒適、自然與純淨。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>三、光的反差（影調） <span class=\"tag warn\">亮暗之間的級距，決定作品的調性</span></h3>\n      <details><summary>8. 高反差（硬調）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"18\" width=\"42\" height=\"30\" rx=\"3\" fill=\"#F8F5FC\"/><rect x=\"58\" y=\"18\" width=\"42\" height=\"30\" rx=\"3\" fill=\"#15101E\"/></svg></span><b class=\"fp-lede\">亮部很亮、暗部死黑，中間灰色地帶很少。</b><i><b>攝影</b>黑白紀實、黑色電影風格，視覺衝擊強烈，適合表達強烈的情緒張力。</i><i><b>繪畫</b>版畫尤其木刻，天然只能依賴黑白兩色，藝術家必須把中間灰階壓縮為純粹的刀痕與留白，力量極強。</i><i><b>設計</b>搖滾樂團海報、街頭潮牌，用高反差黑白衝撞出反叛與個性。</i></p></details>\n      <details><summary>9. 低反差（軟調）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g><rect x=\"8\" y=\"18\" width=\"19\" height=\"30\" fill=\"#E4DCEE\"/><rect x=\"27\" y=\"18\" width=\"19\" height=\"30\" fill=\"#C6BBD8\"/><rect x=\"46\" y=\"18\" width=\"19\" height=\"30\" fill=\"#A79ABE\"/><rect x=\"65\" y=\"18\" width=\"19\" height=\"30\" fill=\"#8B7EA4\"/><rect x=\"84\" y=\"18\" width=\"18\" height=\"30\" fill=\"#6F6289\"/></g></svg></span><b class=\"fp-lede\">從最亮到最暗之間灰階非常豐富，沒有純黑與純白。</b><i><b>攝影</b>小清新、日系空氣感寫真，亮部不過曝、暗部不死黑，畫面柔和舒服。</i><i><b>繪畫</b>莫內晚期的睡蓮，完全放棄強烈對比，整幅畫是一片由微妙冷暖構成的迷霧色域，開始走向抽象。</i><i><b>設計</b>高級護膚品、母嬰品牌的常用調性，營造輕柔無刺激的親和力。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>四、光的功能與特殊應用 <span class=\"tag hot\">光不只照亮，還在做事</span></h3>\n      <details><summary>10. 結構光（雕塑光）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"34\" r=\"22\" fill=\"#B9AECD\"/><path d=\"M55 12 A22 22 0 0 1 55 56 Z\" fill=\"#6F6289\"/><ellipse cx=\"46\" cy=\"26\" rx=\"8\" ry=\"10\" fill=\"#EDE6F5\" opacity=\".8\"/></svg></span><b class=\"fp-lede\">純粹為了揭示形狀、起伏、質感的光，不追求戲劇情緒。</b><i><b>攝影</b>商品攝影中為了拍出布料紋理或珠寶切面，用燈光從特定角度掃過表面，把立體感逼出來。</i><i><b>繪畫</b>學院派素描的基礎邏輯，用單一固定光源分析石膏像的塊面轉折，把複雜形體歸納為亮部、灰部、暗部、反光五個調子。</i><i><b>設計</b>3D 建模軟體中旋轉觀察用的預設照明，目的就是讓結構一目了然。</i></p></details>\n      <details><summary>11. 環境光與反射光</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"34\" r=\"22\" fill=\"#4A4159\"/><path d=\"M55 12 A22 22 0 0 1 55 56 Z\" fill=\"#2A2138\"/><path d=\"M33 34 A22 22 0 0 0 55 56 Z\" fill=\"#5E7EA8\" opacity=\".75\"/></svg></span><b class=\"fp-lede\">光不只來自光源，更來自環境中所有物體的反射。新手最常忽略，卻是決定真實感的關鍵。</b><i><b>攝影</b>白牆或金色夕陽反射在人臉上的補光——暗部不是死黑，而是帶有環境色的微弱光線。</i><i><b>繪畫</b>印象派把「陰影不是黑褐色，而是天空的藍或草地的綠」變成一整套作畫方法。要注意這不是他們最早發現的——謝弗勒爾 1839 年就描述過同時對比，德拉克洛瓦也早已在畫有色陰影；印象派的貢獻是系統化與徹底化。</i><i><b>設計</b>寫實插畫與合成圖若少了環境光的相互滲透，畫面立刻顯得生硬、像貼上去的。</i></p></details>\n      <details><summary>12. 體積光（耶穌光）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g opacity=\".8\"><path d=\"M28 2 L46 2 L26 64 L6 64 Z\" fill=\"#E08A3C\" opacity=\".35\"/><path d=\"M56 2 L74 2 L58 64 L38 64 Z\" fill=\"#E08A3C\" opacity=\".35\"/><path d=\"M84 2 L102 2 L92 64 L72 64 Z\" fill=\"#E08A3C\" opacity=\".35\"/></g></svg></span><b class=\"fp-lede\">光穿過介質（雲隙、窗邊灰塵、林中霧氣），顯現出一道道光柱。</b><i><b>攝影</b>等待清晨或傍晚雲隙光灑落的瞬間，為風景照注入神蹟降臨的震撼。</i><i><b>繪畫</b>浪漫主義與宗教畫中光柱穿破雲層，象徵天啟、希望或神聖的介入。</i><i><b>設計</b>遊戲場景、電影海報用來創造視覺奇觀，把視線聚焦到光柱落點的核心主體上。</i></p></details>\n      <details><summary>13. 光的色彩（色溫）</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"6\" y=\"12\" width=\"46\" height=\"42\" rx=\"4\" fill=\"#E8A63C\"/><rect x=\"58\" y=\"12\" width=\"46\" height=\"42\" rx=\"4\" fill=\"#3C6FA8\"/></svg></span><b class=\"fp-lede\">光本身有顏色，從蠟燭的暖橙到陰天的冷藍，色溫直接定義氛圍。</b><i><b>攝影</b>讓低色溫的暖黃與高色溫的藍調時刻並存，捕捉黃金時刻與藍調時刻的冷暖對比。</i><i><b>繪畫</b>莫內畫同一場景不同時間的系列（乾草堆、盧昂大教堂），證明物體的固有色並不存在，一切取決於當下那道光的顏色。</i><i><b>設計</b>冷暖色光的搭配是賽博朋克風格海報最經典的視覺符號。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>五、光影的終極心法 <span class=\"tag gold\">三個領域的核心意識不同</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\"><b>攝影</b>光線是「發現」的，考驗你對現場的敏感度：光從哪裡來？什麼質地？陰影投在哪？<br><b>繪畫</b>光線是「設計」的，你必須憑空決定光源的位置、強度與顏色。<br><b>設計</b>光線是「模擬」的，無論扁平陰影或 3D 渲染，都只是建立層級與氛圍的工具。<br><br>一句話：構圖決定故事在講什麼，光影決定觀眾感受到什麼。</p>\n    </div>\n", "ae-photo": "\n    <div class=\"card\">\n      <h3>人像構圖圖解 <span class=\"tag ok\">裁切・空間・姿態</span></h3>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 150 120\" role=\"img\">\n<g fill=\"#EFE6F5\" stroke=\"#7B6BB5\" stroke-width=\"1.2\">\n<circle cx=\"46\" cy=\"20\" r=\"11\"/><rect x=\"35\" y=\"33\" width=\"22\" height=\"34\" rx=\"8\"/><rect x=\"38\" y=\"66\" width=\"16\" height=\"42\" rx=\"7\"/></g>\n<g stroke=\"#D06666\" stroke-width=\"1.6\" stroke-dasharray=\"4 3\">\n<line x1=\"20\" y1=\"32\" x2=\"76\" y2=\"32\"/><line x1=\"20\" y1=\"66\" x2=\"76\" y2=\"66\"/><line x1=\"20\" y1=\"106\" x2=\"76\" y2=\"106\"/></g>\n<text x=\"80\" y=\"35\" font-size=\"8.5\" fill=\"#C05555\">✗ 脖子</text>\n<text x=\"80\" y=\"69\" font-size=\"8.5\" fill=\"#C05555\">✗ 膝蓋</text>\n<text x=\"80\" y=\"109\" font-size=\"8.5\" fill=\"#C05555\">✗ 腳踝</text>\n<g stroke=\"#3D8E8A\" stroke-width=\"1.8\">\n<line x1=\"20\" y1=\"47\" x2=\"76\" y2=\"47\"/><line x1=\"20\" y1=\"84\" x2=\"76\" y2=\"84\"/></g>\n<text x=\"80\" y=\"50\" font-size=\"8.5\" fill=\"#3D8E8A\">✓ 胸腰</text>\n<text x=\"80\" y=\"87\" font-size=\"8.5\" fill=\"#3D8E8A\">✓ 大腿中段</text></svg></div><figcaption>裁切關節法則：紅線是禁區（脖子・膝蓋・腳踝），綠線是安全區</figcaption></figure>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 96\" role=\"img\">\n<rect x=\"2\" y=\"6\" width=\"112\" height=\"84\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<circle cx=\"58\" cy=\"46\" r=\"15\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><circle cx=\"64\" cy=\"44\" r=\"2.4\" fill=\"#2A2138\"/>\n<line x1=\"58\" y1=\"10\" x2=\"58\" y2=\"29\" stroke=\"#8A5FC0\" stroke-width=\"1.2\" stroke-dasharray=\"3 2\"/>\n<text x=\"62\" y=\"20\" font-size=\"8\" fill=\"#8A5FC0\">頭部空間</text>\n<rect x=\"126\" y=\"6\" width=\"112\" height=\"84\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<circle cx=\"164\" cy=\"48\" r=\"15\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><circle cx=\"171\" cy=\"46\" r=\"2.4\" fill=\"#2A2138\"/>\n<path d=\"M182 48 L214 48\" stroke=\"#3D8E8A\" stroke-width=\"1.4\" marker-end=\"url(#ar)\"/>\n<defs><marker id=\"ar\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0 0 L6 3 L0 6 z\" fill=\"#3D8E8A\"/></marker></defs>\n<text x=\"186\" y=\"42\" font-size=\"8\" fill=\"#3D8E8A\">視線空間</text></svg></div><figcaption>頭部空間不要過多；視線望去的一側要留更多空間</figcaption></figure>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 110\" role=\"img\">\n<g stroke=\"#7B6BB5\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\">\n<circle cx=\"42\" cy=\"18\" r=\"9\" fill=\"#EFE6F5\"/><line x1=\"42\" y1=\"27\" x2=\"42\" y2=\"62\"/><line x1=\"42\" y1=\"62\" x2=\"34\" y2=\"98\"/><line x1=\"42\" y1=\"62\" x2=\"52\" y2=\"98\"/><line x1=\"28\" y1=\"38\" x2=\"56\" y2=\"38\"/></g>\n<text x=\"16\" y=\"110\" font-size=\"8.5\" fill=\"#2A2138\">呆板・重心平均</text>\n<g stroke=\"#8A5FC0\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\">\n<circle cx=\"160\" cy=\"18\" r=\"9\" fill=\"#EFE6F5\"/>\n<path d=\"M160 27 Q168 44 158 62\" />\n<line x1=\"158\" y1=\"62\" x2=\"152\" y2=\"98\"/><line x1=\"158\" y1=\"62\" x2=\"172\" y2=\"94\"/>\n<line x1=\"147\" y1=\"36\" x2=\"174\" y2=\"41\"/></g>\n<text x=\"128\" y=\"110\" font-size=\"8.5\" fill=\"#8A5FC0\">對立式平衡・S 曲線</text></svg></div><figcaption>重心移到單腳，肩與骨盆反向傾斜，身體自然成 S 形</figcaption></figure>\n    </div>\n    <div class=\"card\">\n      <h3>鏡頭與視角 <span class=\"tag gold\">改變敘事</span></h3>\n      <details><summary>平視</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"8\" y1=\"58\" x2=\"102\" y2=\"58\" stroke=\"#DDD6E8\"/><rect x=\"50\" y=\"24\" width=\"12\" height=\"34\" rx=\"5\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"56\" cy=\"19\" r=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"20\" cy=\"38\" r=\"5\" fill=\"#8A5FC0\"/><line x1=\"25\" y1=\"38\" x2=\"48\" y2=\"32\" stroke=\"#8A5FC0\" stroke-width=\"1.4\" stroke-dasharray=\"3 2\"/></svg></span>與人物同高。<b>平等、自然、寫實</b>，最中性的視角，適合日常感與正式肖像。</p></details>\n      <details><summary>仰角（由下往上）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"8\" y1=\"58\" x2=\"102\" y2=\"58\" stroke=\"#DDD6E8\"/><rect x=\"50\" y=\"24\" width=\"12\" height=\"34\" rx=\"5\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"56\" cy=\"19\" r=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"20\" cy=\"54\" r=\"5\" fill=\"#8A5FC0\"/><line x1=\"25\" y1=\"54\" x2=\"50\" y2=\"44\" stroke=\"#8A5FC0\" stroke-width=\"1.4\" stroke-dasharray=\"3 2\"/></svg></span>把人物拍得<b>高大、威嚴、有壓迫感</b>——適合王者、女王、反派、氣場強的造型。</p></details>\n      <details><summary>俯角（由上往下）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"8\" y1=\"58\" x2=\"102\" y2=\"58\" stroke=\"#DDD6E8\"/><rect x=\"50\" y=\"24\" width=\"12\" height=\"34\" rx=\"5\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"56\" cy=\"19\" r=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"20\" cy=\"20\" r=\"5\" fill=\"#8A5FC0\"/><line x1=\"25\" y1=\"20\" x2=\"52\" y2=\"22\" stroke=\"#8A5FC0\" stroke-width=\"1.4\" stroke-dasharray=\"3 2\"/></svg></span>把人物拍得<b>嬌小、脆弱、惹人憐愛</b>；也適合展示裙擺全貌與地面裝飾。</p></details>\n      <details><summary>景別（遠中近）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"30\" y=\"8\" width=\"50\" height=\"52\" rx=\"4\" fill=\"none\" stroke=\"#8A5FC0\" stroke-dasharray=\"3 2\"/><circle cx=\"55\" cy=\"24\" r=\"9\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><rect x=\"45\" y=\"34\" width=\"20\" height=\"26\" rx=\"5\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/></svg></span><b>全身遠景</b>＝交代環境與整套搭配；<b>中景（腰上）</b>＝平衡人與衣服；<b>特寫</b>＝強調表情、飾品、材質細節。一組作品建議<b>遠中近都有</b>，敘事才完整。</p></details>\n      <details><summary>景深</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"30\" cy=\"34\" r=\"11\" fill=\"#CFC0E8\" opacity=\".5\"/><circle cx=\"82\" cy=\"34\" r=\"13\" fill=\"#C9BBE4\" opacity=\".4\"/><rect x=\"48\" y=\"24\" width=\"14\" height=\"34\" rx=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"55\" cy=\"20\" r=\"7\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/></svg></span><b>淺景深</b>（背景模糊）＝主角突出、夢幻；<b>深景深</b>（全清晰）＝資訊完整、氣勢磅礡。人物照多用淺景深，場景照用深景深。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>攝影常用心法 <span class=\"tag ok\">實用</span></h3>\n      <ul class=\"tips\">\n        <li><b>先決定主角</b>是這套衣服？是表情？還是氣氛？主角不同，構圖與光完全不同。</li>\n        <li><b>減法比加法重要</b>畫面亂通常不是缺東西，而是<b>東西太多</b>。拿掉不服務主題的元素。</li>\n        <li><b>背景要為主角服務</b>背景太花會吃掉人物；深色衣服配淺背景、淺色衣服配深背景，永遠安全。</li>\n        <li><b>注意邊緣</b>檢查畫面四邊有沒有被切一半的奇怪元素——邊緣乾淨，作品就專業一半。</li>\n        <li><b>一張只講一件事</b>想表達的東西越少，畫面越有力。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>人像景別與裁切 <span class=\"tag hot\">專業人像</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">拍到哪裡、切在哪裡，決定了照片的親密程度與專業度。</p>\n      <details><summary>景別的心理距離</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"30\" y=\"8\" width=\"50\" height=\"52\" rx=\"4\" fill=\"none\" stroke=\"#8A5FC0\" stroke-dasharray=\"3 2\"/><circle cx=\"55\" cy=\"24\" r=\"9\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><rect x=\"45\" y=\"34\" width=\"20\" height=\"26\" rx=\"5\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/></svg></span><b>大特寫</b>（五官）＝最強情緒、最私密；<b>特寫</b>（頭肩）＝親密、專注表情；<b>近景</b>（腰上）＝人物與姿態並重，最常用；<b>中景</b>（膝上）＝可看見手勢與服裝主體；<b>全身</b>＝展示完整造型；<b>遠景</b>＝人小景大，強調氛圍與環境。<br>景別越近＝情緒越強；景別越遠＝敘事越強。</p></details>\n      <details><summary>裁切禁忌（關節法則）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"46\" y=\"10\" width=\"18\" height=\"30\" rx=\"7\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><circle cx=\"55\" cy=\"8\" r=\"6\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><line x1=\"30\" y1=\"40\" x2=\"80\" y2=\"40\" stroke=\"#C0554E\" stroke-width=\"1.6\" stroke-dasharray=\"4 3\"/><line x1=\"30\" y1=\"52\" x2=\"80\" y2=\"52\" stroke=\"#3D8E8A\" stroke-width=\"1.6\"/><text x=\"83\" y=\"43\" font-size=\"8\" fill=\"#C0554E\">✗</text><text x=\"83\" y=\"55\" font-size=\"8\" fill=\"#3D8E8A\">✓</text></svg></span><b>絕不要切在關節上</b>——手腕、手肘、膝蓋、腳踝、脖子。切在關節會讓人感覺肢體被「截斷」，非常不適。<br><b>正確做法</b>：切在<b>大腿中段、腰腹、胸口、上臂中段</b>等肌肉區。另外也<b>不要切掉手指或半隻腳</b>。</p></details>\n      <details><summary>頭部空間 Headroom</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"38\" r=\"14\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><line x1=\"55\" y1=\"6\" x2=\"55\" y2=\"23\" stroke=\"#8A5FC0\" stroke-dasharray=\"3 2\"/><text x=\"59\" y=\"16\" font-size=\"7.5\" fill=\"#8A5FC0\">頭部空間</text></svg></span>頭頂到畫面上緣的距離。<b>太多＝人物下沉、畫面空洞；太少＝壓迫、像被壓扁。</b><br>原則：景別越近，頭部空間越少；大特寫時<b>甚至可以切掉一點頭頂</b>（這是專業做法，能讓五官更飽滿）。</p></details>\n      <details><summary>視線空間 Lead room / Nose room</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"40\" cy=\"34\" r=\"14\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><circle cx=\"47\" cy=\"32\" r=\"2.4\" fill=\"#2A2138\"/><path d=\"M56 34 L96 34\" stroke=\"#3D8E8A\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/><text x=\"60\" y=\"28\" font-size=\"7.5\" fill=\"#3D8E8A\">視線空間</text></svg></span>人物面向或視線望去的那一側，<b>必須留出更多空間</b>。<br>否則會產生「撞牆感」——視線被畫框擋住，觀者會覺得莫名不舒服。這是人像構圖<b>最常被忽略卻最有效</b>的一條。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>姿態與體態 <span class=\"tag gold\">讓人物活起來</span></h3>\n      <details><summary>對立式平衡 Contrapposto</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#8A5FC0\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"><circle cx=\"55\" cy=\"14\" r=\"7\" fill=\"#EFE6F5\"/><path d=\"M55 21 Q62 34 52 48\"/><line x1=\"52\" y1=\"48\" x2=\"46\" y2=\"60\"/><line x1=\"52\" y1=\"48\" x2=\"64\" y2=\"58\"/><line x1=\"44\" y1=\"28\" x2=\"66\" y2=\"32\"/></g></svg></span>古希臘雕塑的發明：<b>重心放在單腳</b>，使骨盆傾斜、肩膀反向傾斜，身體形成放鬆的 S 形。<br>效果：<b>立刻打破呆板的立正站姿</b>，產生自然的優雅與生命感。這是所有人像姿勢的基礎——先把重心移到一腳。</p></details>\n      <details><summary>S 曲線與三角</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M55 10 Q46 26 58 38 Q68 48 50 60\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"2.4\" stroke-linecap=\"round\"/></svg></span><b>S 曲線</b>：身體沿著 S 形起伏（頭、肩、腰、臀反向擺動），是女性人像最經典的柔美線條。<br><b>三角形</b>：手叉腰、手撐地、坐姿裙擺展開都會形成三角，帶來<b>穩定感</b>。柔美用 S、莊重用三角。</p></details>\n      <details><summary>肩線與角度</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"16\" r=\"7\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><line x1=\"34\" y1=\"40\" x2=\"76\" y2=\"30\" stroke=\"#8A5FC0\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><text x=\"30\" y=\"56\" font-size=\"8\" fill=\"#2A2138\">斜 45°</text></svg></span><b>肩線平行鏡頭＝正式、強勢、對稱</b>；<b>肩線斜向鏡頭＝苗條、自然、有層次</b>。大多數人像會讓身體斜 45°、臉轉回鏡頭，這樣最顯瘦也最立體。</p></details>\n      <details><summary>手的處理</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"55\" cy=\"34\" rx=\"10\" ry=\"15\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><g stroke=\"#7B6BB5\" stroke-width=\"2\" stroke-linecap=\"round\"><line x1=\"49\" y1=\"22\" x2=\"47\" y2=\"12\"/><line x1=\"55\" y1=\"20\" x2=\"55\" y2=\"10\"/><line x1=\"61\" y1=\"22\" x2=\"63\" y2=\"12\"/></g></svg></span>手是人像最容易出錯的地方。原則：<b>①手要有事做</b>（碰觸頭髮、裙襬、道具）；<b>②避免手背正對鏡頭</b>（顯大、像肉塊），用<b>手的側面</b>更優雅；<b>③手指微彎、不要僵直併攏</b>；④不要讓手臂完全貼緊身體，留一點縫隙才顯瘦。</p></details>\n      <details><summary>留意「斷肢」與交疊</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"46\" y=\"14\" width=\"18\" height=\"34\" rx=\"7\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><line x1=\"55\" y1=\"4\" x2=\"55\" y2=\"60\" stroke=\"#C0554E\" stroke-width=\"3\" opacity=\".5\"/><text x=\"60\" y=\"40\" font-size=\"8\" fill=\"#C0554E\">✗ 交疊</text></svg></span>從鏡頭角度看，避免<b>柱子從頭上長出來</b>、手臂與背景線條重疊、道具切斷脖子。拍完檢查一次輪廓線有沒有和背景「黏」在一起。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>專業人像打光四法 <span class=\"tag ok\">臉部光型</span></h3>\n      <ul class=\"tips\">\n        <li><b>派拉蒙光／蝴蝶光 Butterfly</b>燈在正前上方，鼻下蝴蝶影。<b>華麗、明星感</b>，適合正面美人與對稱臉型。</li>\n        <li><b>環形光 Loop</b>燈稍偏 30–45°，鼻影呈<b>小小的環狀</b>落在臉頰。最自然、最泛用的人像光，適合大多數臉型。</li>\n        <li><b>林布蘭光 Rembrandt</b>燈約 45°，暗側頰上出現<b>倒三角亮塊</b>。戲劇性、古典油畫感，最有故事性。</li>\n        <li><b>分割光 Split</b>燈在正側 90°，臉<b>一半亮一半全暗</b>。強烈、神秘、衝突感，適合暗黑與雙面主題。</li>\n        <li><b>眼神光 Catchlight</b>眼中的那一點反光。<b>沒有眼神光，眼睛會像死掉一樣</b>——這是人像成敗的關鍵細節，務必確認眼裡有光。</li>\n        <li><b>光比</b>亮面與暗面的差距。<b>低光比</b>（差距小）＝柔和清新；<b>高光比</b>（差距大）＝戲劇強烈。想溫柔就補光，想深刻就讓暗部沉下去。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>鏡頭與臉部變形 <span class=\"tag ok\">為什麼要退後拍</span></h3>\n      <ul class=\"tips\">\n        <li><b>廣角（&lt;35mm）</b>近距離拍臉會<b>鼻子放大、臉部外擴變形</b>。適合誇張、環境人像，不適合特寫。</li>\n        <li><b>標準（50mm）</b>接近人眼視角，自然寫實，全身與環境人像的萬用選擇。</li>\n        <li><b>人像鏡（85–135mm）</b><b>公認最美的人像焦段</b>。壓縮感讓五官比例更端正、背景虛化更柔，臉型最好看。</li>\n        <li><b>關鍵是「拍攝距離」</b>變形其實來自距離太近，不是鏡頭本身。<b>退後幾步再拉近</b>，臉型立刻正常。</li>\n        <li><b>背景壓縮</b>長焦會讓背景「拉近放大」，能把遠處的花牆、月亮變成巨大的背景元素。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>攝影視角圖解 <span class=\"tag ok\">相機在哪</span></h3>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 88\"><rect width=\"120\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"46\" cy=\"24\" r=\"9\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"38\" y=\"34\" width=\"16\" height=\"30\" rx=\"6\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"86\" y=\"34\" width=\"16\" height=\"12\" rx=\"2\" fill=\"#8A5FC0\"/><line x1=\"86\" y1=\"40\" x2=\"58\" y2=\"40\" stroke=\"#3D8E8A\" stroke-dasharray=\"3 2\"/><text x=\"10\" y=\"82\" font-size=\"10\" fill=\"#2A2138\">平視</text></svg></div><figcaption>平視・平等自然</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 88\"><rect width=\"120\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"46\" cy=\"24\" r=\"9\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"38\" y=\"34\" width=\"16\" height=\"30\" rx=\"6\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"82\" y=\"66\" width=\"16\" height=\"12\" rx=\"2\" fill=\"#8A5FC0\"/><line x1=\"86\" y1=\"66\" x2=\"52\" y2=\"34\" stroke=\"#3D8E8A\" stroke-dasharray=\"3 2\"/><text x=\"10\" y=\"82\" font-size=\"10\" fill=\"#2A2138\">仰角・威嚴</text></svg></div><figcaption>仰角・高大威嚴</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 88\"><rect width=\"120\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"46\" cy=\"24\" r=\"9\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"38\" y=\"34\" width=\"16\" height=\"30\" rx=\"6\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"82\" y=\"8\" width=\"16\" height=\"12\" rx=\"2\" fill=\"#8A5FC0\"/><line x1=\"86\" y1=\"20\" x2=\"52\" y2=\"40\" stroke=\"#3D8E8A\" stroke-dasharray=\"3 2\"/><text x=\"10\" y=\"82\" font-size=\"10\" fill=\"#2A2138\">俯角・惹憐</text></svg></div><figcaption>俯角・嬌小惹憐</figcaption></figure></div>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 200 92\"><rect width=\"200\" height=\"92\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<g transform=\"translate(6,8)\"><circle cx=\"26\" cy=\"18\" r=\"9\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"17\" y=\"28\" width=\"18\" height=\"26\" rx=\"6\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"20\" y=\"54\" width=\"12\" height=\"20\" rx=\"4\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"1\" y=\"1\" width=\"52\" height=\"76\" rx=\"4\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"1.5\"/><text x=\"6\" y=\"90\" font-size=\"9\" fill=\"#2A2138\">全身</text></g>\n<g transform=\"translate(72,8)\"><circle cx=\"26\" cy=\"18\" r=\"9\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"17\" y=\"28\" width=\"18\" height=\"26\" rx=\"6\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"6\" y=\"1\" width=\"42\" height=\"52\" rx=\"4\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"1.5\"/><text x=\"6\" y=\"90\" font-size=\"9\" fill=\"#2A2138\">近景・腰上</text></g>\n<g transform=\"translate(140,8)\"><circle cx=\"30\" cy=\"24\" r=\"15\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"12\" y=\"1\" width=\"40\" height=\"40\" rx=\"4\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"1.5\"/><text x=\"10\" y=\"90\" font-size=\"9\" fill=\"#2A2138\">特寫</text></g></svg></div><figcaption>景別：越近情緒越強，越遠敘事越強</figcaption></figure>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 200 88\"><rect width=\"200\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<g transform=\"translate(6,6)\"><circle cx=\"60\" cy=\"20\" r=\"6\" fill=\"#DDD6E8\"/><circle cx=\"30\" cy=\"30\" r=\"5\" fill=\"#DDD6E8\"/><circle cx=\"80\" cy=\"40\" r=\"7\" fill=\"#DDD6E8\"/><circle cx=\"46\" cy=\"46\" r=\"9\" fill=\"#8A5FC0\"/><rect x=\"1\" y=\"1\" width=\"88\" height=\"72\" rx=\"4\" fill=\"none\" stroke=\"#DDD6E8\"/><text x=\"6\" y=\"88\" font-size=\"9\" fill=\"#2A2138\">淺景深・主角突出</text></g>\n<g transform=\"translate(104,6)\"><circle cx=\"60\" cy=\"20\" r=\"6\" fill=\"#7B6BB5\"/><circle cx=\"30\" cy=\"30\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"80\" cy=\"40\" r=\"7\" fill=\"#7B6BB5\"/><circle cx=\"46\" cy=\"46\" r=\"9\" fill=\"#8A5FC0\"/><rect x=\"1\" y=\"1\" width=\"88\" height=\"72\" rx=\"4\" fill=\"none\" stroke=\"#DDD6E8\"/><text x=\"6\" y=\"88\" font-size=\"9\" fill=\"#2A2138\">深景深・全清晰</text></g></svg></div><figcaption>景深：人物照用淺景深，場景照用深景深</figcaption></figure>\n    </div>\n    <div class=\"card\">\n      <h3>攝影視角圖解 <span class=\"tag ok\">角度・景別・景深</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">相機位置（黃／綠點）決定人物給人的感覺。</p>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<line x1=\"10\" y1=\"80\" x2=\"110\" y2=\"80\" stroke=\"#DDD6E8\"/>\n<rect x=\"54\" y=\"34\" width=\"14\" height=\"40\" rx=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"61\" cy=\"28\" r=\"8\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/>\n<circle cx=\"26\" cy=\"74\" r=\"6\" fill=\"#8A5FC0\"/><path d=\"M32 74 L54 58\" stroke=\"#8A5FC0\" stroke-width=\"1.6\" stroke-dasharray=\"3 2\" marker-end=\"url(#a2)\"/>\n<defs><marker id=\"a2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0 0 L6 3 L0 6 z\" fill=\"#8A5FC0\"/></marker></defs>\n<text x=\"60\" y=\"92\" font-size=\"9.5\" fill=\"#2A2138\" text-anchor=\"middle\">仰角・高大威嚴</text></svg></div><figcaption>仰角</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<line x1=\"10\" y1=\"80\" x2=\"110\" y2=\"80\" stroke=\"#DDD6E8\"/>\n<rect x=\"54\" y=\"34\" width=\"14\" height=\"40\" rx=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"61\" cy=\"28\" r=\"8\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/>\n<circle cx=\"26\" cy=\"50\" r=\"6\" fill=\"#3D8E8A\"/><path d=\"M32 50 L52 44\" stroke=\"#3D8E8A\" stroke-width=\"1.6\" stroke-dasharray=\"3 2\" marker-end=\"url(#a2_2)\"/>\n<defs><marker id=\"a2_2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0 0 L6 3 L0 6 z\" fill=\"#3D8E8A\"/></marker></defs>\n<text x=\"60\" y=\"92\" font-size=\"9.5\" fill=\"#2A2138\" text-anchor=\"middle\">平視・自然平等</text></svg></div><figcaption>平視</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<line x1=\"10\" y1=\"80\" x2=\"110\" y2=\"80\" stroke=\"#DDD6E8\"/>\n<rect x=\"54\" y=\"34\" width=\"14\" height=\"40\" rx=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"61\" cy=\"28\" r=\"8\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/>\n<circle cx=\"26\" cy=\"24\" r=\"6\" fill=\"#B8892E\"/><path d=\"M32 24 L56 34\" stroke=\"#B8892E\" stroke-width=\"1.6\" stroke-dasharray=\"3 2\" marker-end=\"url(#a2_3)\"/>\n<defs><marker id=\"a2_3\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0 0 L6 3 L0 6 z\" fill=\"#B8892E\"/></marker></defs>\n<text x=\"60\" y=\"92\" font-size=\"9.5\" fill=\"#2A2138\" text-anchor=\"middle\">俯角・嬌小惹憐</text></svg></div><figcaption>俯角</figcaption></figure></div>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<clipPath id=\"c16\"><rect x=\"30\" y=\"16\" width=\"60\" height=\"72\"/></clipPath>\n<g clip-path=\"url(#c16)\"><circle cx=\"60\" cy=\"30\" r=\"13\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><rect x=\"46\" y=\"42\" width=\"28\" height=\"30\" rx=\"8\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><rect x=\"50\" y=\"70\" width=\"20\" height=\"24\" rx=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/></g>\n<rect x=\"30\" y=\"16\" width=\"60\" height=\"72\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n<text x=\"60\" y=\"92\" font-size=\"9\" fill=\"#2A2138\" text-anchor=\"middle\">特寫・情緒</text></svg></div><figcaption>特寫</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<clipPath id=\"c40\"><rect x=\"30\" y=\"40\" width=\"60\" height=\"48\"/></clipPath>\n<g clip-path=\"url(#c40)\"><circle cx=\"60\" cy=\"30\" r=\"13\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><rect x=\"46\" y=\"42\" width=\"28\" height=\"30\" rx=\"8\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><rect x=\"50\" y=\"70\" width=\"20\" height=\"24\" rx=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/></g>\n<rect x=\"30\" y=\"40\" width=\"60\" height=\"48\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n<text x=\"60\" y=\"92\" font-size=\"9\" fill=\"#2A2138\" text-anchor=\"middle\">近景・最常用</text></svg></div><figcaption>近景</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<circle cx=\"34\" cy=\"40\" r=\"13\" fill=\"#CFC0E8\" opacity=\".5\"/><circle cx=\"86\" cy=\"40\" r=\"16\" fill=\"#C9BBE4\" opacity=\".4\"/>\n<rect x=\"52\" y=\"30\" width=\"16\" height=\"44\" rx=\"7\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"60\" cy=\"24\" r=\"8\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/>\n<text x=\"60\" y=\"92\" font-size=\"9\" fill=\"#2A2138\" text-anchor=\"middle\">淺景深・主角突出背景糊</text></svg></div><figcaption>淺景深</figcaption></figure></div>\n    </div>\n    <div class=\"card\">\n      <h3>進階攝影觀念 <span class=\"tag gold\">構圖之外</span></h3>\n      <details><summary>決定性瞬間</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"33\" r=\"20\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><circle cx=\"55\" cy=\"33\" r=\"4\" fill=\"#8A5FC0\"/><path d=\"M55 13 L55 6 M75 33 L82 33 M55 53 L55 60 M35 33 L28 33\" stroke=\"#8A5FC0\" stroke-width=\"2\"/></svg></span>布列松的概念：在<b>動作、情緒、構圖同時到達最完美的那一刻</b>按下快門。擺拍也一樣——捕捉裙擺揚到最高、回眸的那一格，遠勝呆板的定格。</p></details>\n      <details><summary>景深與光圈的取捨</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"33\" r=\"18\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"2\" opacity=\"1.0\"/><circle cx=\"55\" cy=\"33\" r=\"15\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"2\" opacity=\"0.8200000000000001\"/><circle cx=\"55\" cy=\"33\" r=\"12\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"2\" opacity=\"0.64\"/><circle cx=\"55\" cy=\"33\" r=\"9\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"2\" opacity=\"0.45999999999999996\"/></svg></span><b>大光圈（淺景深）</b>＝背景奶油般化開、主角極突出，但容錯低；<b>小光圈（深景深）</b>＝前後都清楚、資訊完整、氣勢足。人物特寫用淺、環境敘事用深。</p></details>\n      <details><summary>負空間敘事</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"86\" cy=\"46\" r=\"9\" fill=\"#8A5FC0\"/></svg></span>大片留白不只是構圖技巧，也能<b>說故事</b>——孤獨、渺小、寧靜、餘韻。空的地方，反而是情緒最濃的地方。</p></details>\n      <details><summary>視線與第四面牆</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"30\" r=\"13\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><circle cx=\"55\" cy=\"30\" r=\"3\" fill=\"#2A2138\"/><path d=\"M55 30 L55 62\" stroke=\"#3D8E8A\" stroke-dasharray=\"3 2\"/></svg></span>人物<b>看向鏡頭</b>＝與觀者直接對話、有張力；<b>看向畫外</b>＝製造故事與想像空間（他在看什麼？）。兩者氛圍完全不同，依你想說的故事選擇。</p></details>\n      <details><summary>色調統一（調色）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"16\" width=\"30\" height=\"34\" rx=\"4\" fill=\"#E05A5A\"/><rect x=\"42\" y=\"16\" width=\"30\" height=\"34\" rx=\"4\" fill=\"#4C93C4\"/><rect x=\"76\" y=\"16\" width=\"26\" height=\"34\" rx=\"4\" fill=\"#9DC44A\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#20A0A0\" opacity=\".28\"/></svg></span>後製時給整張照片<b>統一的色彩傾向</b>（青橙、莫蘭迪、冷藍…），是把「隨手拍」變成「作品」最快的一步。先定一個氛圍，再讓所有顏色靠過去。</p></details>\n      <details><summary>留給呼吸的邊界</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"16\" y=\"14\" width=\"78\" height=\"38\" rx=\"4\" fill=\"none\" stroke=\"#7B6BB5\" stroke-dasharray=\"4 3\"/><circle cx=\"55\" cy=\"33\" r=\"10\" fill=\"#8A5FC0\"/></svg></span>別讓重要元素緊貼畫框邊緣。四周留一點<b>安全邊界</b>，畫面才不會有窒息感；裁切時也更有餘裕。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>人像構圖 <span class=\"tag hot\">先觀察人，再套用構圖</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\">前面所有構圖法都能用在人像上，但人像有一個獨一無二的變數：人本身。上方分析現在會判讀景別、關節裁切、頭頂留白、眼睛高度與臉部角度——其中「關節裁切」是最常踩又最少被提醒的一條。</p>\n    </div>\n    <div class=\"card\">\n      <h3>一、景別 <span class=\"tag gold\">拿起相機前先決定拍進多少身體</span></h3>\n      <details><summary>1. 特寫</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"34\" r=\"30\" fill=\"#8A5FC0\"/><circle cx=\"45\" cy=\"28\" r=\"3\" fill=\"#fff\"/><circle cx=\"66\" cy=\"28\" r=\"3\" fill=\"#fff\"/></svg></span><i><b>範圍</b>額頭到下巴，甚至只取五官的一部分（雙眼、嘴唇）。</i><i><b>目的</b>放大情緒，讀取最細微的靈魂波動。剝離環境干擾，強迫觀者與被攝者最親密地對視。</i><i><b>關鍵</b>對焦點永遠落在眼睛上；可以稍微裁切額頭，但不要剛好裁在脖子或下巴關節處；大光圈虛化背景。</i></p></details>\n      <details><summary>2. 大頭照</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"16\" r=\"7\" fill=\"#8A5FC0\"/><rect x=\"46\" y=\"25\" width=\"18\" height=\"41\" rx=\"6\" fill=\"#8A5FC0\"/><line x1=\"4\" y1=\"52\" x2=\"106\" y2=\"52\" stroke=\"#C0554E\" stroke-dasharray=\"3 3\"/></svg></span><i><b>範圍</b>頭頂到鎖骨或胸口。</i><i><b>目的</b>證件照、演員試鏡照、化妝作品展示。重點是清晰交代「這個人長什麼樣子」。</i><i><b>關鍵</b>避免廣角造成鼻子變大；面部受光均勻；背景乾淨，留白通常在上方與兩側均衡分佈。</i></p></details>\n      <details><summary>3. 半身像</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"12\" r=\"7\" fill=\"#8A5FC0\"/><rect x=\"46\" y=\"21\" width=\"18\" height=\"45\" rx=\"6\" fill=\"#8A5FC0\"/><line x1=\"4\" y1=\"46\" x2=\"106\" y2=\"46\" stroke=\"#C0554E\" stroke-dasharray=\"3 3\"/></svg></span><i><b>範圍</b>頭頂到腰部或臀部。</i><i><b>目的</b>最常用的人像範疇。既能看清表情，又能帶入手部姿態與服裝細節。</i><i><b>關鍵</b>手的擺放是成敗關鍵——手指自然微曲，避免手掌攤平直對鏡頭；裁切點避開手肘、手腕。</i></p></details>\n      <details><summary>4. 七分身</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"8\" r=\"7\" fill=\"#8A5FC0\"/><rect x=\"46\" y=\"17\" width=\"18\" height=\"49\" rx=\"6\" fill=\"#8A5FC0\"/><line x1=\"4\" y1=\"58\" x2=\"106\" y2=\"58\" stroke=\"#C0554E\" stroke-dasharray=\"3 3\"/></svg></span><i><b>範圍</b>頭頂到小腿肚。</i><i><b>目的</b>比全身更聚焦，又比半身更能展示姿態與服裝的流動感。</i><i><b>關鍵</b>絕對不能剛好卡在膝蓋或腳踝；利用前後腳站姿拉長線條。<br><span style=\"color:var(--rose)\">※ 更正：這個景別常被叫做「美式鏡頭」，但 plan américain 其實是裁在<b>大腿中段／膝蓋略上方</b>，源自西部片要帶到腰間槍套。裁到小腿肚是另一種安全裁切，兩者不同。</span></i></p></details>\n      <details><summary>5. 全身像</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"6\" r=\"7\" fill=\"#8A5FC0\"/><rect x=\"46\" y=\"15\" width=\"18\" height=\"45\" rx=\"6\" fill=\"#8A5FC0\"/></svg></span><i><b>範圍</b>頭頂到腳底。</i><i><b>目的</b>展示整體穿搭、肢體語言、人與環境的空間關係。適合街拍與時尚大片。</i><i><b>關鍵</b>廣角端低角度可拉長腿部比例；頭頂與腳底留適度空間；地平線避免切過脖子。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>二、人像專用構圖法 <span class=\"tag ok\">從通用法則到人像演繹</span></h3>\n      <details><summary>6. 眼神留白空間</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"34\" cy=\"30\" r=\"11\" fill=\"#8A5FC0\"/><rect x=\"52\" y=\"8\" width=\"52\" height=\"50\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".10\"/><path d=\"M46 28 L96 24\" stroke=\"#7B6BB5\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\"/></svg></span><i><b>範圍</b>在被攝者視線朝向的方向，留出比腦後更多的空間。</i><i><b>目的</b>讓觀者順著目光看過去，產生對話感與故事延伸。眼睛看左邊、人卻緊貼左框，會產生壓迫與不安。</i><i><b>關鍵</b>例外：故意讓模特兒緊貼視線邊框，可創造孤獨、壓抑、被逼到絕境的張力。</i></p></details>\n      <details><summary>7. 頭頂留白</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"40\" r=\"14\" fill=\"#8A5FC0\"/><line x1=\"6\" y1=\"18\" x2=\"104\" y2=\"18\" stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\"/><text x=\"55\" y=\"13\" font-size=\"7.5\" fill=\"#7B6BB5\" text-anchor=\"middle\">headroom</text></svg></span><i><b>範圍</b>頭頂到畫面上邊界的距離要恰到好處。</i><i><b>目的</b>頭頂被削掉或緊貼邊緣會有撞牆感；留白過多則人像縮在下方，顯得空盪無力。</i><i><b>關鍵</b>特寫與大頭照可稍微裁切頭頂；半身以上應保留完整頭部輪廓並留微幅空間。</i></p></details>\n      <details><summary>8. 人體關節裁切禁忌</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"44\" y=\"4\" width=\"22\" height=\"58\" rx=\"8\" fill=\"#8A5FC0\"/><g stroke=\"#C0554E\" stroke-width=\"2\"><line x1=\"30\" y1=\"20\" x2=\"80\" y2=\"20\"/><line x1=\"30\" y1=\"44\" x2=\"80\" y2=\"44\"/></g><g stroke=\"#3D8E8A\" stroke-width=\"2\"><line x1=\"34\" y1=\"32\" x2=\"76\" y2=\"32\"/></g></svg></span><i><b>範圍</b>人像最易踩雷卻最被忽視的規則。</i><i><b>目的</b><b>安全裁切點</b>：大腿中段、上臂中段、小腿中段。<b>禁止裁切點</b>：脖子、手肘、手腕、膝蓋、腳踝、腰部。</i><i><b>關鍵</b>在關節處裁切會產生「截肢」的視覺暗示，觀者心理上直覺感到不適。這條規則現在由上方分析自動檢查。</i></p></details>\n      <details><summary>9. 前／後景虛化的層次</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"30\" r=\"12\" fill=\"#8A5FC0\"/><path d=\"M2 66 C22 46 32 60 44 66 Z\" fill=\"#7B6BB5\" opacity=\".5\"/><path d=\"M108 66 C88 44 76 58 64 66 Z\" fill=\"#7B6BB5\" opacity=\".5\"/></svg></span><i><b>範圍</b>用景深堆出空間。</i><i><b>目的</b>前景放花草、窗紗、玻璃，虛化成色塊，營造窺視感與深度，常用來「破」掉過於單調的畫面。</i><i><b>關鍵</b>背景選有引導線的街道、樓梯。環境人像的成敗，往往取決於背景的線條有沒有服務於人物。</i></p></details>\n      <details><summary>10. 框架式構圖</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"18\" y=\"8\" width=\"74\" height=\"50\" rx=\"5\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"5\" opacity=\".35\"/><circle cx=\"55\" cy=\"32\" r=\"11\" fill=\"#8A5FC0\"/></svg></span><i><b>範圍</b>用門框、窗框、樹枝縫隙把人物包圍起來。</i><i><b>目的</b>框架隔離雜亂環境，強迫視線跳過一切落在框中的臉上。</i><i><b>關鍵</b>人像中框架還有「保護感」的心理暗示，讓被攝者看起來更安穩、更有故事。</i></p></details>\n      <details><summary>11. 負空間的情緒化運用</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"86\" cy=\"42\" r=\"8\" fill=\"#8A5FC0\"/><rect x=\"8\" y=\"8\" width=\"60\" height=\"50\" rx=\"5\" fill=\"#7B6BB5\" opacity=\".07\"/></svg></span><i><b>範圍</b>大量留白，人物只佔一角。</i><i><b>目的</b>同一個手法可以傳達截然不同的情緒，差別在人物的大小與視線方向。</i><i><b>關鍵</b>孤獨與疏離（人物很小、空間很大）／自由與嚮往（視線朝向廣闊天空）／極簡與時尚（純色背景上精準偏離中心）。</i></p></details>\n      <details><summary>12. 肢體線條的幾何</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><polygon points=\"55,10 88,56 22,56\" fill=\"none\" stroke=\"#7B6BB5\" stroke-dasharray=\"4 3\"/><path d=\"M55 14 C40 26 68 36 52 50\" stroke=\"#8A5FC0\" stroke-width=\"2.5\" fill=\"none\"/></svg></span><i><b>範圍</b>不只用背景線條，更用身體本身形成結構。</i><i><b>目的</b><b>三角形</b>手臂撐頭、雙手叉腰、屈膝坐姿，畫面立刻有重量感。<b>S 形</b>重量放一側腳、髖部傾斜、肩膀反向微傾。<b>對角線</b>側躺或傾斜，主軸穿過畫面。</i><i><b>關鍵</b>S 形曲線是女性人像的經典姿態，從頸到胸到腰到腿形成流暢的連續曲線。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>三、進階心法 <span class=\"tag warn\">構圖永遠服務於人</span></h3>\n      <details><summary>13. 眼睛的位置是神聖的</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\"><line x1=\"37\" y1=\"4\" x2=\"37\" y2=\"62\"/><line x1=\"73\" y1=\"4\" x2=\"73\" y2=\"62\"/><line x1=\"4\" y1=\"22\" x2=\"106\" y2=\"22\"/></g><circle cx=\"37\" cy=\"22\" r=\"5\" fill=\"#8A5FC0\"/><circle cx=\"73\" cy=\"22\" r=\"5\" fill=\"#8A5FC0\"/></svg></span><i><b>範圍</b>人像唯一接近鐵律的一條。</i><i><b>目的</b>眼睛永遠是畫面中最銳利、最明亮的焦點。觀者看一張人像時，第一個找的就是眼睛。</i><i><b>關鍵</b>把眼睛放在九宮格上方兩個交點附近，最自然、最符合人類觀看習慣。</i></p></details>\n      <details><summary>14. 透視變形與鏡頭選擇</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"30\" cy=\"34\" rx=\"17\" ry=\"22\" fill=\"#8A5FC0\" opacity=\".45\"/><ellipse cx=\"78\" cy=\"34\" rx=\"11\" ry=\"21\" fill=\"#8A5FC0\"/></svg></span><i><b>範圍</b>構圖不只是框取，更與焦距綁定。</i><i><b>目的</b><b>廣角 24–35mm</b>靠近時近端誇張放大。低角度拍全身可拉長腿，但拍特寫會讓鼻子變大，不建議。<b>50–135mm</b>最接近人眼比例，五官不變形，是人像的安全焦距。<b>200mm 以上</b>壓縮空間、背景虛化極強，可從遠處捕捉不被打擾的情緒。</i><i><b>關鍵</b>所謂「變形」其實不是鏡頭造成的，而是<b>拍攝距離</b>。廣角逼你靠近，靠近才造成放大；同樣距離下不同焦距的透視是一樣的。</i></p></details>\n      <details><summary>15. 傾斜構圖的情緒開關</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"6\" y1=\"48\" x2=\"104\" y2=\"22\" stroke=\"#7B6BB5\" stroke-width=\"1.6\"/><rect x=\"44\" y=\"16\" width=\"18\" height=\"30\" rx=\"7\" fill=\"#8A5FC0\" transform=\"rotate(-15 53 31)\"/></svg></span><i><b>範圍</b>荷蘭角在人像中不是隨便能用的效果。</i><i><b>目的</b>適用：混亂、不安、青春叛逆、動感，或時尚大片中刻意打破平衡。</i><i><b>關鍵</b>禁用：正式肖像、婚紗照、企業形象照——歪斜的水平線會讓觀者感到不專業。</i></p></details>\n      <details><summary>16. 正臉、側臉與半側臉</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"34\" cy=\"34\" rx=\"16\" ry=\"21\" fill=\"#8A5FC0\"/><ellipse cx=\"78\" cy=\"34\" rx=\"9\" ry=\"21\" fill=\"#8A5FC0\" opacity=\".6\"/></svg></span><i><b>範圍</b>三種角度三種性格。</i><i><b>目的</b><b>正面</b>直接對視，衝擊力與對話感最強。<b>側面 90°</b>輪廓線條最強，適合五官立體者，常表現沉思與眺望。<b>半側面 45°</b>最實用也最顯瘦。</i><i><b>關鍵</b>半側面能同時看到雙眼與臉部輪廓，光影在臉頰形成自然的立體過渡，是大多數人像的預設選擇。</i></p></details>\n      <details><summary>17. 手與臉的互動</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"26\" r=\"14\" fill=\"#8A5FC0\"/><path d=\"M40 44 C46 36 52 40 55 44\" stroke=\"#7B6BB5\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\"/></svg></span><i><b>範圍</b>半身以上，手的擺放決定成敗。</i><i><b>目的</b>手可以放在下巴、臉頰、嘴唇附近，但不要用力擠壓臉部。</i><i><b>關鍵</b>手指自然微彎，避免五指張開直對鏡頭（會顯得比實際更大更搶眼）。手在畫面邊緣時，同樣遵守關節不裁切原則。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>總結 <span class=\"tag gold\">先觀察人，再套用構圖</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\">構圖永遠服務於人的情緒、神韻和故事。如果你腦中只想著九宮格、引導線，卻忽略了模特兒當下的眼神與肢體語言，照片再「正確」也只是空洞的公式。一張好的人像，是構圖、光影與那個瞬間的靈魂，三者合一的結果。</p>\n    </div>\n", "ae-color": "\n    <div class=\"card\">\n      <h3>色相環與配色圖解 <span class=\"tag ok\">配色一目了然</span></h3>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 120\" role=\"img\"><path d=\"M60.0 8.0 A52 52 0 0 1 86.0 15.0 L75.0 34.0 A30 30 0 0 0 60.0 30.0 Z\" fill=\"#E05A5A\" opacity=\"1\"/><path d=\"M86.0 15.0 A52 52 0 0 1 105.0 34.0 L86.0 45.0 A30 30 0 0 0 75.0 34.0 Z\" fill=\"#E0813F\" opacity=\"1\"/><path d=\"M105.0 34.0 A52 52 0 0 1 112.0 60.0 L90.0 60.0 A30 30 0 0 0 86.0 45.0 Z\" fill=\"#E0A93F\" opacity=\"1\"/><path d=\"M112.0 60.0 A52 52 0 0 1 105.0 86.0 L86.0 75.0 A30 30 0 0 0 90.0 60.0 Z\" fill=\"#D7C63F\" opacity=\"1\"/><path d=\"M105.0 86.0 A52 52 0 0 1 86.0 105.0 L75.0 86.0 A30 30 0 0 0 86.0 75.0 Z\" fill=\"#9DC44A\" opacity=\"1\"/><path d=\"M86.0 105.0 A52 52 0 0 1 60.0 112.0 L60.0 90.0 A30 30 0 0 0 75.0 86.0 Z\" fill=\"#5FB36A\" opacity=\"1\"/><path d=\"M60.0 112.0 A52 52 0 0 1 34.0 105.0 L45.0 86.0 A30 30 0 0 0 60.0 90.0 Z\" fill=\"#4CB0A6\" opacity=\"1\"/><path d=\"M34.0 105.0 A52 52 0 0 1 15.0 86.0 L34.0 75.0 A30 30 0 0 0 45.0 86.0 Z\" fill=\"#4C93C4\" opacity=\"1\"/><path d=\"M15.0 86.0 A52 52 0 0 1 8.0 60.0 L30.0 60.0 A30 30 0 0 0 34.0 75.0 Z\" fill=\"#5A6FC0\" opacity=\"1\"/><path d=\"M8.0 60.0 A52 52 0 0 1 15.0 34.0 L34.0 45.0 A30 30 0 0 0 30.0 60.0 Z\" fill=\"#7B5FC0\" opacity=\"1\"/><path d=\"M15.0 34.0 A52 52 0 0 1 34.0 15.0 L45.0 34.0 A30 30 0 0 0 34.0 45.0 Z\" fill=\"#A85FC0\" opacity=\"1\"/><path d=\"M34.0 15.0 A52 52 0 0 1 60.0 8.0 L60.0 30.0 A30 30 0 0 0 45.0 34.0 Z\" fill=\"#C45A93\" opacity=\"1\"/></svg></div><figcaption>12 色相環</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 120\" role=\"img\"><path d=\"M60.0 8.0 A52 52 0 0 1 86.0 15.0 L75.0 34.0 A30 30 0 0 0 60.0 30.0 Z\" fill=\"#E05A5A\" opacity=\"0.22\"/><path d=\"M86.0 15.0 A52 52 0 0 1 105.0 34.0 L86.0 45.0 A30 30 0 0 0 75.0 34.0 Z\" fill=\"#E0813F\" opacity=\"0.22\"/><path d=\"M105.0 34.0 A52 52 0 0 1 112.0 60.0 L90.0 60.0 A30 30 0 0 0 86.0 45.0 Z\" fill=\"#E0A93F\" opacity=\"0.22\"/><path d=\"M112.0 60.0 A52 52 0 0 1 105.0 86.0 L86.0 75.0 A30 30 0 0 0 90.0 60.0 Z\" fill=\"#D7C63F\" opacity=\"0.22\"/><path d=\"M105.0 86.0 A52 52 0 0 1 86.0 105.0 L75.0 86.0 A30 30 0 0 0 86.0 75.0 Z\" fill=\"#9DC44A\" opacity=\"0.22\"/><path d=\"M86.0 105.0 A52 52 0 0 1 60.0 112.0 L60.0 90.0 A30 30 0 0 0 75.0 86.0 Z\" fill=\"#5FB36A\" opacity=\"0.22\"/><path d=\"M60.0 112.0 A52 52 0 0 1 34.0 105.0 L45.0 86.0 A30 30 0 0 0 60.0 90.0 Z\" fill=\"#4CB0A6\" opacity=\"0.22\"/><path d=\"M34.0 105.0 A52 52 0 0 1 15.0 86.0 L34.0 75.0 A30 30 0 0 0 45.0 86.0 Z\" fill=\"#4C93C4\" opacity=\"0.22\"/><path d=\"M15.0 86.0 A52 52 0 0 1 8.0 60.0 L30.0 60.0 A30 30 0 0 0 34.0 75.0 Z\" fill=\"#5A6FC0\" opacity=\"1\"/><path d=\"M8.0 60.0 A52 52 0 0 1 15.0 34.0 L34.0 45.0 A30 30 0 0 0 30.0 60.0 Z\" fill=\"#7B5FC0\" opacity=\"1\"/><path d=\"M15.0 34.0 A52 52 0 0 1 34.0 15.0 L45.0 34.0 A30 30 0 0 0 34.0 45.0 Z\" fill=\"#A85FC0\" opacity=\"1\"/><path d=\"M34.0 15.0 A52 52 0 0 1 60.0 8.0 L60.0 30.0 A30 30 0 0 0 45.0 34.0 Z\" fill=\"#C45A93\" opacity=\"0.22\"/><polygon points=\"20.4,70.6 20.4,49.4 31.0,31.0\" fill=\"none\" stroke=\"#2A2138\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/></svg></div><figcaption>類似色・相鄰和諧</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 120\" role=\"img\"><path d=\"M60.0 8.0 A52 52 0 0 1 86.0 15.0 L75.0 34.0 A30 30 0 0 0 60.0 30.0 Z\" fill=\"#E05A5A\" opacity=\"1\"/><path d=\"M86.0 15.0 A52 52 0 0 1 105.0 34.0 L86.0 45.0 A30 30 0 0 0 75.0 34.0 Z\" fill=\"#E0813F\" opacity=\"0.22\"/><path d=\"M105.0 34.0 A52 52 0 0 1 112.0 60.0 L90.0 60.0 A30 30 0 0 0 86.0 45.0 Z\" fill=\"#E0A93F\" opacity=\"0.22\"/><path d=\"M112.0 60.0 A52 52 0 0 1 105.0 86.0 L86.0 75.0 A30 30 0 0 0 90.0 60.0 Z\" fill=\"#D7C63F\" opacity=\"0.22\"/><path d=\"M105.0 86.0 A52 52 0 0 1 86.0 105.0 L75.0 86.0 A30 30 0 0 0 86.0 75.0 Z\" fill=\"#9DC44A\" opacity=\"0.22\"/><path d=\"M86.0 105.0 A52 52 0 0 1 60.0 112.0 L60.0 90.0 A30 30 0 0 0 75.0 86.0 Z\" fill=\"#5FB36A\" opacity=\"0.22\"/><path d=\"M60.0 112.0 A52 52 0 0 1 34.0 105.0 L45.0 86.0 A30 30 0 0 0 60.0 90.0 Z\" fill=\"#4CB0A6\" opacity=\"1\"/><path d=\"M34.0 105.0 A52 52 0 0 1 15.0 86.0 L34.0 75.0 A30 30 0 0 0 45.0 86.0 Z\" fill=\"#4C93C4\" opacity=\"0.22\"/><path d=\"M15.0 86.0 A52 52 0 0 1 8.0 60.0 L30.0 60.0 A30 30 0 0 0 34.0 75.0 Z\" fill=\"#5A6FC0\" opacity=\"0.22\"/><path d=\"M8.0 60.0 A52 52 0 0 1 15.0 34.0 L34.0 45.0 A30 30 0 0 0 30.0 60.0 Z\" fill=\"#7B5FC0\" opacity=\"0.22\"/><path d=\"M15.0 34.0 A52 52 0 0 1 34.0 15.0 L45.0 34.0 A30 30 0 0 0 34.0 45.0 Z\" fill=\"#A85FC0\" opacity=\"0.22\"/><path d=\"M34.0 15.0 A52 52 0 0 1 60.0 8.0 L60.0 30.0 A30 30 0 0 0 45.0 34.0 Z\" fill=\"#C45A93\" opacity=\"0.22\"/><line x1=\"70.6\" y1=\"20.4\" x2=\"49.4\" y2=\"99.6\" stroke=\"#2A2138\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/></svg></div><figcaption>互補色・正對面最強</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 120\" role=\"img\"><path d=\"M60.0 8.0 A52 52 0 0 1 86.0 15.0 L75.0 34.0 A30 30 0 0 0 60.0 30.0 Z\" fill=\"#E05A5A\" opacity=\"1\"/><path d=\"M86.0 15.0 A52 52 0 0 1 105.0 34.0 L86.0 45.0 A30 30 0 0 0 75.0 34.0 Z\" fill=\"#E0813F\" opacity=\"0.22\"/><path d=\"M105.0 34.0 A52 52 0 0 1 112.0 60.0 L90.0 60.0 A30 30 0 0 0 86.0 45.0 Z\" fill=\"#E0A93F\" opacity=\"0.22\"/><path d=\"M112.0 60.0 A52 52 0 0 1 105.0 86.0 L86.0 75.0 A30 30 0 0 0 90.0 60.0 Z\" fill=\"#D7C63F\" opacity=\"0.22\"/><path d=\"M105.0 86.0 A52 52 0 0 1 86.0 105.0 L75.0 86.0 A30 30 0 0 0 86.0 75.0 Z\" fill=\"#9DC44A\" opacity=\"1\"/><path d=\"M86.0 105.0 A52 52 0 0 1 60.0 112.0 L60.0 90.0 A30 30 0 0 0 75.0 86.0 Z\" fill=\"#5FB36A\" opacity=\"0.22\"/><path d=\"M60.0 112.0 A52 52 0 0 1 34.0 105.0 L45.0 86.0 A30 30 0 0 0 60.0 90.0 Z\" fill=\"#4CB0A6\" opacity=\"0.22\"/><path d=\"M34.0 105.0 A52 52 0 0 1 15.0 86.0 L34.0 75.0 A30 30 0 0 0 45.0 86.0 Z\" fill=\"#4C93C4\" opacity=\"0.22\"/><path d=\"M15.0 86.0 A52 52 0 0 1 8.0 60.0 L30.0 60.0 A30 30 0 0 0 34.0 75.0 Z\" fill=\"#5A6FC0\" opacity=\"1\"/><path d=\"M8.0 60.0 A52 52 0 0 1 15.0 34.0 L34.0 45.0 A30 30 0 0 0 30.0 60.0 Z\" fill=\"#7B5FC0\" opacity=\"0.22\"/><path d=\"M15.0 34.0 A52 52 0 0 1 34.0 15.0 L45.0 34.0 A30 30 0 0 0 34.0 45.0 Z\" fill=\"#A85FC0\" opacity=\"0.22\"/><path d=\"M34.0 15.0 A52 52 0 0 1 60.0 8.0 L60.0 30.0 A30 30 0 0 0 45.0 34.0 Z\" fill=\"#C45A93\" opacity=\"0.22\"/><polygon points=\"70.6,20.4 89.0,89.0 20.4,70.6\" fill=\"none\" stroke=\"#2A2138\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/></svg></div><figcaption>三分色・等距三角</figcaption></figure>\n      </div>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 46\" role=\"img\">\n<rect x=\"0\" y=\"6\" width=\"144\" height=\"26\" rx=\"4\" fill=\"#7B6BB5\"/>\n<rect x=\"148\" y=\"6\" width=\"72\" height=\"26\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".45\"/>\n<rect x=\"224\" y=\"6\" width=\"16\" height=\"26\" rx=\"4\" fill=\"#B8892E\"/>\n<text x=\"60\" y=\"24\" font-size=\"11\" fill=\"#fff\">主色 60%</text>\n<text x=\"158\" y=\"24\" font-size=\"10\" fill=\"#fff\">輔 30%</text>\n<text x=\"196\" y=\"44\" font-size=\"9\" fill=\"#B8892E\">強調 10%</text></svg></div><figcaption>60-30-10 法則：主色定調、輔色豐富、強調色點睛</figcaption></figure>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 70\" role=\"img\">\n<rect x=\"2\" y=\"6\" width=\"112\" height=\"58\" rx=\"6\" fill=\"#6E5FA8\"/><circle cx=\"58\" cy=\"35\" r=\"18\" fill=\"#B9A9E0\"/>\n<text x=\"8\" y=\"20\" font-size=\"9\" fill=\"#fff\">明度有拉開 ✓</text>\n<rect x=\"126\" y=\"6\" width=\"112\" height=\"58\" rx=\"6\" fill=\"#8478B0\"/><circle cx=\"182\" cy=\"35\" r=\"18\" fill=\"#8B80B6\"/>\n<text x=\"132\" y=\"20\" font-size=\"9\" fill=\"#fff\">明度太近 ✗</text></svg></div><figcaption>明度測試：轉成單色仍分得出主角，才算明度足夠</figcaption></figure>\n    </div>\n    <div class=\"card\">\n      <h3>配色方案 <span class=\"tag gold\">照著配不會錯</span></h3>\n      <details><summary>單色（Monochrome）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"22\" width=\"16\" height=\"22\" rx=\"3\" fill=\"#4A3A80\"/><rect x=\"28\" y=\"22\" width=\"16\" height=\"22\" rx=\"3\" fill=\"#6E5FA8\"/><rect x=\"46\" y=\"22\" width=\"16\" height=\"22\" rx=\"3\" fill=\"#9184C4\"/><rect x=\"64\" y=\"22\" width=\"16\" height=\"22\" rx=\"3\" fill=\"#B4A9DC\"/></svg></span>同一個色相，只改<b>明度與彩度</b>（例：淺紫→紫→深紫）。最安全、最高級、最統一，缺點是容易單調——用材質差異救它。</p></details>\n      <details><summary>類似色（相鄰色）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 66 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"64\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M33.0 7.0 A26 26 0 0 1 46.0 10.5 L40.5 20.0 A15 15 0 0 0 33.0 18.0 Z\" fill=\"#E05A5A\" opacity=\"0.2\"/><path d=\"M46.0 10.5 A26 26 0 0 1 55.5 20.0 L46.0 25.5 A15 15 0 0 0 40.5 20.0 Z\" fill=\"#E0813F\" opacity=\"0.2\"/><path d=\"M55.5 20.0 A26 26 0 0 1 59.0 33.0 L48.0 33.0 A15 15 0 0 0 46.0 25.5 Z\" fill=\"#E0A93F\" opacity=\"0.2\"/><path d=\"M59.0 33.0 A26 26 0 0 1 55.5 46.0 L46.0 40.5 A15 15 0 0 0 48.0 33.0 Z\" fill=\"#D7C63F\" opacity=\"0.2\"/><path d=\"M55.5 46.0 A26 26 0 0 1 46.0 55.5 L40.5 46.0 A15 15 0 0 0 46.0 40.5 Z\" fill=\"#9DC44A\" opacity=\"0.2\"/><path d=\"M46.0 55.5 A26 26 0 0 1 33.0 59.0 L33.0 48.0 A15 15 0 0 0 40.5 46.0 Z\" fill=\"#5FB36A\" opacity=\"0.2\"/><path d=\"M33.0 59.0 A26 26 0 0 1 20.0 55.5 L25.5 46.0 A15 15 0 0 0 33.0 48.0 Z\" fill=\"#4CB0A6\" opacity=\"0.2\"/><path d=\"M20.0 55.5 A26 26 0 0 1 10.5 46.0 L20.0 40.5 A15 15 0 0 0 25.5 46.0 Z\" fill=\"#4C93C4\" opacity=\"0.2\"/><path d=\"M10.5 46.0 A26 26 0 0 1 7.0 33.0 L18.0 33.0 A15 15 0 0 0 20.0 40.5 Z\" fill=\"#5A6FC0\" opacity=\"1\"/><path d=\"M7.0 33.0 A26 26 0 0 1 10.5 20.0 L20.0 25.5 A15 15 0 0 0 18.0 33.0 Z\" fill=\"#7B5FC0\" opacity=\"1\"/><path d=\"M10.5 20.0 A26 26 0 0 1 20.0 10.5 L25.5 20.0 A15 15 0 0 0 20.0 25.5 Z\" fill=\"#A85FC0\" opacity=\"1\"/><path d=\"M20.0 10.5 A26 26 0 0 1 33.0 7.0 L33.0 18.0 A15 15 0 0 0 25.5 20.0 Z\" fill=\"#C45A93\" opacity=\"0.2\"/></svg></span>色環上相鄰的顏色（藍＋藍紫＋紫）。<b>和諧又比單色豐富</b>，是最推薦的日常配法。</p></details>\n      <details><summary>互補色（對比色）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 66 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"64\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M33.0 7.0 A26 26 0 0 1 46.0 10.5 L40.5 20.0 A15 15 0 0 0 33.0 18.0 Z\" fill=\"#E05A5A\" opacity=\"1\"/><path d=\"M46.0 10.5 A26 26 0 0 1 55.5 20.0 L46.0 25.5 A15 15 0 0 0 40.5 20.0 Z\" fill=\"#E0813F\" opacity=\"0.2\"/><path d=\"M55.5 20.0 A26 26 0 0 1 59.0 33.0 L48.0 33.0 A15 15 0 0 0 46.0 25.5 Z\" fill=\"#E0A93F\" opacity=\"0.2\"/><path d=\"M59.0 33.0 A26 26 0 0 1 55.5 46.0 L46.0 40.5 A15 15 0 0 0 48.0 33.0 Z\" fill=\"#D7C63F\" opacity=\"0.2\"/><path d=\"M55.5 46.0 A26 26 0 0 1 46.0 55.5 L40.5 46.0 A15 15 0 0 0 46.0 40.5 Z\" fill=\"#9DC44A\" opacity=\"0.2\"/><path d=\"M46.0 55.5 A26 26 0 0 1 33.0 59.0 L33.0 48.0 A15 15 0 0 0 40.5 46.0 Z\" fill=\"#5FB36A\" opacity=\"0.2\"/><path d=\"M33.0 59.0 A26 26 0 0 1 20.0 55.5 L25.5 46.0 A15 15 0 0 0 33.0 48.0 Z\" fill=\"#4CB0A6\" opacity=\"1\"/><path d=\"M20.0 55.5 A26 26 0 0 1 10.5 46.0 L20.0 40.5 A15 15 0 0 0 25.5 46.0 Z\" fill=\"#4C93C4\" opacity=\"0.2\"/><path d=\"M10.5 46.0 A26 26 0 0 1 7.0 33.0 L18.0 33.0 A15 15 0 0 0 20.0 40.5 Z\" fill=\"#5A6FC0\" opacity=\"0.2\"/><path d=\"M7.0 33.0 A26 26 0 0 1 10.5 20.0 L20.0 25.5 A15 15 0 0 0 18.0 33.0 Z\" fill=\"#7B5FC0\" opacity=\"0.2\"/><path d=\"M10.5 20.0 A26 26 0 0 1 20.0 10.5 L25.5 20.0 A15 15 0 0 0 20.0 25.5 Z\" fill=\"#A85FC0\" opacity=\"0.2\"/><path d=\"M20.0 10.5 A26 26 0 0 1 33.0 7.0 L33.0 18.0 A15 15 0 0 0 25.5 20.0 Z\" fill=\"#C45A93\" opacity=\"0.2\"/></svg></span>色環上正對面的顏色（紅↔綠、藍↔橙、黃↔紫）。<b>最強烈搶眼</b>，但很容易俗——訣竅是<b>一大一小</b>，主色大面積、補色只用一點點當點綴。</p></details>\n      <details><summary>三分色（三角配色）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 66 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"64\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M33.0 7.0 A26 26 0 0 1 46.0 10.5 L40.5 20.0 A15 15 0 0 0 33.0 18.0 Z\" fill=\"#E05A5A\" opacity=\"1\"/><path d=\"M46.0 10.5 A26 26 0 0 1 55.5 20.0 L46.0 25.5 A15 15 0 0 0 40.5 20.0 Z\" fill=\"#E0813F\" opacity=\"0.2\"/><path d=\"M55.5 20.0 A26 26 0 0 1 59.0 33.0 L48.0 33.0 A15 15 0 0 0 46.0 25.5 Z\" fill=\"#E0A93F\" opacity=\"0.2\"/><path d=\"M59.0 33.0 A26 26 0 0 1 55.5 46.0 L46.0 40.5 A15 15 0 0 0 48.0 33.0 Z\" fill=\"#D7C63F\" opacity=\"0.2\"/><path d=\"M55.5 46.0 A26 26 0 0 1 46.0 55.5 L40.5 46.0 A15 15 0 0 0 46.0 40.5 Z\" fill=\"#9DC44A\" opacity=\"1\"/><path d=\"M46.0 55.5 A26 26 0 0 1 33.0 59.0 L33.0 48.0 A15 15 0 0 0 40.5 46.0 Z\" fill=\"#5FB36A\" opacity=\"0.2\"/><path d=\"M33.0 59.0 A26 26 0 0 1 20.0 55.5 L25.5 46.0 A15 15 0 0 0 33.0 48.0 Z\" fill=\"#4CB0A6\" opacity=\"0.2\"/><path d=\"M20.0 55.5 A26 26 0 0 1 10.5 46.0 L20.0 40.5 A15 15 0 0 0 25.5 46.0 Z\" fill=\"#4C93C4\" opacity=\"0.2\"/><path d=\"M10.5 46.0 A26 26 0 0 1 7.0 33.0 L18.0 33.0 A15 15 0 0 0 20.0 40.5 Z\" fill=\"#5A6FC0\" opacity=\"1\"/><path d=\"M7.0 33.0 A26 26 0 0 1 10.5 20.0 L20.0 25.5 A15 15 0 0 0 18.0 33.0 Z\" fill=\"#7B5FC0\" opacity=\"0.2\"/><path d=\"M10.5 20.0 A26 26 0 0 1 20.0 10.5 L25.5 20.0 A15 15 0 0 0 20.0 25.5 Z\" fill=\"#A85FC0\" opacity=\"0.2\"/><path d=\"M20.0 10.5 A26 26 0 0 1 33.0 7.0 L33.0 18.0 A15 15 0 0 0 25.5 20.0 Z\" fill=\"#C45A93\" opacity=\"0.2\"/></svg></span>色環上等距的三色。活潑、豐富、有節慶感；同樣要<b>分主次</b>，不能三色等量。</p></details>\n      <details><summary>60-30-10 法則</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"58\" height=\"22\" rx=\"3\" fill=\"#7B6BB5\"/><rect x=\"68\" y=\"22\" width=\"28\" height=\"22\" rx=\"3\" fill=\"#7B6BB5\" opacity=\".45\"/><rect x=\"98\" y=\"22\" width=\"8\" height=\"22\" rx=\"2\" fill=\"#B8892E\"/></svg></span>最實用的比例公式：<b>主色 60%</b>（大面積、定調）＋<b>輔色 30%</b>（呼應、豐富度）＋<b>強調色 10%</b>（點睛，通常最亮或最豔）。搭配卡住時直接套這條。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>色彩心理與明度 <span class=\"tag ok\">氣氛控制</span></h3>\n      <ul class=\"tips\">\n        <li><b>明度決定氛圍</b>高明度（淺）＝輕盈、純潔、夢幻；低明度（深）＝厚重、神秘、高級。</li>\n        <li><b>彩度決定強度</b>高彩＝活潑張揚；低彩（灰調）＝優雅、成熟、電影感。<b>降低彩度是讓搭配變高級最快的方法</b>。</li>\n        <li><b>冷暖決定距離</b>暖色前進（顯大、親近）、冷色後退（顯遠、冷靜）。想讓主角跳出來：<b>暖主角＋冷背景</b>。</li>\n        <li><b>色彩情緒</b>白＝純潔／空白，黑＝神秘／哀悼，紅＝慾望／危險，藍＝憂鬱／寧靜，紫＝高貴／神秘，金銀＝華麗／冷冽。</li>\n        <li><b>無彩色是萬能潤滑劑</b>顏色太多打架時，加入黑白灰或金銀能立刻收攏整體。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>色彩理論基礎 <span class=\"tag gold\">三屬性與色相環</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">看懂顏色的三個座標，配色就不再靠感覺。</p>\n      <ul class=\"tips\">\n        <li><b>色相 Hue</b>顏色本身（紅、藍、綠…），即它在<b>色相環</b>上的位置。決定「是什麼顏色」。</li>\n        <li><b>明度 Value / Brightness</b>亮到暗的程度。<b>明度是三者中最重要的</b>——把畫面轉成黑白，如果分不出主角，就是明度沒拉開。</li>\n        <li><b>彩度 Saturation / Chroma</b>顏色的鮮豔程度。高彩＝強烈；低彩（加灰）＝優雅高級。</li>\n        <li><b>原色→間色→複色</b>色料三原色（紅黃藍）混出間色（橙綠紫），再混出複色（灰調的中間色）。<b>複色最耐看</b>，是高級配色的主力。</li>\n        <li><b>色相環的距離＝關係</b>相鄰（30°內）＝類似色，和諧；90°＝中差色，有變化；180°＝互補色，最強對比。</li>\n        <li><b>顏色沒有絕對，只有關係</b>同一個灰放在暗背景顯亮、放在亮背景顯暗（<b>同時對比</b>）。永遠要看整體，不要單看一塊。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>伊登七大色彩對比 <span class=\"tag hot\">Itten</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">包浩斯大師約翰・伊登整理的七種對比，是配色設計的完整工具箱。</p>\n      <details><summary>① 色相對比</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 66 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"64\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M33.0 7.0 A26 26 0 0 1 46.0 10.5 L40.5 20.0 A15 15 0 0 0 33.0 18.0 Z\" fill=\"#E05A5A\" opacity=\"1\"/><path d=\"M46.0 10.5 A26 26 0 0 1 55.5 20.0 L46.0 25.5 A15 15 0 0 0 40.5 20.0 Z\" fill=\"#E0813F\" opacity=\"0.2\"/><path d=\"M55.5 20.0 A26 26 0 0 1 59.0 33.0 L48.0 33.0 A15 15 0 0 0 46.0 25.5 Z\" fill=\"#E0A93F\" opacity=\"0.2\"/><path d=\"M59.0 33.0 A26 26 0 0 1 55.5 46.0 L46.0 40.5 A15 15 0 0 0 48.0 33.0 Z\" fill=\"#D7C63F\" opacity=\"0.2\"/><path d=\"M55.5 46.0 A26 26 0 0 1 46.0 55.5 L40.5 46.0 A15 15 0 0 0 46.0 40.5 Z\" fill=\"#9DC44A\" opacity=\"1\"/><path d=\"M46.0 55.5 A26 26 0 0 1 33.0 59.0 L33.0 48.0 A15 15 0 0 0 40.5 46.0 Z\" fill=\"#5FB36A\" opacity=\"0.2\"/><path d=\"M33.0 59.0 A26 26 0 0 1 20.0 55.5 L25.5 46.0 A15 15 0 0 0 33.0 48.0 Z\" fill=\"#4CB0A6\" opacity=\"0.2\"/><path d=\"M20.0 55.5 A26 26 0 0 1 10.5 46.0 L20.0 40.5 A15 15 0 0 0 25.5 46.0 Z\" fill=\"#4C93C4\" opacity=\"0.2\"/><path d=\"M10.5 46.0 A26 26 0 0 1 7.0 33.0 L18.0 33.0 A15 15 0 0 0 20.0 40.5 Z\" fill=\"#5A6FC0\" opacity=\"1\"/><path d=\"M7.0 33.0 A26 26 0 0 1 10.5 20.0 L20.0 25.5 A15 15 0 0 0 18.0 33.0 Z\" fill=\"#7B5FC0\" opacity=\"0.2\"/><path d=\"M10.5 20.0 A26 26 0 0 1 20.0 10.5 L25.5 20.0 A15 15 0 0 0 20.0 25.5 Z\" fill=\"#A85FC0\" opacity=\"0.2\"/><path d=\"M20.0 10.5 A26 26 0 0 1 33.0 7.0 L33.0 18.0 A15 15 0 0 0 25.5 20.0 Z\" fill=\"#C45A93\" opacity=\"0.2\"/></svg></span>純色相之間的差異，如紅 vs 藍 vs 黃。<b>最原始、最強烈、最有活力</b>，但也最容易顯得幼稚。用色相對比時，記得<b>拉開面積比例</b>。</p></details>\n      <details><summary>② 明暗對比</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"20\" width=\"40\" height=\"26\" rx=\"3\" fill=\"#EEE9F6\"/><rect x=\"60\" y=\"20\" width=\"40\" height=\"26\" rx=\"3\" fill=\"#2A2138\"/></svg></span>亮與暗的對比，<b>最重要的一種</b>。黑白照片只剩明暗對比，卻依然好看，就是證明。明暗對比不足＝畫面糊在一起。</p></details>\n      <details><summary>③ 冷暖對比</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"20\" width=\"40\" height=\"26\" rx=\"3\" fill=\"#D8823F\"/><rect x=\"60\" y=\"20\" width=\"40\" height=\"26\" rx=\"3\" fill=\"#4C93C4\"/></svg></span>暖色（紅橙黃）與冷色（藍青綠）的對比。同時帶來<b>空間感</b>（暖前進、冷後退）與<b>情緒</b>（暖情感、冷理性）。<b>冷背景＋暖主角</b>是萬用配方。</p></details>\n      <details><summary>④ 補色對比</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 66 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"64\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M33.0 7.0 A26 26 0 0 1 46.0 10.5 L40.5 20.0 A15 15 0 0 0 33.0 18.0 Z\" fill=\"#E05A5A\" opacity=\"1\"/><path d=\"M46.0 10.5 A26 26 0 0 1 55.5 20.0 L46.0 25.5 A15 15 0 0 0 40.5 20.0 Z\" fill=\"#E0813F\" opacity=\"0.2\"/><path d=\"M55.5 20.0 A26 26 0 0 1 59.0 33.0 L48.0 33.0 A15 15 0 0 0 46.0 25.5 Z\" fill=\"#E0A93F\" opacity=\"0.2\"/><path d=\"M59.0 33.0 A26 26 0 0 1 55.5 46.0 L46.0 40.5 A15 15 0 0 0 48.0 33.0 Z\" fill=\"#D7C63F\" opacity=\"0.2\"/><path d=\"M55.5 46.0 A26 26 0 0 1 46.0 55.5 L40.5 46.0 A15 15 0 0 0 46.0 40.5 Z\" fill=\"#9DC44A\" opacity=\"0.2\"/><path d=\"M46.0 55.5 A26 26 0 0 1 33.0 59.0 L33.0 48.0 A15 15 0 0 0 40.5 46.0 Z\" fill=\"#5FB36A\" opacity=\"0.2\"/><path d=\"M33.0 59.0 A26 26 0 0 1 20.0 55.5 L25.5 46.0 A15 15 0 0 0 33.0 48.0 Z\" fill=\"#4CB0A6\" opacity=\"1\"/><path d=\"M20.0 55.5 A26 26 0 0 1 10.5 46.0 L20.0 40.5 A15 15 0 0 0 25.5 46.0 Z\" fill=\"#4C93C4\" opacity=\"0.2\"/><path d=\"M10.5 46.0 A26 26 0 0 1 7.0 33.0 L18.0 33.0 A15 15 0 0 0 20.0 40.5 Z\" fill=\"#5A6FC0\" opacity=\"0.2\"/><path d=\"M7.0 33.0 A26 26 0 0 1 10.5 20.0 L20.0 25.5 A15 15 0 0 0 18.0 33.0 Z\" fill=\"#7B5FC0\" opacity=\"0.2\"/><path d=\"M10.5 20.0 A26 26 0 0 1 20.0 10.5 L25.5 20.0 A15 15 0 0 0 20.0 25.5 Z\" fill=\"#A85FC0\" opacity=\"0.2\"/><path d=\"M20.0 10.5 A26 26 0 0 1 33.0 7.0 L33.0 18.0 A15 15 0 0 0 25.5 20.0 Z\" fill=\"#C45A93\" opacity=\"0.2\"/></svg></span>色相環上正對面的兩色（紅↔綠）。彼此使對方看起來更鮮豔，張力最大；<b>切忌等量使用</b>，務必一大一小。</p></details>\n      <details><summary>⑤ 彩度對比（純度對比）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"20\" width=\"40\" height=\"26\" rx=\"3\" fill=\"#9A8FB0\"/><rect x=\"60\" y=\"20\" width=\"40\" height=\"26\" rx=\"3\" fill=\"#8A2FC0\"/></svg></span>鮮豔色與混濁色並置。<b>灰調中的一點鮮色最抓眼</b>——這是最優雅的強調方式，比互補色柔和得多。</p></details>\n      <details><summary>⑥ 面積對比</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"20\" width=\"76\" height=\"26\" rx=\"3\" fill=\"#5A6FC0\"/><rect x=\"88\" y=\"24\" width=\"14\" height=\"18\" rx=\"2\" fill=\"#E0C63F\"/></svg></span>色塊大小的對比。伊登指出：<b>顏色的視覺強度不同，需要的面積也不同</b>。黃色亮而強，一點就夠；紫色暗而弱，需要大面積才平衡。這是 60-30-10 法則的理論來源。</p></details>\n      <details><summary>⑦ 同時對比</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"18\" width=\"44\" height=\"30\" rx=\"3\" fill=\"#C0554E\"/><rect x=\"58\" y=\"18\" width=\"44\" height=\"30\" rx=\"3\" fill=\"#3D8E5A\"/><circle cx=\"30\" cy=\"33\" r=\"7\" fill=\"#9A9A9A\"/><circle cx=\"80\" cy=\"33\" r=\"7\" fill=\"#9A9A9A\"/></svg></span><b>視錯覺現象</b>：同一個顏色，在不同背景上看起來會不一樣（灰色在紅底上會偏綠）。這提醒我們——<b>配色永遠是「關係」，不是絕對值</b>，改背景就等於改了主體的顏色。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>更多配色方案 <span class=\"tag gold\">進階組合</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">除了單色／類似／互補／三分，還有這些更細緻的配法。</p>\n      <details><summary>分裂互補 Split-Complementary</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"31\" height=\"22\" rx=\"3\" fill=\"#5A6FC0\"/><rect x=\"41\" y=\"22\" width=\"31\" height=\"22\" rx=\"3\" fill=\"#E0A93F\"/><rect x=\"74\" y=\"22\" width=\"31\" height=\"22\" rx=\"3\" fill=\"#E05A5A\"/></svg></span>取一個主色，配它互補色<b>左右兩側</b>的顏色（而非正對面那一個）。<br>好處：<b>保有互補的對比張力，卻不像純互補那麼衝</b>，更好駕馭。新手想用對比又怕俗，這是最安全的選擇。</p></details>\n      <details><summary>四方（矩形）配色 Tetradic</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#5A6FC0\"/><rect x=\"33\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#E0813F\"/><rect x=\"58\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#C45A93\"/><rect x=\"83\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#9DC44A\"/></svg></span>色環上<b>兩組互補色</b>（形成矩形），共四色。色彩最豐富、最華麗，但也最難平衡——<b>務必選一色為主，其餘為輔</b>，並注意冷暖各半的分配。</p></details>\n      <details><summary>正方配色 Square</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#E05A5A\"/><rect x=\"33\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#9DC44A\"/><rect x=\"58\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#4C93C4\"/><rect x=\"83\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#A85FC0\"/></svg></span>色環上等距的<b>四個色</b>（正方形）。比矩形更均衡但更難統一，適合繽紛、節慶、童趣主題；同樣要壓低其中三色、突出一色。</p></details>\n      <details><summary>雙色調 Duotone</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"44\" height=\"22\" rx=\"3\" fill=\"#2A2138\"/><rect x=\"54\" y=\"22\" width=\"44\" height=\"22\" rx=\"3\" fill=\"#B4A9DC\"/></svg></span>整個畫面<b>只用兩個顏色</b>（通常一深一淺）貫穿，連陰影和高光都染上這兩色。<br>效果：<b>極度統一、有強烈風格感與印刷海報味</b>，是現代設計的熱門手法。暗黑、復古海報最愛用。</p></details>\n      <details><summary>大地色系 Earth Tones</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#6E4A2A\"/><rect x=\"33\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#A9834E\"/><rect x=\"58\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#C7B08A\"/><rect x=\"83\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#8A7A4A\"/></svg></span>棕、褐、卡其、橄欖、赭紅、米——取自自然的低彩暖色群。<b>天生和諧、溫暖、耐看、有質感</b>，因為它們本來就常在自然中並存。復古、和風、秋季主題的萬用底。</p></details>\n      <details><summary>莫蘭迪色 Morandi</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#9E9AA6\"/><rect x=\"33\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#AFA6A0\"/><rect x=\"58\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#A6ADAA\"/><rect x=\"83\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#B6ACB4\"/></svg></span>義大利畫家莫蘭迪愛用的<b>高級灰</b>——每個顏色都<b>掺入灰</b>、降低彩度到接近。<br>效果：柔和、寧靜、高雅、不張揚。<b>「高級感」的祕密就是全部降彩</b>，讓顏色們處在同一個灰階層級。</p></details>\n      <details><summary>馬卡龍／粉彩 Pastel</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#F3C6D6\"/><rect x=\"33\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#C6E8D6\"/><rect x=\"58\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#F3E8B8\"/><rect x=\"83\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#D6C6E8\"/></svg></span>高明度、低到中彩度的<b>淺甜色</b>（粉、薄荷、鵝黃、藕紫）。<br>效果：柔軟、夢幻、可愛、青春。仙氣與少女風的主力；訣竅是<b>明度都拉高、彩度都壓低</b>，讓它們是一家人。</p></details>\n      <details><summary>霓虹／螢光 Neon</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#2A2138\"/><rect x=\"8\" y=\"22\" width=\"28\" height=\"22\" rx=\"3\" fill=\"#39FF9E\"/><rect x=\"38\" y=\"22\" width=\"28\" height=\"22\" rx=\"3\" fill=\"#FF3D9A\"/><rect x=\"68\" y=\"22\" width=\"28\" height=\"22\" rx=\"3\" fill=\"#3DE0FF\"/></svg></span>極高彩度的亮色配<b>深色（尤其黑）背景</b>，製造發光感。<br>效果：強烈、前衛、賽博、未來。<b>一定要配暗底</b>才會「亮起來」；亮色本身也不宜超過兩三種。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>進階色彩觀念 <span class=\"tag ok\">拉開層次</span></h3>\n      <details><summary>固有色・光源色・環境色</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"34\" cy=\"33\" r=\"15\" fill=\"#C8A0A0\"/><circle cx=\"34\" cy=\"33\" r=\"15\" fill=\"#E0A040\" opacity=\".28\"/><path d=\"M49 33 A15 15 0 0 1 64 20\" fill=\"none\"/><rect x=\"70\" y=\"20\" width=\"30\" height=\"26\" rx=\"4\" fill=\"#B03030\" opacity=\".25\"/></svg></span>物體的顏色其實是三者疊加：<b>固有色</b>（物件本來的色）＋<b>光源色</b>（打光的顏色，暖光讓白布偏黃）＋<b>環境色</b>（周圍反射過來的光，紅牆旁的白裙會泛紅）。<br>畫面高不高級，往往差在有沒有讓環境色「串起」整個畫面。</p></details>\n      <details><summary>冷暖不是絕對的</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"44\" height=\"22\" rx=\"3\" fill=\"#C43A5A\"/><rect x=\"54\" y=\"22\" width=\"44\" height=\"22\" rx=\"3\" fill=\"#E0603A\"/></svg></span>同一色相也有冷暖之分——<b>偏藍的紅（洋紅）是冷紅，偏橙的紅（朱紅）是暖紅</b>。高手配色會在「暖色裡找冷、冷色裡找暖」，讓同色系也有呼吸。</p></details>\n      <details><summary>灰的重要性</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"44\" height=\"22\" rx=\"3\" fill=\"#8E96A6\"/><rect x=\"54\" y=\"22\" width=\"44\" height=\"22\" rx=\"3\" fill=\"#A69890\"/></svg></span><b>沒有純灰，只有帶色的灰</b>——偏藍的冷灰、偏棕的暖灰。畫面裡大面積的灰決定了整體調性。想沉穩用暖灰，想清冷用冷灰。<b>會用灰，才算會配色。</b></p></details>\n      <details><summary>對比色的面積法則</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"20\" width=\"76\" height=\"26\" rx=\"3\" fill=\"#5A6FC0\"/><rect x=\"88\" y=\"24\" width=\"14\" height=\"18\" rx=\"2\" fill=\"#E0C63F\"/></svg></span>越鮮豔、越亮的顏色，需要的<b>面積越小</b>就能平衡。伊登給的理想比例：黃:橙:紅:紫:藍:綠 ≈ 3:4:6:9:8:6（越弱的色需要越大面積）。實務上記住一句：<b>豔色點綴、濁色打底。</b></p></details>\n      <details><summary>色彩的前進與後退</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#3A4A7A\"/><circle cx=\"55\" cy=\"33\" r=\"14\" fill=\"#E0813F\"/></svg></span><b>暖色、亮色、高彩色會「前進」</b>（顯得靠近、放大）；<b>冷色、暗色、低彩色會「後退」</b>（顯得遠、縮小）。想讓主角跳出來就給它前進色，想讓背景退後就給它後退色——這是製造空間深度的色彩手段。</p></details>\n      <details><summary>主色調（Tonal统一）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"14\" width=\"26\" height=\"16\" rx=\"3\" fill=\"#E05A5A\"/><rect x=\"42\" y=\"14\" width=\"26\" height=\"16\" rx=\"3\" fill=\"#4C93C4\"/><rect x=\"76\" y=\"14\" width=\"26\" height=\"16\" rx=\"3\" fill=\"#9DC44A\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#E0A040\" opacity=\".3\"/></svg></span>讓整個畫面<b>罩上一層統一的色調</b>（例如全部偏暖黃、或全部偏冷藍），就像蒙了一層有色玻璃。這是電影調色的核心手法，能瞬間把雜亂的顏色收成一個氛圍。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>色輪配色法則 <span class=\"tag hot\">七種幾何取色</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">以下每一種配色法，都是從色輪上按幾何關係取色。掌握這些，就能從「憑感覺配」進階到「有邏輯地配」。上方分析會自動判讀你的作品屬於哪一種，並給出幾何吻合度。</p>\n      <details><summary>單色搭配</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">只取一個色相，透過改變明度與彩度建立層次。</b><i><b>攝影</b>日系藍調寫真，從淺藍天到深藍海，靠明暗層次而非色彩衝突說故事。</i><i><b>繪畫</b>畢卡索藍色時期，整幅畫浸在冷藍的單色調裡，把悲傷與貧困統合到極致。</i><i><b>設計</b>極簡品牌視覺、Apple 產品頁常只用一個色相搭配黑白灰，乾淨克制。</i></p></details>\n      <details><summary>類似色搭配</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">取色輪上相鄰的 2–4 色（如黃、黃綠、綠），彼此有共同色素。</b><i><b>攝影</b>秋天色調（紅、橙、黃），豐富有層次但不衝突，是自然界最常見的和諧配色。</i><i><b>繪畫</b>莫內的乾草堆，落日天空由橙、粉、淡紫構成，相鄰色的微妙過渡營造出發光的空氣感。</i><i><b>設計</b>養生、有機品牌常用綠色系搭配黃綠或藍綠，傳達自然、健康與放鬆。</i></p></details>\n      <details><summary>互補色搭配</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">取色輪上正對面的兩色（紅與綠、藍與橙、黃與紫），對比最強烈。</b><i><b>攝影</b>日落的橙金天空與下方暗藍剪影，冷暖互補把張力拉到最大。</i><i><b>繪畫</b>梵谷《夜晚露天咖啡座》，黃色燈光與深藍夜空直接對撞，兩色各自「發亮」。</i><i><b>設計</b>運動品牌、促銷海報最愛。需控制面積比例避免俗豔，常見安全公式是主色 70%、互補色 30%。</i></p></details>\n      <details><summary>分裂互補色搭配</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">取一個主色，再用它互補色左右兩邊的顏色搭配。比直接互補更柔和、更難出錯。</b><i><b>攝影</b>藍天下橘紅與粉色的建築並存，對比有了，但橘紅與粉之間是類似色，整體更協調。</i><i><b>繪畫</b>人物膚色暖黃，背景用藍綠與藍紫，冷暖對比成立，背景本身又有層次。</i><i><b>設計</b>介面主按鈕為藍色，輔助提示用橘黃與紅，視覺跳躍但不刺眼。</i></p></details>\n      <details><summary>三角色搭配</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">在色輪上取等邊三角形的三頂點（如紅、黃、藍），豐富、平衡又有活力。</b><i><b>攝影</b>遊樂園場景中紅氣球、黃設施、藍天空各佔一角，畫面活潑有童趣。</i><i><b>繪畫</b>蒙德里安的幾何抽象，直接用紅黃藍三原色搭黑白灰格子，是最純粹的視覺平衡。</i><i><b>設計</b>兒童品牌、教育產品常用紅黃藍，象徵活力、創造力與純粹的快樂。</i></p></details>\n      <details><summary>矩形（四角色）搭配</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">取色輪上矩形的四個頂點，其實是兩組互補色的組合。極豐富，需要很強的掌控力。</b><i><b>攝影</b>城市夜景的霓虹同時有藍、橙、紅、綠，繽紛但容易雜亂，適合表現都市喧囂。</i><i><b>繪畫</b>高更的塔希提畫作，紅土、綠葉、黃膚、紫影交織出異域的豐饒感。</i><i><b>設計</b>大膽的插畫海報或潮流品牌，關鍵是讓其中一色主導面積，其餘三色小面積點綴。</i></p></details>\n      <details><summary>無彩色搭配</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">只用黑、白、灰，完全抽離色相。</b><i><b>攝影</b>黑白紀實攝影，剝離色彩干擾，強迫觀眾凝視光影、紋理、表情與構圖的本質。</i><i><b>繪畫</b>中國水墨以墨代色，「墨分五色」，用單一黑色的濃淡乾濕創造比彩色更豐富的意境。</i><i><b>設計</b>極簡海報、高端時尚品牌，黑白灰傳達永恆、冷靜與絕對的現代感。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>風格色系與色卡 <span class=\"tag gold\">可直接取用</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 6px\">以下色卡附十六進制色碼，可直接貼進設計軟體，或作為攝影調色、繪畫配色的參考。分析報告的「風格色系」欄會告訴你作品最接近哪一組。</p>\n      <details><summary>莫蘭迪色系（高級灰）</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">所有顏色都加入一層灰調，低飽和、中高明度，溫柔克制耐看。</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#C2A4A3\"><b style=\"color:#1B1226\">灰粉<em>#C2A4A3</em></b></i><i style=\"background:#A3B5A6\"><b style=\"color:#1B1226\">灰綠<em>#A3B5A6</em></b></i><i style=\"background:#8D9CA9\"><b style=\"color:#1B1226\">灰藍<em>#8D9CA9</em></b></i><i style=\"background:#C1B9B0\"><b style=\"color:#1B1226\">暖灰<em>#C1B9B0</em></b></i><i style=\"background:#B0A1B4\"><b style=\"color:#1B1226\">灰紫<em>#B0A1B4</em></b></i></div>\n        <p class=\"lens3\"><i><b>攝影</b>降低飽和度、提高暗部灰階，歐美博主最愛的柔和色調。</i><i><b>繪畫</b>莫蘭迪本人的靜物油畫，瓶罐全被一層灰調統合，極度靜謐。</i><i><b>設計</b>北歐風家居、文青咖啡店、護膚品牌的視覺首選。</i></p></details>\n      <details><summary>馬卡龍色系</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">高明度、中低飽和，粉嫩甜美，充滿輕盈感。</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#F2C4CE\"><b style=\"color:#1B1226\">草莓粉<em>#F2C4CE</em></b></i><i style=\"background:#C0E3D4\"><b style=\"color:#1B1226\">薄荷綠<em>#C0E3D4</em></b></i><i style=\"background:#FDE7C4\"><b style=\"color:#1B1226\">奶油黃<em>#FDE7C4</em></b></i><i style=\"background:#D6C9E2\"><b style=\"color:#1B1226\">薰衣草紫<em>#D6C9E2</em></b></i><i style=\"background:#C2D9EA\"><b style=\"color:#1B1226\">天空藍<em>#C2D9EA</em></b></i></div>\n        <p class=\"lens3\"><i><b>攝影</b>過曝一檔再降低對比度，得到輕盈的空氣感寫真。</i><i><b>繪畫</b>洛可可時期的粉彩油畫，描繪貴族生活的輕盈甜美。</i><i><b>設計</b>甜品店、母嬰品牌、春季限定包裝的標準配色。</i></p></details>\n      <details><summary>大地色系</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">以棕、褐、米、卡其、橄欖綠為主，取自土壤、岩石、木材，溫暖沉穩。</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#B8A68B\"><b style=\"color:#1B1226\">卡其<em>#B8A68B</em></b></i><i style=\"background:#B27A5E\"><b style=\"color:#FFFFFF\">陶土棕<em>#B27A5E</em></b></i><i style=\"background:#7E8B68\"><b style=\"color:#FFFFFF\">橄欖綠<em>#7E8B68</em></b></i><i style=\"background:#F5F0E6\"><b style=\"color:#1B1226\">米白<em>#F5F0E6</em></b></i><i style=\"background:#5C4332\"><b style=\"color:#FFFFFF\">深棕<em>#5C4332</em></b></i></div>\n        <p class=\"lens3\"><i><b>攝影</b>咖啡廳、皮革、木質調的靜物攝影，色溫偏暖。</i><i><b>繪畫</b>林布蘭肖像中的服裝色系，深褐與暖金交織，厚重而真摯。</i><i><b>設計</b>戶外品牌、文創文具，營造可靠與質樸。</i></p></details>\n      <details><summary>黑白灰極簡（無彩色）</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">徹底去除色彩，僅以明度對比構成。</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#FFFFFF\"><b style=\"color:#1B1226\">純白<em>#FFFFFF</em></b></i><i style=\"background:#E0E0E0\"><b style=\"color:#1B1226\">淺灰<em>#E0E0E0</em></b></i><i style=\"background:#999999\"><b style=\"color:#1B1226\">中灰<em>#999999</em></b></i><i style=\"background:#3D3D3D\"><b style=\"color:#FFFFFF\">深灰<em>#3D3D3D</em></b></i><i style=\"background:#000000\"><b style=\"color:#FFFFFF\">純黑<em>#000000</em></b></i></div>\n        <p class=\"lens3\"><i><b>攝影</b>森山大道式的高反差黑白街拍，只剩光影的絕對力量。</i><i><b>繪畫</b>水墨、炭筆素描，用灰階探討造型的本質。</i><i><b>設計</b>蘋果官網、無印良品、高級時裝品牌。</i></p></details>\n      <details><summary>霓虹色系</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">極高飽和、中高亮度，彷彿發光，帶強烈的數位感與街頭氣息。</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#BF5FFF\"><b style=\"color:#1B1226\">電光紫<em>#BF5FFF</em></b></i><i style=\"background:#39FF14\"><b style=\"color:#1B1226\">螢光綠<em>#39FF14</em></b></i><i style=\"background:#FF69B4\"><b style=\"color:#1B1226\">熱力粉<em>#FF69B4</em></b></i><i style=\"background:#FF8C00\"><b style=\"color:#1B1226\">亮橙<em>#FF8C00</em></b></i><i style=\"background:#00E5FF\"><b style=\"color:#1B1226\">青藍<em>#00E5FF</em></b></i></div>\n        <p class=\"lens3\"><i><b>攝影</b>夜晚街頭的霓虹招牌、UV 螢光人像。</i><i><b>繪畫</b>普普藝術、哈林的街頭塗鴉，用螢光色製造直接的身體衝擊。</i><i><b>設計</b>音樂節海報、運動潮牌、賽博朋克 UI。</i></p></details>\n      <details><summary>復古褪色系</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">低飽和、偏暖偏黃，模擬舊照片與老印刷品因時間而褪色的效果。</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#E8D8B8\"><b style=\"color:#1B1226\">舊紙黃<em>#E8D8B8</em></b></i><i style=\"background:#C25A5A\"><b style=\"color:#FFFFFF\">褪色紅<em>#C25A5A</em></b></i><i style=\"background:#7A9A9E\"><b style=\"color:#1B1226\">老照片青<em>#7A9A9E</em></b></i><i style=\"background:#A68A6B\"><b style=\"color:#1B1226\">暖褐<em>#A68A6B</em></b></i><i style=\"background:#B5A898\"><b style=\"color:#1B1226\">灰卡其<em>#B5A898</em></b></i></div>\n        <p class=\"lens3\"><i><b>攝影</b>膠片模擬、日系復古濾鏡，陰影加入黃綠或青色。</i><i><b>繪畫</b>老廣告畫、手繪電影海報因歲月褪色後的溫柔色調。</i><i><b>設計</b>懷舊咖啡廳菜單、復古包裝，訴說時間的故事。</i></p></details>\n      <details><summary>賽博朋克色系</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">冷色（青藍、紫）為主調，暖色（洋紅、橙）作為高光與點綴，高對比高飽和。</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#1A0B2E\"><b style=\"color:#FFFFFF\">暗夜紫<em>#1A0B2E</em></b></i><i style=\"background:#00F0FF\"><b style=\"color:#1B1226\">霓虹青<em>#00F0FF</em></b></i><i style=\"background:#FF007F\"><b style=\"color:#FFFFFF\">洋紅<em>#FF007F</em></b></i><i style=\"background:#0D1B2A\"><b style=\"color:#FFFFFF\">深藍<em>#0D1B2A</em></b></i><i style=\"background:#F5A623\"><b style=\"color:#1B1226\">暖金<em>#F5A623</em></b></i></div>\n        <p class=\"lens3\"><i><b>攝影</b>香港、東京雨夜街頭的燈光調色，青藍陰影加洋紅高光。</i><i><b>繪畫</b>科幻插畫、未來都市概念圖，用冷暖螢光對比定義整個流派。</i><i><b>設計</b>遊戲海報、電競品牌、科幻電影標題字。</i></p></details>\n      <details><summary>孟菲斯風格色系</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">大量明快、飽和甚至衝突的色彩，搭配幾何圖形與波點，拒絕極簡、擁抱裝飾與玩心。</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#FF6B6B\"><b style=\"color:#1B1226\">珊瑚粉<em>#FF6B6B</em></b></i><i style=\"background:#FFD93D\"><b style=\"color:#1B1226\">銘黃<em>#FFD93D</em></b></i><i style=\"background:#6BCB77\"><b style=\"color:#1B1226\">草綠<em>#6BCB77</em></b></i><i style=\"background:#9B59B6\"><b style=\"color:#FFFFFF\">亮紫<em>#9B59B6</em></b></i><i style=\"background:#2C3E50\"><b style=\"color:#FFFFFF\">墨藍黑<em>#2C3E50</em></b></i></div>\n        <p class=\"lens3\"><i><b>攝影</b>極具風格的置景攝影，用彩色背景紙與幾何道具搭出超現實空間。</i><i><b>繪畫</b>80 年代後現代繪畫回歸裝飾性，用平塗色塊與幾何解構畫面。</i><i><b>設計</b>孟菲斯小組的家具與海報，影響至今的 UI 插畫與社群視覺。</i></p></details>\n    </div>\n", "ae-style": "\n    <div class=\"card\">\n      <h3>風格配方圖解 <span class=\"tag hot\">光＋色一眼對照</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">小臉示意<b>光的位置與明暗</b>，色條是<b>建議配色</b>。</p>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#F3EFF9\"/><circle cx=\"42\" cy=\"40\" r=\"20\" fill=\"#F7ECEC\"/><circle cx=\"42\" cy=\"40\" r=\"20\" fill=\"#EEDFE8\" opacity=\".5\"/><circle cx=\"42\" cy=\"40\" r=\"20\" fill=\"none\" stroke=\"#FFF3C4\" stroke-width=\"2.5\"/>\n<circle cx=\"42\" cy=\"8\" r=\"4\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\"><line x1=\"35\" y1=\"8\" x2=\"38\" y2=\"8\"/><line x1=\"46\" y1=\"8\" x2=\"49\" y2=\"8\"/><line x1=\"42\" y1=\"1\" x2=\"42\" y2=\"4\"/></g><rect x=\"76\" y=\"14\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#FFFFFF\"/><rect x=\"76\" y=\"31\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#EAD9F0\"/><rect x=\"76\" y=\"48\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#CFE0F0\"/><rect x=\"76\" y=\"65\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#DCD2EC\"/></svg></div><figcaption>仙氣：逆光柔光＋高明度低彩，關鍵是輪廓光與朦朧</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#221C2E\"/><circle cx=\"42\" cy=\"40\" r=\"20\" fill=\"#E9DBDB\"/><path d=\"M42 20 A20 20 0 0 1 42 60 Z\" fill=\"#100B18\" opacity=\".72\"/>\n<circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\"><line x1=\"7\" y1=\"14\" x2=\"10\" y2=\"14\"/><line x1=\"18\" y1=\"14\" x2=\"21\" y2=\"14\"/><line x1=\"14\" y1=\"7\" x2=\"14\" y2=\"10\"/></g><rect x=\"76\" y=\"14\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#141019\"/><rect x=\"76\" y=\"31\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#3A2140\"/><rect x=\"76\" y=\"48\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#7C1F1F\"/><rect x=\"76\" y=\"65\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#C9A94E\"/></svg></div><figcaption>哥德：硬光明暗＋深色，一個高彩重點色（血紅／金）</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#EDE7E0\"/><circle cx=\"42\" cy=\"40\" r=\"20\" fill=\"#F3E7DD\"/><path d=\"M42 20 A20 20 0 0 0 42 60 Z\" fill=\"#CFC2B4\" opacity=\".55\"/>\n<circle cx=\"78\" cy=\"40\" r=\"4\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\"><line x1=\"71\" y1=\"40\" x2=\"74\" y2=\"40\"/><line x1=\"82\" y1=\"40\" x2=\"85\" y2=\"40\"/><line x1=\"78\" y1=\"33\" x2=\"78\" y2=\"36\"/></g><rect x=\"76\" y=\"14\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#F0EBE3\"/><rect x=\"76\" y=\"31\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#D8A7A0\"/><rect x=\"76\" y=\"48\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#C7B7D6\"/><rect x=\"76\" y=\"65\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#AFC0C4\"/></svg></div><figcaption>和風：柔側光＋傳統低彩色，留白很重要</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#2A2119\"/><circle cx=\"42\" cy=\"40\" r=\"20\" fill=\"#E6D3BE\"/><path d=\"M42 20 A20 20 0 0 1 42 60 Z\" fill=\"#191008\" opacity=\".68\"/><polygon points=\"47,39 55,44 47,49\" fill=\"#E6D3BE\"/>\n<circle cx=\"18\" cy=\"14\" r=\"4\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\"><line x1=\"11\" y1=\"14\" x2=\"14\" y2=\"14\"/><line x1=\"22\" y1=\"14\" x2=\"25\" y2=\"14\"/><line x1=\"18\" y1=\"7\" x2=\"18\" y2=\"10\"/></g><rect x=\"76\" y=\"14\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#241A10\"/><rect x=\"76\" y=\"31\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#4A3520\"/><rect x=\"76\" y=\"48\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#6E4A2A\"/><rect x=\"76\" y=\"65\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#B8892E\"/></svg></div><figcaption>復古：林布蘭光＋降彩做舊，純白換米白、純黑換墨褐</figcaption></figure>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3>質感圖解 <span class=\"tag ok\">光怎麼落在表面</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">材質＝高光的形狀。看高光就能判斷是什麼材質。</p>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"10\" width=\"100\" height=\"52\" rx=\"8\" fill=\"#6E5FA8\"/><rect x=\"18\" y=\"30\" width=\"84\" height=\"7\" rx=\"3.5\" fill=\"#D9CBF2\" opacity=\".9\"/><text x=\"60\" y=\"80\" font-size=\"10\" fill=\"#2A2138\" text-anchor=\"middle\">絲緞・長柔高光帶</text></svg></div><figcaption>絲緞／緞面</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"10\" width=\"100\" height=\"52\" rx=\"8\" fill=\"#3A2846\"/><rect x=\"10\" y=\"10\" width=\"100\" height=\"52\" rx=\"8\" fill=\"none\" stroke=\"#9B7DB8\" stroke-width=\"4\" opacity=\".6\"/><text x=\"60\" y=\"80\" font-size=\"10\" fill=\"#2A2138\" text-anchor=\"middle\">天鵝絨・邊緣泛光中心吃光</text></svg></div><figcaption>天鵝絨</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"10\" width=\"100\" height=\"52\" rx=\"8\" fill=\"#8891A0\"/><polygon points=\"20,14 30,14 22,58 12,58\" fill=\"#FFFFFF\" opacity=\".95\"/><rect x=\"10\" y=\"40\" width=\"100\" height=\"22\" rx=\"6\" fill=\"#2E3440\" opacity=\".35\"/><text x=\"60\" y=\"80\" font-size=\"10\" fill=\"#2A2138\" text-anchor=\"middle\">金屬・銳利高光＋強反射</text></svg></div><figcaption>金屬</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"10\" width=\"100\" height=\"52\" rx=\"8\" fill=\"#C9B79E\"/><rect x=\"10\" y=\"10\" width=\"100\" height=\"52\" rx=\"8\" fill=\"#000\" opacity=\".04\"/><text x=\"60\" y=\"80\" font-size=\"10\" fill=\"#2A2138\" text-anchor=\"middle\">棉麻／和紙・幾乎無高光</text></svg></div><figcaption>棉麻・和紙</figcaption></figure></div>\n    </div>\n    <div class=\"card\">\n      <h3>風格配方圖解 <span class=\"tag hot\">光＋色一眼看</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">上半是<b>光位與明暗</b>（黃點＝光源方向），下方色條是<b>建議配色</b>。</p>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#F3EFF9\"/>\n<circle cx=\"60\" cy=\"40\" r=\"30\" fill=\"#FFFFFF\" opacity=\".4\"/><circle cx=\"60\" cy=\"34\" r=\"18\" fill=\"#F8ECE6\"/><circle cx=\"60\" cy=\"34\" r=\"18\" fill=\"#fff\" opacity=\".25\"/><circle cx=\"60\" cy=\"34\" r=\"18\" fill=\"none\" stroke=\"#FFF6DE\" stroke-width=\"2.5\"/>\n<circle cx=\"60\" cy=\"10\" r=\"4.5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\" opacity=\".8\">\n<line x1=\"52\" y1=\"10\" x2=\"55\" y2=\"10\"/><line x1=\"65\" y1=\"10\" x2=\"68\" y2=\"10\"/>\n<line x1=\"60\" y1=\"2\" x2=\"60\" y2=\"5\"/><line x1=\"60\" y1=\"15\" x2=\"60\" y2=\"18\"/></g>\n<rect x=\"8.0\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#FFFFFF\"/><rect x=\"28.8\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#F0E9DE\"/><rect x=\"49.6\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#DDE7F2\"/><rect x=\"70.4\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#E6DEF2\"/><rect x=\"91.2\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#D8D2E6\"/></svg></div><figcaption>仙氣：逆光＋輪廓光、高明度低彩度</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#1E1A28\"/>\n<circle cx=\"60\" cy=\"34\" r=\"18\" fill=\"#E8DDE0\"/><path d=\"M60 16 A18 18 0 0 1 60 52 Z\" fill=\"#00000066\"/><circle cx=\"60\" cy=\"34\" r=\"18\" fill=\"none\" stroke=\"#C9A24B\" stroke-width=\"2.5\"/>\n<circle cx=\"18\" cy=\"14\" r=\"4.5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\" opacity=\".8\">\n<line x1=\"10\" y1=\"14\" x2=\"13\" y2=\"14\"/><line x1=\"23\" y1=\"14\" x2=\"26\" y2=\"14\"/>\n<line x1=\"18\" y1=\"6\" x2=\"18\" y2=\"9\"/><line x1=\"18\" y1=\"19\" x2=\"18\" y2=\"22\"/></g>\n<rect x=\"8.0\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#15121C\"/><rect x=\"28.8\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#3A2740\"/><rect x=\"49.6\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#5A2233\"/><rect x=\"70.4\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#8A1F2E\"/><rect x=\"91.2\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#C9A24B\"/></svg></div><figcaption>哥德：側光＋大片暗、一抹血紅／金</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#EDE9F0\"/>\n<rect x=\"0\" y=\"0\" width=\"120\" height=\"92\" fill=\"#B9C0D8\" opacity=\".08\"/><circle cx=\"60\" cy=\"34\" r=\"18\" fill=\"#F3E9E2\"/><path d=\"M60 16 A18 18 0 0 1 60 52 Z\" fill=\"#0000001A\"/>\n<circle cx=\"16\" cy=\"30\" r=\"4.5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\" opacity=\".8\">\n<line x1=\"8\" y1=\"30\" x2=\"11\" y2=\"30\"/><line x1=\"21\" y1=\"30\" x2=\"24\" y2=\"30\"/>\n<line x1=\"16\" y1=\"22\" x2=\"16\" y2=\"25\"/><line x1=\"16\" y1=\"35\" x2=\"16\" y2=\"38\"/></g>\n<rect x=\"8.0\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#F5F2EC\"/><rect x=\"28.8\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#E8D8D0\"/><rect x=\"49.6\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#D8C8E0\"/><rect x=\"70.4\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#DCE2E0\"/><rect x=\"91.2\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#C9BCC6\"/></svg></div><figcaption>和風：柔側光、低彩傳統色、多留白</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#2A2018\"/>\n<circle cx=\"60\" cy=\"34\" r=\"18\" fill=\"#EAD9C4\"/><path d=\"M60 16 A18 18 0 0 1 60 52 Z\" fill=\"#00000055\"/><polygon points=\"66,32 74,37 66,42\" fill=\"#EAD9C4\"/>\n<circle cx=\"24\" cy=\"14\" r=\"4.5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\" opacity=\".8\">\n<line x1=\"16\" y1=\"14\" x2=\"19\" y2=\"14\"/><line x1=\"29\" y1=\"14\" x2=\"32\" y2=\"14\"/>\n<line x1=\"24\" y1=\"6\" x2=\"24\" y2=\"9\"/><line x1=\"24\" y1=\"19\" x2=\"24\" y2=\"22\"/></g>\n<rect x=\"8.0\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#6B4A2E\"/><rect x=\"28.8\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#8A5A32\"/><rect x=\"49.6\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#7A2E2E\"/><rect x=\"70.4\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#3A4A32\"/><rect x=\"91.2\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#C9A24B\"/></svg></div><figcaption>復古：林布蘭光、降彩做舊、酒紅金褐</figcaption></figure>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3>風格配方 <span class=\"tag gold\">照著配</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">每種風格都有慣用的光、色與構圖組合。直接套用，再依喜好微調。</p>\n      <details><summary>仙氣・空靈系</summary>\n        <p><b>光｜</b>逆光或高調柔光。逆光讓紗、蕾絲、髮絲透光發亮，是仙氣的靈魂；避免硬光與濃重陰影。<br><b>色｜</b>高明度、<b>低彩度</b>——白、香檳、淺藍、淡紫、銀。單色或類似色為主，整體<b>對比要弱</b>。<br><b>構圖｜</b>大量留白、中央或三分法、視線望向遠方；加入飄浮元素（花瓣、光斑、羽毛）。<br><b>質感｜</b>薄紗、雪紡、蕾絲、珍珠——輕、透、會飄的材質。<br><b>關鍵｜</b>朦朧感。<b>寧可淡一點，也不要重</b>。</p></details>\n      <details><summary>哥德・暗黑系</summary>\n        <p><b>光｜</b>硬光＋<b>明暗法</b>（大片暗中一束光），或底光製造不安；務必加<b>輪廓光</b>，否則黑衣會融進黑背景。<br><b>色｜</b>低明度為主——黑、墨、暗紫、深紅。<b>用一個高彩重點色</b>（血紅、金）點睛，其餘壓暗。<br><b>構圖｜</b>對稱（莊嚴）或倒三角（不安）；框架式構圖（拱門、鐵柵、簾幕）非常適合。<br><b>質感｜</b>天鵝絨、皮革、金屬、黑蕾絲——重、硬、有光澤反差的材質。<br><b>關鍵｜</b>對比。<b>暗要夠暗，亮點要夠準</b>。</p></details>\n      <details><summary>和風系</summary>\n        <p><b>光｜</b>柔和的側光或斜射光（像從紙門透進來的光）；月夜題材可用冷調逆光。<br><b>色｜</b><b>低彩度的傳統色</b>——白妙、退紅、淡藤、月白、灰櫻。<b>留白（間）非常重要</b>，忌滿版。<br><b>構圖｜</b>非對稱、偏置構圖（日本美學的「不完全」）；善用直線分割（門框、屏風、垂簾）。<br><b>質感｜</b>絹、綸子、和紙、漆器——啞光、細緻、含蓄的光澤。<br><b>關鍵｜</b>餘白與季節感。加一枝櫻、一片雪、一輪月，勝過十件配件。</p></details>\n      <details><summary>復古・古典油畫系</summary>\n        <p><b>光｜</b><b>林布蘭光</b>（45° 斜上），暗部厚實。<br><b>色｜</b>降彩度＋加一點黃棕做舊；深綠、酒紅、金褐。<br><b>構圖｜</b>中央或三角構圖，端正穩定；背景用厚重簾幕或室內場景。<br><b>質感｜</b>天鵝絨、織錦、金線刺繡。<br><b>關鍵｜</b>沉穩。<b>把純白換成米白、純黑換成墨褐</b>，古典感立刻出來。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>質感與材質 <span class=\"tag ok\">看得見的觸感</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">材質＝光在表面的反應方式。掌握它，畫面才有「摸得到」的說服力。</p>\n      <ul class=\"tips\">\n        <li><b>光澤度是關鍵</b>絲綢／緞面＝<b>長而柔的高光帶</b>；天鵝絨＝<b>邊緣泛光、中心吃光</b>；金屬＝<b>銳利高光＋強反射</b>；棉麻／和紙＝幾乎無高光的<b>啞光</b>。</li>\n        <li><b>透光材質靠逆光</b>紗、蕾絲、雪紡要<b>從背後打光</b>才會透亮；順光下它們只是白布。</li>\n        <li><b>質感對比法則</b>同一套裡放<b>兩種相反質感</b>最好看——柔紗配硬皮革、啞光配亮面、粗織配細珠。全套同質感會顯得平。</li>\n        <li><b>粗糙度影響距離感</b>細緻光滑＝精緻、高級、冷；粗糙毛絨＝溫暖、親近、樸實。</li>\n        <li><b>質感也有重量</b>皮革、金屬、天鵝絨視覺上「重」，紗與蕾絲「輕」——重的放下方（裙襬、靴），輕的放上方或外層，畫面才穩。</li>\n        <li><b>細節密度要分配</b>不能全身都是滿版蕾絲＋刺繡＋亮片。<b>選一個區域做重點</b>，其餘留簡單，這叫密度對比。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>質感圖解 <span class=\"tag ok\">高光＝觸感</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">材質差別就在<b>光怎麼落在表面</b>。</p>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 84\"><rect width=\"120\" height=\"84\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<rect x=\"14\" y=\"14\" width=\"92\" height=\"42\" rx=\"6\" fill=\"#6E5FA8\"/><rect x=\"20\" y=\"20\" width=\"80\" height=\"7\" rx=\"3\" fill=\"#fff\" opacity=\".55\"/><rect x=\"20\" y=\"40\" width=\"60\" height=\"4\" rx=\"2\" fill=\"#fff\" opacity=\".25\"/>\n<text x=\"60\" y=\"74\" font-size=\"10\" fill=\"#fff\" text-anchor=\"middle\">絲緞・長柔高光</text></svg></div><figcaption>絲緞：一條長而柔的高光</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 84\"><rect width=\"120\" height=\"84\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<rect x=\"14\" y=\"14\" width=\"92\" height=\"42\" rx=\"6\" fill=\"#3A2A48\"/><rect x=\"14\" y=\"14\" width=\"92\" height=\"42\" rx=\"6\" fill=\"none\" stroke=\"#B79AD0\" stroke-width=\"4\" opacity=\".5\"/>\n<text x=\"60\" y=\"74\" font-size=\"10\" fill=\"#fff\" text-anchor=\"middle\">天鵝絨・邊緣泛光</text></svg></div><figcaption>天鵝絨：邊緣亮、中心吃光</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 84\"><rect width=\"120\" height=\"84\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<rect x=\"14\" y=\"14\" width=\"92\" height=\"42\" rx=\"6\" fill=\"#8892A0\"/><polygon points=\"22,20 34,20 24,50 16,50\" fill=\"#fff\" opacity=\".85\"/><rect x=\"60\" y=\"18\" width=\"40\" height=\"38\" rx=\"4\" fill=\"#000\" opacity=\".2\"/>\n<text x=\"60\" y=\"74\" font-size=\"10\" fill=\"#fff\" text-anchor=\"middle\">金屬・銳利高光反射</text></svg></div><figcaption>金屬：銳利高光＋強反射</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 84\"><rect width=\"120\" height=\"84\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<rect x=\"14\" y=\"14\" width=\"92\" height=\"42\" rx=\"6\" fill=\"#C9BBA8\"/>\n<text x=\"60\" y=\"74\" font-size=\"10\" fill=\"#2A2138\" text-anchor=\"middle\">棉麻／和紙・啞光無高光</text></svg></div><figcaption>棉麻／和紙：幾乎無高光</figcaption></figure>\n      </div>\n      <p class=\"fine\" style=\"margin-top:8px\">訣竅：一套裡放<b>兩種相反質感</b>（柔紗配硬皮革）最耐看。</p>\n    </div>\n", "ae-type": "\n    <div class=\"card\">\n      <h3>文字排版圖解 <span class=\"tag hot\">看圖就懂</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">每組都是<b>錯（✗）vs 對（✓）</b>對照，照著右邊做就對了。</p>\n\n      <p class=\"cond\" style=\"margin:14px 0 4px\"><b>① 三類字型的個性</b></p>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 80\"><rect width=\"120\" height=\"80\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<text x=\"60\" y=\"42\" font-size=\"34\" font-family=\"Georgia,'Times New Roman',serif\" fill=\"#2A2138\" text-anchor=\"middle\" font-weight=\"700\">Aa</text>\n<text x=\"60\" y=\"64\" font-size=\"10\" fill=\"#7B6BB5\" text-anchor=\"middle\">襯線・優雅古典</text></svg></div><figcaption>襯線＝優雅古典</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 80\"><rect width=\"120\" height=\"80\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<text x=\"60\" y=\"42\" font-size=\"34\" font-family=\"Arial,Helvetica,sans-serif\" fill=\"#2A2138\" text-anchor=\"middle\" font-weight=\"700\">Aa</text>\n<text x=\"60\" y=\"64\" font-size=\"10\" fill=\"#7B6BB5\" text-anchor=\"middle\">無襯線・現代清晰</text></svg></div><figcaption>無襯線＝現代清晰</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 80\"><rect width=\"120\" height=\"80\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<text x=\"60\" y=\"44\" font-size=\"34\" font-family=\"'Brush Script MT','Segoe Script',cursive\" fill=\"#2A2138\" text-anchor=\"middle\" font-style=\"italic\">Aa</text>\n<text x=\"60\" y=\"64\" font-size=\"10\" fill=\"#7B6BB5\" text-anchor=\"middle\">手寫・浪漫（少用）</text></svg></div><figcaption>手寫＝浪漫、只少量用</figcaption></figure></div>\n\n      <p class=\"cond\" style=\"margin:16px 0 4px\"><b>② 兩字型搭配：要對比，不要相似</b></p>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 90\"><rect width=\"240\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<text x=\"16\" y=\"38\" font-size=\"20\" font-family=\"Arial\" fill=\"#2A2138\" font-weight=\"700\">Title</text>\n<text x=\"16\" y=\"62\" font-size=\"15\" font-family=\"Helvetica\" fill=\"#2A2138\">內文 body text</text>\n<text x=\"16\" y=\"82\" font-size=\"10\" fill=\"#C0554E\">兩個都是無襯線、大小又接近 → 說不清誰是誰</text></svg></div><figcaption><span style=\"color:#C0554E\">✗ 兩個都無襯線、大小又接近</span>　<span style=\"color:#3D8E8A\">✓ 襯線標題＋無襯線內文</span></figcaption></figure>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 90\"><rect width=\"240\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<text x=\"16\" y=\"40\" font-size=\"26\" font-family=\"Georgia,serif\" fill=\"#2A2138\" font-weight=\"700\">Title</text>\n<text x=\"16\" y=\"64\" font-size=\"13\" font-family=\"Arial,sans-serif\" fill=\"#2A2138\">內文 body text</text>\n<text x=\"16\" y=\"83\" font-size=\"10\" fill=\"#3D8E8A\">襯線標題＋無襯線內文，明顯不同 → 清楚</text></svg></div><figcaption>訣竅：要嘛差很多，要嘛用同一家族的不同粗細</figcaption></figure>\n\n      <p class=\"cond\" style=\"margin:16px 0 4px\"><b>③ 建立層級（先看什麼、再看什麼）</b></p>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 96\"><rect width=\"240\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<text x=\"14\" y=\"26\" font-size=\"13\" fill=\"#2A2138\">春季新裝上市</text>\n<text x=\"14\" y=\"46\" font-size=\"13\" fill=\"#2A2138\">全系列八折優惠</text>\n<text x=\"14\" y=\"66\" font-size=\"13\" fill=\"#2A2138\">即日起至月底</text>\n<text x=\"14\" y=\"88\" font-size=\"10\" fill=\"#C0554E\">全部一樣大 → 不知道先看哪</text></svg></div><figcaption>全部一樣大 → 讀者不知道先看哪</figcaption></figure>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 96\"><rect width=\"240\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<text x=\"14\" y=\"34\" font-size=\"21\" font-weight=\"700\" fill=\"#2A2138\">春季新裝</text>\n<text x=\"14\" y=\"56\" font-size=\"14\" fill=\"#8A5FC0\" font-weight=\"700\">全系列八折</text>\n<text x=\"14\" y=\"74\" font-size=\"11\" fill=\"#2A2138\" opacity=\".7\">即日起至月底</text>\n<text x=\"14\" y=\"90\" font-size=\"10\" fill=\"#3D8E8A\">大小粗細顏色拉開 → 一眼看出順序</text></svg></div><figcaption>用大小・粗細・顏色拉開 → 順序自然浮現</figcaption></figure>\n\n      <p class=\"cond\" style=\"margin:16px 0 4px\"><b>④ 平面設計四原則 CRAP</b></p>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"14\" y=\"40\" font-size=\"24\" font-weight=\"800\" fill=\"#2A2138\">Big</text><text x=\"14\" y=\"66\" font-size=\"11\" fill=\"#2A2138\" opacity=\".7\">small quiet text</text></svg></div><figcaption>對比 Contrast：大就大、小就小</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"20\" cy=\"30\" r=\"6\" fill=\"#8A5FC0\"/><circle cx=\"42\" cy=\"30\" r=\"6\" fill=\"#8A5FC0\"/><circle cx=\"64\" cy=\"30\" r=\"6\" fill=\"#8A5FC0\"/><circle cx=\"86\" cy=\"30\" r=\"6\" fill=\"#8A5FC0\"/><rect x=\"15\" y=\"52\" width=\"12\" height=\"12\" rx=\"3\" fill=\"#7B6BB5\"/><rect x=\"37\" y=\"52\" width=\"12\" height=\"12\" rx=\"3\" fill=\"#7B6BB5\"/><rect x=\"59\" y=\"52\" width=\"12\" height=\"12\" rx=\"3\" fill=\"#7B6BB5\"/><rect x=\"81\" y=\"52\" width=\"12\" height=\"12\" rx=\"3\" fill=\"#7B6BB5\"/><text x=\"16\" y=\"86\" font-size=\"9\" fill=\"#3D8E8A\">重複同款元素</text></svg></div><figcaption>重複 Repetition：同款元素貫穿</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"8\" x2=\"60\" y2=\"88\" stroke=\"#C0554E\" stroke-dasharray=\"3 3\" opacity=\".4\"/><text x=\"18\" y=\"30\" font-size=\"11\" fill=\"#2A2138\">歪的</text><text x=\"52\" y=\"50\" font-size=\"11\" fill=\"#2A2138\">亂的</text><text x=\"30\" y=\"72\" font-size=\"11\" fill=\"#2A2138\">排版</text><text x=\"8\" y=\"90\" font-size=\"9\" fill=\"#C0554E\">✗ 沒對齊</text></svg></div><figcaption>對齊：亂擺 ✗</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"18\" y1=\"14\" x2=\"18\" y2=\"76\" stroke=\"#3D8E8A\" stroke-dasharray=\"3 3\"/><text x=\"22\" y=\"30\" font-size=\"11\" fill=\"#2A2138\">齊左</text><text x=\"22\" y=\"50\" font-size=\"11\" fill=\"#2A2138\">的</text><text x=\"22\" y=\"70\" font-size=\"11\" fill=\"#2A2138\">排版</text><text x=\"8\" y=\"92\" font-size=\"9\" fill=\"#3D8E8A\">✓ 對齊</text></svg></div><figcaption>對齊：齊左 ✓</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"14\" y=\"26\" font-size=\"10\" fill=\"#2A2138\">標題 A</text><text x=\"14\" y=\"40\" font-size=\"9\" fill=\"#2A2138\" opacity=\".6\">內文 a</text><text x=\"14\" y=\"58\" font-size=\"10\" fill=\"#2A2138\">標題 B</text><text x=\"14\" y=\"72\" font-size=\"9\" fill=\"#2A2138\" opacity=\".6\">內文 b</text><text x=\"8\" y=\"90\" font-size=\"8.5\" fill=\"#C0554E\">✗ 間距一樣分不出組</text></svg></div><figcaption>親密性：間距一樣 ✗</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"14\" y=\"24\" font-size=\"10\" fill=\"#2A2138\">標題 A</text><text x=\"14\" y=\"37\" font-size=\"9\" fill=\"#2A2138\" opacity=\".6\">內文 a</text><text x=\"14\" y=\"62\" font-size=\"10\" fill=\"#2A2138\">標題 B</text><text x=\"14\" y=\"75\" font-size=\"9\" fill=\"#2A2138\" opacity=\".6\">內文 b</text><text x=\"8\" y=\"92\" font-size=\"8.5\" fill=\"#3D8E8A\">✓ 拉開＝分組清楚</text></svg></div><figcaption>親密性：相關的靠近 ✓</figcaption></figure>\n      </div>\n\n      <p class=\"cond\" style=\"margin:16px 0 4px\"><b>⑤ 行距與行長</b></p>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 160 96\"><rect width=\"160\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"14\" y=\"16\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"25\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"34\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"43\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><text x=\"14\" y=\"88\" font-size=\"9\" fill=\"#C0554E\">✗ 行距太擠</text></svg></div><figcaption>行距太擠</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 160 96\"><rect width=\"160\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"14\" y=\"14\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"29\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"44\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"59\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><text x=\"14\" y=\"90\" font-size=\"9\" fill=\"#3D8E8A\">✓ 行距 1.5 倍</text></svg></div><figcaption>行距約 1.5 倍</figcaption></figure></div>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 78\"><rect width=\"240\" height=\"78\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"14\" y=\"16\" width=\"214\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"28\" width=\"214\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"40\" width=\"214\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><text x=\"14\" y=\"66\" font-size=\"9\" fill=\"#C0554E\">✗ 一行太長，找不到下一行</text></svg></div><figcaption>一行太長</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 78\"><rect width=\"240\" height=\"78\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"14\" y=\"14\" width=\"150\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"25\" width=\"150\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"36\" width=\"150\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"47\" width=\"150\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><text x=\"14\" y=\"70\" font-size=\"9\" fill=\"#3D8E8A\">✓ 一行 15–35 字最好讀</text></svg></div><figcaption>一行 15–35 字</figcaption></figure></div>\n\n      <p class=\"cond\" style=\"margin:16px 0 4px\"><b>⑥ 文字放到圖片上</b></p>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#8478A8\"/>\n<g fill=\"#B8A9D8\" opacity=\".85\"><circle cx=\"30\" cy=\"40\" r=\"16\"/><circle cx=\"66\" cy=\"30\" r=\"12\"/><circle cx=\"90\" cy=\"58\" r=\"18\"/><circle cx=\"46\" cy=\"70\" r=\"14\"/></g>\n<text x=\"60\" y=\"52\" font-size=\"13\" fill=\"#EDE7F5\" text-anchor=\"middle\" font-weight=\"700\">TITLE</text>\n<text x=\"60\" y=\"90\" font-size=\"8.5\" fill=\"#C0554E\" text-anchor=\"middle\">✗ 壓在雜亂處看不清</text></svg></div><figcaption>壓在最花的地方</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#8478A8\"/>\n<g fill=\"#B8A9D8\" opacity=\".85\"><circle cx=\"26\" cy=\"66\" r=\"15\"/><circle cx=\"58\" cy=\"76\" r=\"12\"/><circle cx=\"94\" cy=\"70\" r=\"16\"/></g>\n<rect x=\"0\" y=\"0\" width=\"120\" height=\"42\" fill=\"#2A2138\" opacity=\".28\"/>\n<text x=\"60\" y=\"28\" font-size=\"13\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">TITLE</text>\n<text x=\"60\" y=\"90\" font-size=\"8.5\" fill=\"#3D8E8A\" text-anchor=\"middle\">✓ 放留白＋墊暗底</text></svg></div><figcaption>放留白＋墊暗底／陰影</figcaption></figure></div>\n    </div>\n    <div class=\"card\">\n      <h3>視覺動線圖解 <span class=\"tag ok\">眼睛的路徑</span></h3>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\" opacity=\"0\"/><rect x=\"4\" y=\"4\" width=\"112\" height=\"82\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M18 20 L102 20 L18 70 L102 70\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"18\" cy=\"20\" r=\"4\" fill=\"#3D8E8A\"/><circle cx=\"102\" cy=\"70\" r=\"4\" fill=\"#B8892E\"/></svg></div><figcaption>Z 型・圖像為主的版面</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\" opacity=\"0\"/><rect x=\"4\" y=\"4\" width=\"112\" height=\"82\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M18 20 L100 20 M18 20 L18 74 M18 44 L82 44\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><circle cx=\"18\" cy=\"20\" r=\"4\" fill=\"#3D8E8A\"/></svg></div><figcaption>F 型・文字為主的版面</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\" opacity=\"0\"/><rect x=\"4\" y=\"4\" width=\"112\" height=\"82\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"8\" x2=\"60\" y2=\"82\" stroke=\"#DDD6E8\"/><line x1=\"8\" y1=\"45\" x2=\"112\" y2=\"45\" stroke=\"#DDD6E8\"/>\n<text x=\"14\" y=\"26\" font-size=\"8\" fill=\"#3D8E8A\">主視覺</text><text x=\"72\" y=\"26\" font-size=\"8\" fill=\"#7B6BB5\">強休息</text>\n<text x=\"14\" y=\"66\" font-size=\"8\" fill=\"#C05555\">弱休息</text><text x=\"72\" y=\"66\" font-size=\"8\" fill=\"#B8892E\">終點</text>\n<path d=\"M22 32 L98 60\" stroke=\"#8A5FC0\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/></svg></div><figcaption>古騰堡：左下是死角，重點別放</figcaption></figure>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3>字體的個性 <span class=\"tag gold\">選字＝選語氣</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">字體本身就會說話。同一句話換個字體，氣質完全不同。</p>\n      <details><summary>襯線體（Serif／明體・宋體）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"55\" y=\"46\" font-size=\"34\" font-family=\"Georgia,serif\" fill=\"#2A2138\" text-anchor=\"middle\" font-weight=\"700\">Aa</text></svg></span>筆畫末端有<b>小裝飾腳（襯線）</b>。個性：<b>古典、正式、文學、優雅</b>。適合哥德、復古、品牌名、詩句。中文的<b>明體／宋體</b>同理，橫細直粗、有頓角。</p></details>\n      <details><summary>無襯線體（Sans-serif／黑體）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"55\" y=\"46\" font-size=\"34\" font-family=\"Arial,sans-serif\" fill=\"#2A2138\" text-anchor=\"middle\" font-weight=\"700\">Aa</text></svg></span>沒有裝飾腳，線條乾淨。個性：<b>現代、簡潔、清晰、中性</b>。適合說明文字、UI、現代簡約風。小字閱讀性最好。</p></details>\n      <details><summary>手寫體・書法體（Script）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"55\" y=\"47\" font-size=\"34\" font-family=\"'Segoe Script',cursive\" fill=\"#2A2138\" text-anchor=\"middle\" font-style=\"italic\">Aa</text></svg></span>模擬手寫或書法。個性：<b>浪漫、personal、優雅或隨性</b>。<b>只能少量使用</b>——整段用手寫體會非常難讀。適合簽名、標題、一句話。</p></details>\n      <details><summary>裝飾體（Display）</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"55\" y=\"47\" font-size=\"32\" font-family=\"Georgia,serif\" fill=\"#2A2138\" text-anchor=\"middle\" font-weight=\"800\" letter-spacing=\"1\">A✦</text></svg></span>為標題設計的特殊字體（哥德黑體、藝術字）。個性極強但<b>可讀性低</b>，<b>只用在標題、絕不用在內文</b>。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>字體搭配原則 <span class=\"tag ok\">不出錯</span></h3>\n      <ul class=\"tips\">\n        <li><b>最多兩種字體</b>一種當標題、一種當內文就夠了。三種以上幾乎必亂。</li>\n        <li><b>要對比，不要相似</b>兩個字體要嘛<b>明顯不同</b>（襯線＋無襯線＝黃金組合），要嘛就用<b>同一家族</b>的不同粗細。似像非像最難看。</li>\n        <li><b>建立層級</b>標題 → 副標 → 內文，靠<b>大小、粗細、顏色</b>拉開差距。層級不清＝讀者不知道先看哪。</li>\n        <li><b>行距（行高）</b>約字級的 <b>1.4～1.8 倍</b>最好讀。太擠壓迫、太鬆散開。</li>\n        <li><b>字距</b>大標題可以<b>縮緊</b>更有力；小字或全大寫則<b>放寬</b>才清楚。</li>\n        <li><b>行長</b>一行約 <b>15～35 字</b>（中文）最舒適，太長會找不到下一行。</li>\n        <li><b>對比要足</b>淺色底配淺色字＝災難。文字永遠要和背景有明顯明度差。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>平面設計四大原則 <span class=\"tag hot\">CRAP</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">出自《寫給大家看的設計書》，是排版的黃金四條。</p>\n      <details><summary>對比 Contrast</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"14\" y=\"38\" font-size=\"22\" font-weight=\"800\" fill=\"#2A2138\">Aa</text><text x=\"60\" y=\"40\" font-size=\"10\" fill=\"#2A2138\" opacity=\".6\">small</text></svg></span>不同的元素就要<b>差很多</b>——大小、粗細、顏色、字體。<b>怕就怕「有點像又不太像」</b>。對比不足是新手排版最常見的問題。</p></details>\n      <details><summary>重複 Repetition</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"20\" cy=\"24\" r=\"4\" fill=\"#8A5FC0\"/><circle cx=\"40\" cy=\"24\" r=\"4\" fill=\"#8A5FC0\"/><circle cx=\"60\" cy=\"24\" r=\"4\" fill=\"#8A5FC0\"/><circle cx=\"80\" cy=\"24\" r=\"4\" fill=\"#8A5FC0\"/><rect x=\"16\" y=\"40\" width=\"10\" height=\"10\" rx=\"2\" fill=\"#7B6BB5\"/><rect x=\"36\" y=\"40\" width=\"10\" height=\"10\" rx=\"2\" fill=\"#7B6BB5\"/><rect x=\"56\" y=\"40\" width=\"10\" height=\"10\" rx=\"2\" fill=\"#7B6BB5\"/><rect x=\"76\" y=\"40\" width=\"10\" height=\"10\" rx=\"2\" fill=\"#7B6BB5\"/></svg></span>把某個視覺元素（顏色、線條、字體、圖示風格）<b>在整個作品中重複使用</b>，建立一致性與品牌感。這就是「統一」的實作方法。</p></details>\n      <details><summary>對齊 Alignment</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"18\" y1=\"12\" x2=\"18\" y2=\"54\" stroke=\"#3D8E8A\" stroke-dasharray=\"3 3\"/><rect x=\"22\" y=\"18\" width=\"40\" height=\"6\" rx=\"3\" fill=\"#7B6BB5\"/><rect x=\"22\" y=\"30\" width=\"60\" height=\"6\" rx=\"3\" fill=\"#7B6BB5\"/><rect x=\"22\" y=\"42\" width=\"30\" height=\"6\" rx=\"3\" fill=\"#7B6BB5\"/></svg></span>每個元素都要和<b>另一個元素有視覺上的連線</b>，不要隨便亂擺。<b>齊左或齊右通常比置中更俐落</b>；置中適合正式、對稱的場合。看起來亂，八成是沒對齊。</p></details>\n      <details><summary>親密性 Proximity</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"18\" y=\"14\" width=\"40\" height=\"5\" rx=\"2\" fill=\"#7B6BB5\"/><rect x=\"18\" y=\"22\" width=\"30\" height=\"5\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".5\"/><rect x=\"18\" y=\"42\" width=\"40\" height=\"5\" rx=\"2\" fill=\"#7B6BB5\"/><rect x=\"18\" y=\"50\" width=\"30\" height=\"5\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".5\"/></svg></span><b>相關的東西放一起，不相關的分開</b>。靠得近的自動被視為一組。標題要貼近它所屬的內容，而不是漂浮在中間。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>文字與圖像的結合 <span class=\"tag ok\">加字不破圖</span></h3>\n      <ul class=\"tips\">\n        <li><b>把字放進「安靜區」</b>放在留白、單色或模糊的區域，不要壓在細節最複雜的地方。</li>\n        <li><b>看不清就墊底</b>加半透明色塊、暗角、漸層，或在文字下加<b>微弱陰影</b>提升可讀性。</li>\n        <li><b>文字也是構圖元素</b>它有視覺重量，能用來<b>平衡畫面</b>——一側人物重，另一側就放文字。</li>\n        <li><b>對齊人物或畫面軸線</b>文字邊緣對齊人物、地平線或建築線條，畫面會瞬間變整齊。</li>\n        <li><b>顏色從畫面裡取</b>文字顏色<b>吸取畫面中已有的顏色</b>（例如裙子的紫），整體立刻和諧。</li>\n        <li><b>寧可少字</b>一句短標題勝過一整段。字越少，畫面越有力。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>視覺動線 <span class=\"tag hot\">眼睛怎麼走</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">好的版面不是「排得整齊」，而是<b>控制觀者的視線順序</b>。</p>\n      <details><summary>Z 型動線</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M16 18 L94 18 L16 50 L94 50\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"2.4\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></svg></span>視線走「左上 → 右上 → 左下 → 右下」的 Z 字。<b>適合資訊少、圖像為主的版面</b>（海報、廣告、封面）。<br>應用：最重要的放<b>左上</b>（起點），行動呼籲或簽名放<b>右下</b>（終點）。</p></details>\n      <details><summary>F 型動線</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M18 16 L92 16 M18 16 L18 54 M18 34 L74 34\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"2.4\" stroke-linecap=\"round\"/></svg></span>視線在<b>文字多</b>的版面上呈 F 型：先橫掃頂部，再橫掃中段，然後沿左側垂直下滑。<br>應用：這是網頁與長文的真實閱讀行為——把重點放在<b>每段開頭與左側</b>，右下角幾乎不會被看到。</p></details>\n      <details><summary>古騰堡圖表</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"55\" y1=\"8\" x2=\"55\" y2=\"58\" stroke=\"#DDD6E8\"/><line x1=\"8\" y1=\"33\" x2=\"102\" y2=\"33\" stroke=\"#DDD6E8\"/><circle cx=\"24\" cy=\"20\" r=\"4\" fill=\"#3D8E8A\"/><circle cx=\"86\" cy=\"46\" r=\"4\" fill=\"#B8892E\"/><path d=\"M28 22 L82 44\" stroke=\"#8A5FC0\" stroke-width=\"1.6\" stroke-dasharray=\"3 3\"/></svg></span>把版面分四區：<b>主要視覺區（左上）→ 強休息區（右上）→ 弱休息區（左下）→ 終點區（右下）</b>。視線自然由左上流向右下。<br>應用：重要資訊絕不要放<b>左下</b>（最容易被忽略的死角）。</p></details>\n      <details><summary>視覺層級</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"16\" y=\"14\" width=\"60\" height=\"12\" rx=\"3\" fill=\"#2A2138\"/><rect x=\"16\" y=\"30\" width=\"44\" height=\"7\" rx=\"3\" fill=\"#8A5FC0\"/><rect x=\"16\" y=\"42\" width=\"70\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".5\"/></svg></span>透過<b>大小、粗細、顏色、位置、留白</b>建立「先看什麼、再看什麼」的順序。<br>檢查法：<b>瞇眼看</b>——最先跳出來的東西，就是實際的第一層級。如果跳出來的不是你想要的重點，就要調整。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>網格與版面構成 <span class=\"tag ok\">秩序的骨架</span></h3>\n      <ul class=\"tips\">\n        <li><b>網格系統 Grid</b>把版面切成等分的欄與列，所有元素<b>對齊到網格線</b>。這是專業排版與雜亂的分水嶺——即使自由排版，也要有隱形的基準線。</li>\n        <li><b>邊界 Margin</b>四周留出足夠且<b>一致</b>的邊界。新手最常見錯誤就是貼邊；適當的邊界會讓內容看起來更貴。</li>\n        <li><b>群組化</b>用<b>接近性</b>把相關資訊聚成塊，塊與塊之間拉開距離。版面的可讀性來自「塊」，不是來自「行」。</li>\n        <li><b>對齊一以貫之</b>整份作品盡量只用<b>一種主要對齊方式</b>（多半是齊左）。齊左＋置中混用是雜亂的主因。</li>\n        <li><b>黃金比例／三分</b>版面分割也適用：把主體或分界線放在 1/3 或黃金分割處，比對半分更有張力。</li>\n        <li><b>重複建立系統</b>同樣的間距、同樣的圓角、同樣的標題樣式重複出現——這就是「設計感」的來源。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>文字排版 <span class=\"tag hot\">讓文字看起來本來就屬於那裡</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\">文字不只是用來讀的，更是用來看的。字體選擇、大小對比、疏密排列，本身就是視覺圖形。上方分析只量得到文字區塊的<b>位置、大小與對比</b>——字體、字距、行長需要 OCR 才判讀得了，所以那部分不做臆測。</p>\n    </div>\n    <div class=\"card\">\n      <h3>一、字體基礎 <span class=\"tag gold\">認識文字的骨架</span></h3>\n      <details><summary>1. 襯線體 vs 無襯線體</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"26\" y=\"44\" font-size=\"34\" font-family=\"Georgia,serif\" fill=\"#8A5FC0\">Aa</text><text x=\"66\" y=\"44\" font-size=\"34\" font-family=\"Helvetica,Arial,sans-serif\" fill=\"#7B6BB5\">Aa</text></svg></span><i><b>重點</b>兩大陣營。</i><i><b>說明</b><b>襯線體 Serif</b>筆畫末端有裝飾性小尾巴，粗細對比明顯；古典、優雅、權威、可信賴。Times New Roman、Garamond、Georgia、思源宋體。<br><b>無襯線體 Sans</b>筆畫均勻、幾何感強；現代、簡潔、理性、易讀。Helvetica、Arial、Futura、思源黑體。</i><i><b>實務</b>攝影：婚紗與復古寫真用襯線，街拍與極簡用無襯線。設計：書籍報紙內文與奢侈品用襯線，網頁 UI、簡報、路標用無襯線。</i></p></details>\n      <details><summary>2. 字體的性格</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"10\" y=\"30\" font-size=\"15\" font-family=\"Georgia,serif\" fill=\"#8A5FC0\">Garamond</text><text x=\"10\" y=\"52\" font-size=\"15\" font-family=\"Helvetica,Arial\" fill=\"#7B6BB5\">Futura</text></svg></span><i><b>重點</b>每種字體都有自己的聲音與年代感。</i><i><b>說明</b><b>古典人文</b>文藝復興襯線（Garamond），筆畫有書法般的人味。<b>權威莊重</b>現代襯線（Didot、Bodoni），粗細對比極端，Vogue 的標誌就出自這一路。<b>中性萬能</b>新無襯線（Helvetica），沒有多餘個性，放進任何情境都不突兀。<b>幾何未來</b>Futura，字母 O 接近正圓，阿波羅 11 號登月紀念牌用的就是它。</i><i><b>實務</b>手寫字體與書法體情感濃烈，但切忌大篇幅使用，會嚴重拖垮閱讀效率。</i></p></details>\n      <details><summary>3. 字重與字寬</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"10\" y=\"26\" font-size=\"13\" font-weight=\"300\" fill=\"#7B6BB5\">Light</text><text x=\"10\" y=\"42\" font-size=\"13\" font-weight=\"600\" fill=\"#7B6BB5\">Medium</text><text x=\"10\" y=\"58\" font-size=\"13\" font-weight=\"900\" fill=\"#8A5FC0\">Black</text></svg></span><i><b>重點</b>同一套字體家族內就能建立層級，不必引入第二種字體。</i><i><b>說明</b><b>字重</b>Light / Regular / Medium / Bold / Black。標題用 Bold 或 Black，內文 Regular，註釋 Light。<b>字寬</b>Condensed 適合狹長空間的標題，Extended 適合需要氣勢的大標。</i><i><b>實務</b>只用一套字體、靠字重拉開層級，是最不容易出錯的做法。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>二、段落排印 <span class=\"tag ok\">讓文字好讀的法則</span></h3>\n      <details><summary>4. 字距 Tracking</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#8A5FC0\"><rect x=\"12\" y=\"26\" width=\"7\" height=\"16\"/><rect x=\"27\" y=\"26\" width=\"7\" height=\"16\"/><rect x=\"42\" y=\"26\" width=\"7\" height=\"16\"/></g><g fill=\"#7B6BB5\" opacity=\".5\"><rect x=\"64\" y=\"26\" width=\"7\" height=\"16\"/><rect x=\"74\" y=\"26\" width=\"7\" height=\"16\"/><rect x=\"84\" y=\"26\" width=\"7\" height=\"16\"/></g></svg></span><i><b>重點</b>字元之間的整體距離。</i><i><b>說明</b>大標題常拉大 tracking 營造高級呼吸感；正文保持預設或略緊以利閱讀。英文全大寫必須拉開字距，否則字母會黏在一起。</i><i><b>實務</b><span style=\"color:var(--rose)\">※ 補充：tracking（整體字距）和 kerning（特定字母對的微調，如 A 和 V）是兩件事，最常被混用。tracking 調一整段，kerning 只修個別配對。</span></i></p></details>\n      <details><summary>5. 行距 Leading</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#8A5FC0\" stroke-width=\"2.4\"><line x1=\"14\" y1=\"16\" x2=\"50\" y2=\"16\"/><line x1=\"14\" y1=\"26\" x2=\"46\" y2=\"26\"/><line x1=\"14\" y1=\"36\" x2=\"50\" y2=\"36\"/></g><g stroke=\"#7B6BB5\" stroke-width=\"2.4\" opacity=\".6\"><line x1=\"62\" y1=\"14\" x2=\"98\" y2=\"14\"/><line x1=\"62\" y1=\"30\" x2=\"94\" y2=\"30\"/><line x1=\"62\" y1=\"46\" x2=\"98\" y2=\"46\"/></g></svg></span><i><b>重點</b>行與行之間的垂直距離。</i><i><b>說明</b>太緊，行會互相打架；太鬆，段落會解體。行距與行長綁定——行越長需要的行距越大，否則換行時視線容易跳回同一行。</i><i><b>實務</b>經驗值：內文行距約字體大小的 1.4–1.6 倍；大標題可縮到 1.0–1.2 倍，讓多行標題形成緊密的文字塊。</i></p></details>\n      <details><summary>6. 行長</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"2.6\"><line x1=\"10\" y1=\"20\" x2=\"100\" y2=\"20\"/><line x1=\"10\" y1=\"32\" x2=\"100\" y2=\"32\"/><line x1=\"10\" y1=\"44\" x2=\"72\" y2=\"44\"/></g></svg></span><i><b>重點</b>每行的字數。</i><i><b>說明</b>理想範圍：中文內文每行 25–35 字，英文 45–75 個字元。太短視線頻繁換行造成疲勞，太長則讀完一行找不到下一行開頭。</i><i><b>實務</b>攝影浮水印可故意違反此規則，一行只放 3–5 字，把文字當成點綴性的圖形元素。</i></p></details>\n      <details><summary>7. 層級 Hierarchy</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"12\" y=\"12\" width=\"60\" height=\"9\" rx=\"2\" fill=\"#8A5FC0\"/><rect x=\"12\" y=\"28\" width=\"44\" height=\"6\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".7\"/><g fill=\"#7B6BB5\" opacity=\".45\"><rect x=\"12\" y=\"40\" width=\"82\" height=\"3.5\" rx=\"1.5\"/><rect x=\"12\" y=\"48\" width=\"82\" height=\"3.5\" rx=\"1.5\"/></g></svg></span><i><b>重點</b>一張作品中，文字至少要有三個層級才有秩序。</i><i><b>說明</b><b>主標題</b>最大最粗，負責 3 秒內傳達核心訊息。<b>副標題</b>補充說明，引導往下。<b>內文</b>最小，以閱讀舒適為最高原則。</i><i><b>實務</b>層級靠對比建立——大小、粗細、顏色。兩個層級差別不夠明顯時，會產生「差一點點就一樣」的不安感。</i></p></details>\n      <details><summary>8. 對齊方式</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#8A5FC0\" opacity=\".55\"><rect x=\"10\" y=\"14\" width=\"40\" height=\"4\" rx=\"2\"/><rect x=\"10\" y=\"24\" width=\"32\" height=\"4\" rx=\"2\"/><rect x=\"10\" y=\"34\" width=\"38\" height=\"4\" rx=\"2\"/></g><g fill=\"#7B6BB5\" opacity=\".55\"><rect x=\"62\" y=\"14\" width=\"38\" height=\"4\" rx=\"2\"/><rect x=\"68\" y=\"24\" width=\"32\" height=\"4\" rx=\"2\"/><rect x=\"64\" y=\"34\" width=\"36\" height=\"4\" rx=\"2\"/></g></svg></span><i><b>重點</b>四種各有性格。</i><i><b>說明</b><b>左對齊</b>最常見，符合閱讀習慣。<b>右對齊</b>刻意，常用於角落浮水印與圖說。<b>置中</b>正式古典，婚紗相本、詩集、邀請函最愛，但多行長度差異大時會凌亂。<b>齊行</b>左右都齊，形成整齊的文字塊。</i><i><b>實務</b>齊行若欄寬太窄，字間會出現連成一串的縱向空白，印刷術語叫「河流」。</i></p></details>\n      <details><summary>9. 避頭尾與孤兒寡婦</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#7B6BB5\" opacity=\".5\"><rect x=\"12\" y=\"14\" width=\"84\" height=\"4\" rx=\"2\"/><rect x=\"12\" y=\"24\" width=\"84\" height=\"4\" rx=\"2\"/><rect x=\"12\" y=\"34\" width=\"84\" height=\"4\" rx=\"2\"/></g><g fill=\"#fff\"><rect x=\"40\" y=\"14\" width=\"5\" height=\"28\" opacity=\".9\"/></g></svg></span><i><b>重點</b>收尾的細節。</i><i><b>說明</b><b>避頭尾</b>中文忌諱行首出現逗號、句號，也忌諱行尾出現左括號、左引號。<b>孤兒</b>段落第一行單獨留在欄或頁的底部。<b>寡婦</b>段落最後一行單獨落到下一欄或下一頁的頂端。</i><i><b>實務</b><span style=\"color:var(--rose)\">※ 這組定義常被寫反，這裡的版本是對的。記法：孤兒沒有過去（被留在下方），寡婦沒有未來（獨自在上方）。</span></i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>三、文字作為圖形 <span class=\"tag warn\">創意排版法則</span></h3>\n      <details><summary>10. 文字跳出邊框</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"30\" y=\"18\" width=\"90\" height=\"30\" rx=\"4\" fill=\"#8A5FC0\"/><text x=\"42\" y=\"40\" font-size=\"19\" font-weight=\"800\" fill=\"#fff\">TYPE</text></svg></span><i><b>重點</b>故意讓文字衝出畫面邊界，或讓標題字母的一半被裁切。</i><i><b>說明</b>在海報或封面中能瞬間打破沉悶，帶來前進感與衝擊力。</i><i><b>實務</b>前提是被裁掉的部分仍可辨識。裁到看不懂就只是失誤。</i></p></details>\n      <details><summary>11. 繞圖排版</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"40\" cy=\"34\" r=\"22\" fill=\"#8A5FC0\"/><g fill=\"#7B6BB5\" opacity=\".6\"><rect x=\"66\" y=\"14\" width=\"34\" height=\"3.5\" rx=\"1.5\"/><rect x=\"70\" y=\"24\" width=\"30\" height=\"3.5\" rx=\"1.5\"/><rect x=\"72\" y=\"34\" width=\"28\" height=\"3.5\" rx=\"1.5\"/><rect x=\"68\" y=\"44\" width=\"32\" height=\"3.5\" rx=\"1.5\"/></g></svg></span><i><b>重點</b>讓內文沿主體輪廓流動，而非硬對齊矩形圖框。</i><i><b>說明</b>核心在文字與圖像之間的安全距離：太近會互相侵犯，太遠則關係斷裂。</i><i><b>實務</b>通常保留 3–5mm 的緩衝空間。</i></p></details>\n      <details><summary>12. 文字遮罩</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><defs><clipPath id=\"tclip\"><text x=\"8\" y=\"46\" font-size=\"34\" font-weight=\"900\">MASK</text></clipPath></defs><rect x=\"0\" y=\"0\" width=\"110\" height=\"66\" fill=\"#8A5FC0\" clip-path=\"url(#tclip)\"/></svg></span><i><b>重點</b>把圖片填入粗體大字，或反過來把文字鏤空透出底下的影像。</i><i><b>說明</b>文字既是可讀的標題，本身又是承載影像的容器。</i><i><b>實務</b>作品集封面與海報的常用手法。字體要夠粗，否則填進去的影像看不出來。</i></p></details>\n      <details><summary>13. 破壞規則的編排</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"12\" y=\"40\" font-size=\"24\" font-weight=\"800\" fill=\"#8A5FC0\" opacity=\".55\">OVER</text><text x=\"30\" y=\"48\" font-size=\"24\" font-weight=\"800\" fill=\"#7B6BB5\" opacity=\".55\">LAP</text></svg></span><i><b>重點</b>三種手法。</i><i><b>說明</b><b>文字重疊</b>兩層交錯疊加，其中一層半透明或鏤空，製造空間層次。<b>透視文字</b>貼合建築立面、地板或牆面，跟隨場景的消失線走。<b>解構文字</b>拆散成個別字母散落各處。</i><i><b>實務</b>解構文字讓觀者自行拼湊，參與感產生了但可讀性犧牲了，適合藝術表達而非資訊傳達。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>四、實戰 <span class=\"tag hot\">攝影與設計中的落地做法</span></h3>\n      <details><summary>14. 浮水印的藝術</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"6\" y=\"6\" width=\"98\" height=\"54\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".12\"/><text x=\"62\" y=\"54\" font-size=\"8\" fill=\"#7B6BB5\" opacity=\".8\">© studio</text></svg></span><i><b>重點</b>不只防盜，更是個人品牌的一環。</i><i><b>說明</b><b>位置</b>四角最常見，右下角是最自然的視覺終點。<b>字體</b>寧細勿粗、寧小勿大。<b>透明度</b>60–80%，讓它融入畫面而非貼在上面。</i><i><b>實務</b>風格要匹配：復古照片配襯線體，極簡攝影配無襯線體——字體的年代感要和影像的調性一致。</i></p></details>\n      <details><summary>15. 排版網格系統</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-dasharray=\"2 2\" opacity=\".75\"><line x1=\"26\" y1=\"4\" x2=\"26\" y2=\"62\"/><line x1=\"55\" y1=\"4\" x2=\"55\" y2=\"62\"/><line x1=\"84\" y1=\"4\" x2=\"84\" y2=\"62\"/></g><rect x=\"30\" y=\"14\" width=\"50\" height=\"20\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".55\"/></svg></span><i><b>重點</b>文字不是憑感覺放的，而是建立在一套隱形網格上。</i><i><b>說明</b><b>單欄</b>適合手機。<b>雙欄</b>雜誌常用，可圖文穿插。<b>三欄</b>海報與資訊密集版面，彈性最大。<b>模組化網格</b>切成等大方塊，適合畫冊與作品集。</i><i><b>實務</b>所有文字區塊都應該對齊這套網格，這是排版「看起來專業」的底層祕密。</i></p></details>\n      <details><summary>16. 色彩與對比</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#2A2138\"/><rect x=\"14\" y=\"26\" width=\"82\" height=\"16\" rx=\"3\" fill=\"#000\" opacity=\".45\"/><text x=\"24\" y=\"38\" font-size=\"11\" fill=\"#fff\">readable</text></svg></span><i><b>重點</b>文字壓在影像上的可讀性。</i><i><b>說明</b><b>黑白照片</b>純白字放暗部、純黑字放亮部，或用中灰字走極簡。<b>彩色照片</b>吸取畫面主色，把文字設為其互補色（藍天配橙字），對比最強。</i><i><b>實務</b>安全牌：文字底下加一條半透明黑條或局部模糊（文字背景板），任何複雜畫面下都能保住可讀性。上方分析的「文字對比」欄用 WCAG 門檻檢查這件事。</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>總結 <span class=\"tag gold\">隱形的藝術</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\">文字排版是一門隱形藝術——做得好，讀者渾然不覺地沉浸於內容；做得差，每一個字都在尖叫著業餘。掌握了規則之後請記住一句話：排版的最高境界，是讓文字看起來本來就屬於那裡。</p>\n    </div>\n", "ae-prac": "\n    <div class=\"card\">\n      <h3>藝術照實戰清單 <span class=\"tag hot\">拍之前跑一遍</span></h3>\n      <ul class=\"tips\">\n        <li><b>① 定主角</b>這張要讓人看見什麼？（整套？裙擺？表情？飾品？）</li>\n        <li><b>② 選構圖</b>不確定就三分法；莊重用中央、動感用對角線、雙人用三角。</li>\n        <li><b>③ 定光向</b>要細節→順光；要立體→側光；要氛圍→逆光；要古典→林布蘭光。</li>\n        <li><b>④ 收色</b>套 60-30-10；顏色太雜就降彩度或加無彩色。</li>\n        <li><b>⑤ 做對比</b>深衣服配淺背景（反之亦然），確保主角不會融進背景。</li>\n        <li><b>⑥ 加層次</b>前景放一點東西（花瓣、簾幕、光斑）製造景深。</li>\n        <li><b>⑦ 清邊緣</b>檢查四邊有沒有切到一半的雜物、有沒有切在關節上。</li>\n        <li><b>⑧ 做減法</b>最後拿掉一到兩個不必要的元素——通常會更好看。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>常見失誤與解法 <span class=\"tag warn\">對症下藥</span></h3>\n      <table>\n        <thead><tr><th>症狀</th><th>可能原因</th><th>解法</th></tr></thead>\n        <tbody>\n          <tr><td>畫面很平、沒立體感</td><td>順光、缺明暗</td><td>改側光或逆光，加強陰影</td></tr>\n          <tr><td>看不出主角是誰</td><td>缺強調與引導線</td><td>降低配角彩度、加引導線與留白</td></tr>\n          <tr><td>很雜很亂</td><td>元素太多、缺統一</td><td>統一色系、做減法、留白</td></tr>\n          <tr><td>很單調無聊</td><td>缺變化與對比</td><td>加一個強調色或亮點細節</td></tr>\n          <tr><td>人物融進背景</td><td>明度／色相太接近</td><td>換背景明暗，或加輪廓光</td></tr>\n          <tr><td>配色很俗</td><td>互補色等量、彩度全開</td><td>套 60-30-10、降彩度</td></tr>\n          <tr><td>構圖歪、不穩</td><td>視覺重量偏一邊</td><td>另一側加小亮點平衡</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"card\">\n      <h3>哪一項弱，就找哪種老師 <span class=\"tag hot\">學習路線</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">報告裡每一段對應的是一門不同的手藝。分數低的那幾段，就是該補的方向。<b>不必全部學</b>——挑最弱的一兩項就好。</p>\n      <table>\n        <thead><tr><th>報告哪一段弱</th><th>要練的能力</th><th>找哪種老師</th></tr></thead>\n        <tbody>\n          <tr><td>構圖分析<br><span class=\"cond\">（構圖型態、三分法、引導線）</span></td><td>構圖能力</td><td>攝影、<b>電影分鏡</b>、插畫</td></tr>\n          <tr><td>色彩<br><span class=\"cond\">（配色法則、風格色系、色彩評語）</span></td><td>色彩搭配</td><td><b>色彩學</b>、平面設計、插畫</td></tr>\n          <tr><td>美的形式原理<br><span class=\"cond\">（單純、統一與多樣偏低時）</span></td><td>元素取捨</td><td>平面設計、<b>廣告設計</b></td></tr>\n          <tr><td>視覺焦點集中度、主體重心</td><td>視覺重心安排</td><td><b>版面設計 Layout</b>、UI 設計</td></tr>\n          <tr><td>光影、留白比例</td><td>光影與留白</td><td>攝影、繪畫、<b>電影攝影</b></td></tr>\n          <tr><td>文字層<br><span class=\"cond\">（對比、邊距）</span></td><td>文字排版</td><td><b>字體排印 Typography</b>、平面設計</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"card\">\n      <h3>如果只能選兩三門 <span class=\"tag gold\">依你的作品類型排序</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">你做的是<b>合成型的平面作品</b>（封面、展示圖、有文字的版面），不是單張攝影。這個差別會改變優先順序：</p>\n      <ul class=\"tips\">\n        <li><b>① 版面設計（Layout）</b>合成作品的成敗大半在這裡——元素放哪、留多少、誰壓過誰。而且它是最有系統、最快看到成效的一門。</li>\n        <li><b>② 色彩學</b>第二大槓桿，而且可以「用學的」。色輪的配色法則是規則，不是天分，學完就能用。</li>\n        <li><b>③ 字體排印</b>只要作品裡有文字就繞不開。字級對比、行距、對齊——做不好的話整張作品的完成度會被一眼看穿。</li>\n        <li><b>④ 電影分鏡／攝影構圖</b>學視線怎麼被帶著走。放在後面不是因為不重要，而是前三項沒打底時，構圖再好也撐不起來。</li>\n        <li><b>⑤ 光影</b>最花時間、最難速成的一門，但也是讓作品「有份量」的關鍵。</li>\n      </ul>\n      <p class=\"cond\" style=\"margin:10px 0 0\">跟一般「先學構圖」的建議不同，是因為<b>構圖法則多半是為單一鏡頭設計的</b>；你的作品是多個素材疊起來再加文字，決定成敗的是版面與層級，不是取景。</p>\n    </div>\n", "sec-lore": "\n  <p class=\"fine\" style=\"margin:0 0 10px\">品牌與命名的完整科普。<b>逐池條目點擊展開</b>，同時看到「取名由來」與「英文版截圖實證」。標註「推測」者為社群解讀。</p>\n  <div class=\"seg\" id=\"loreSeg\" style=\"margin-bottom:14px\">\n    <button class=\"on\" data-v=\"lore-deux\">Deux</button>\n    <button data-v=\"lore-melem\">melem</button>\n    <button data-v=\"lore-bye\">By(e)</button>\n    <button data-v=\"lore-common\">共通</button>\n  </div>\n  <div class=\"lort show\" id=\"lore-deux\">\n    <div class=\"card\">\n      <h3>deux <span class=\"tag gold\">人偶系列</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\"><b>一句話：</b>名字＝法文「二」，一切成雙——雙子主視覺、男女成對品項、對偶染色（未來／過去、太陽／月），連品名都在對「你」說話。</p>\n      <ul class=\"tips\">\n        <li><b>原色多是法文單字</b>Chagrin 悲傷、Larme 眼淚、Âme 靈魂、Néant 虛無、Soleil 太陽、Vérité 真理、Loin 遠方、Soirée 晚會、Rêve 夢、Perle 珍珠。</li>\n        <li><b>愛用神話與經典</b>Psyche＝希臘文「靈魂」（象徵蝴蝶）、Giselle＝芭蕾幽靈舞姬、Marguerite＝雛菊、Minette＝小貓。</li>\n        <li><b>和風池藏古語</b>玉響＝一瞬、うたかた＝泡沫、徒櫻＝「明日不可恃」的落櫻、川平子／加波比良古＝蝴蝶的上古語；白妙、黑橡、退紅、月白皆為傳統色名。</li>\n        <li><b>C.D／F.D 家族暗線</b>#10 Charlotte D. 的墮天使之淚＋家族之書 → #11 F.D-Glass Key → #14 C.D-Papillon → #15 F.D-Papillon（推測為同一家族縮寫）。</li>\n        <li><b>為什麼從 #4 開始</b>國際服跟著日服時間線走，#1～#3 是接軌前就結束的池，自 #4（2023/02）起同步。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>角色人名的意義 <span class=\"tag ok\">語源</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">各池眼睛／髮型多以真實人名命名，名字本身就藏著含義（僅收錄確定語源；Saintière 等遊戲自創名不列）。</p>\n      <p class=\"cond\" style=\"margin:10px 0 4px\"><b>眼睛角色</b></p>\n      <ul class=\"tips\">\n        <li><b>法蘭欣 Francine</b>「自由之人」（Francis 的陰性）。</li>\n        <li><b>安妮 Anne</b>「恩典」（希伯來 Hannah）；<b>安東尼 Antoine</b>＝Anthony 的法文形。</li>\n        <li><b>路易絲／路易 Louise／Louis</b>「著名的戰士」（日耳曼 Ludwig）。</li>\n        <li><b>卡蜜兒 Camille</b>「祭儀的侍者」（拉丁）；<b>塞繆爾 Samuel</b>「神已聽見」（希伯來）。</li>\n        <li><b>克拉麗絲 Claris</b>「明亮、清澈」（拉丁 clarus）；<b>克萊門特 Clement</b>「仁慈、溫和」（拉丁 clemens）。</li>\n        <li><b>瑪格麗特 Marguerite</b>「珍珠／雛菊」（希臘 margarites）；<b>馬克西米利安 Maximilian</b>「最偉大的」（拉丁 maximus）。</li>\n        <li><b>伊內斯 Inez</b>「純潔、神聖」（Agnes 西語形）；<b>勞爾 Raul</b>「狼的智慧」（Ralph 西語形）。</li>\n        <li><b>吉賽爾 Giselle</b>「誓約」（日耳曼 gisil）；<b>普緒克 Psyche</b>「靈魂、氣息」（希臘）。</li>\n      </ul>\n      <p class=\"cond\" style=\"margin:14px 0 4px\"><b>髮型角色</b></p>\n      <ul class=\"tips\">\n        <li><b>西爾維雅／西爾萬 Sylvia／Sylvain</b>「森林的」（拉丁 silva）。</li>\n        <li><b>寬大 Bénédicte</b>「蒙福的」（拉丁 benedictus）；<b>費利克斯 Felix</b>「幸福、幸運」（拉丁）。</li>\n        <li><b>吉爾 Gilles</b>＝Giles 的法文（希臘 aigidion 幼羊／盾）；<b>亨利 Henri</b>「家的統治者」（日耳曼）。</li>\n        <li><b>蘇菲 Sophie</b>「智慧」（希臘）；<b>盧卡／露西／盧西安 Luca／Lucie／Lucian</b>「光」（拉丁 lux）。</li>\n        <li><b>艾兒莎 Elsa</b>＝Elisabeth 暱稱「向神起誓」；<b>路德維克 Ludovic</b>＝Louis 變體「著名戰士」。</li>\n        <li><b>阿爾瑪 Alma</b>「靈魂」（拉丁／西語）；<b>埃斯特 Ester</b>「星」（波斯 Esther）。</li>\n        <li><b>伊維特 Yvette</b>「紫杉」（法文，Yves 陰性）；<b>傑斯維 Gervais</b>「持矛的侍從」（日耳曼）。</li>\n      </ul>\n      <p class=\"cond\" style=\"margin:14px 0 4px\"><b>更多語源人名</b></p>\n      <ul class=\"tips\">\n        <li><b>雷維爾／瑞維爾 Reveur</b>法文「作夢者」（rêveur）——#6、#8、By(e) #1 都出現。</li>\n        <li><b>布莉埃 Briller</b>法文「閃耀、發光」（#11）。</li>\n        <li><b>蕾妮 Renée</b>「重生」（拉丁 renatus 的法文陰性，#10）。</li>\n        <li><b>瑪莉 Marie</b>Mary 的法文形（希伯來 Miryam，#14）；<b>露恩・卡曼 Lune Carmin</b>＝月（Lune）＋胭脂紅（Carmin）。</li>\n        <li><b>艾米莉亞 Emilia</b>「競逐、勤勉」（羅馬氏族 Aemilia，By(e) #1）。</li>\n        <li><b>露露 Lulu</b>Louise／Lucille 的暱稱形（#4）；<b>西蒙 Simon</b>「他已聽見」（希伯來 Shimon，#8）。</li>\n        <li><b>希里尤 Cyril</b>「主君、有威者」（希臘 Kyrillos，By(e) #3 Pellucid Cyril）；<b>伊甸 Eden</b>「喜樂、樂園」（希伯來，By(e) #3）。</li>\n        <li><b>Cherie</b>法文「親愛的」（Reveur: Cherie）；<b>Lumiadus／Lumineux</b>由 Lumière（光）衍生的造字。</li>\n      </ul>\n      <p class=\"fine\">同一角色常有男女／深淺兩版（如 Sylvia／Sylvain、Hiina／Hihina），名字也隨之成對。</p>\n    </div>\n    <div class=\"card\">\n      <h3>deux・逐池詳解 <span class=\"tag ok\">取名＋英文實證</span></h3>\n      <details><summary>#4 星月冰藍 · 星光化為月虹</summary>\n        <p><span class=\"lb\">取名</span>原色 <b>Ciel</b>（天空），主裙「花之鑰・天空」；星彩的（原）→月光彩虹的（染），半月帽、朦朧月，一路是月相。</p>\n        <p><span class=\"lb en\">英文</span>星彩的＝<b>Starlight</b>（女 Francine／男 Saintière）、月光彩虹的＝of Lunar Rainbow；花之鑰＝<b>Fleur Serie</b>；月系配件全法文（Lune Bonnet／Beret、Lunevoirée、Une Rose Eye Patch）。</p></details>\n      <details><summary>#5 ex 櫻・宵 · 別指望明天的落櫻</summary>\n        <p><span class=\"lb\">取名</span>原色 <b>宵／黑夜</b>；徒櫻取自「明日ありと思ふ心の仇桜」；八重戀衣→泡沫戀衣（うたかた）；「薄花櫻的你／花朧的你」對「你」說話。</p>\n        <p><span class=\"lb en\">英文</span>官方錯字 <b>Love Pedal</b>（Petal 花瓣→Pedal 踏板）；原色眼男女＝Night Sakura <b>Hinawa</b>（女）／<b>Kyoya</b>（男・宵）。</p></details>\n      <details><summary>#6 紅寶石 · 致命之女與月相</summary>\n        <p><span class=\"lb\">取名</span>原色 <b>Rouge</b>（胭脂），主裙 Femme Fatale；盈虛＝月的盈虧；暗黑的卡蜜兒→閃光／沉默。</p>\n        <p><span class=\"lb en\">英文</span>主裙 <b>Femme Fatale</b>、男版 <b>Omphale</b>（奴役海克力斯的女王）成對；盈虛＝<b>Lunar Flux</b>；卡蜜兒＝Flash of Light／of Silence；薔薇的意圖＝Rose Thoughts: Night→<b>White Day／New Year&#39;s Eve／Evening</b>（節日梗）；品牌卡 Le Rubis De Deux。</p></details>\n      <details><summary>#7 白薔薇 · 清廉之光走遠了</summary>\n        <p><span class=\"lb\">取名</span>原色 <b>Perle／Ciel／Claire</b>；清廉的光 Pure Lumière→悠遠的光；「寬大」＝法文名 Bénédicte（蒙福）意譯。</p>\n        <p><span class=\"lb en\">英文</span>整池原封法文（Pure Lumière、Souvenir Eternel、Cache Oeil de Dentelles 蕾絲眼罩）；悠遠的光＝<b>Distant Lumière</b>；同池兩種語序（Eternal Souvenir／Souvenir Eternel）；靜謐之眼女 Anne Tranquille／男 Tranquility Antoine；拼字彩蛋 <b>Laprèmidi</b>（l&#39;après-midi 連寫，男版掉重音）。</p></details>\n      <details><summary>#8 藍薔薇 · 小貓與蔚藍海岸</summary>\n        <p><span class=\"lb\">取名</span><b>Minette</b>＝小貓咪——所以有黑貓耳尾、獵戶座；R 眼 Riviera＋d&#39;Azur＝蔚藍海岸；沙格蘭＝Chagrin 悲傷。</p>\n        <p><span class=\"lb en\">英文</span>d&#39;Azur 寫成 <b>Dajour</b>；Silent Bloom／Sleeping／Quiet Bloom；蔚藍的迴旋曲＝Azure Rondo→Navy Rondo；髮型 Yvette／Yverre 成對。</p></details>\n      <details><summary>#9 藍白奶油 · 雛菊之夢化成泡</summary>\n        <p><span class=\"lb\">取名</span>原色 <b>Rêve</b>（夢），染色第一格「睡眠」；Marguerite＝雛菊（人名同時是花名）；追憶的→寂靜的／泡沫的。</p>\n        <p><span class=\"lb en\">英文</span>追憶＝Recollection、寂靜＝Silence、泡沫＝Bubbles；拼字彩蛋 <b>Nobel</b>（應 Noble）、<b>Pesch</b>（應 Pêche）。</p></details>\n      <details><summary>#10 墮天使 · 染色版在演墮落</summary>\n        <p><span class=\"lb\">取名</span>原色 <b>Âme</b>（靈魂）；書・混亂→闔上、天穹光環→虛空光環、墮天使翼→魁儡翼；Alma＝拉丁文靈魂: Vérité 真理。</p>\n        <p><span class=\"lb en\">英文</span>靈魂＝<b>âme</b>；Inez／Raul→<b>Daybreak</b>（夜空→破曉）；Livre: Désarroi→<b>Fermer</b>（闔上）、Skyward→<b>Void Halo</b>、Fallen Angel→<b>Puppet Wings</b>；家族線 Heritage Book＋Fallen Angel Tears。</p></details>\n      <details><summary>#11 晨露 · 朝露＝清晨的眼淚</summary>\n        <p><span class=\"lb\">取名</span>原色 <b>Larme</b>（眼淚）——朝露＝清晨的眼淚，整池題眼；Matin 早晨、Fleurir 綻放、Soleil 太陽；雫石＝水滴之石。</p>\n        <p><span class=\"lb en\">英文</span>Larme（Dearest Morning Mist: Larme）；Matin（Dawn Reflet Matin）；Fleurir→染 <b>Bourgeon</b> 花苞；Soleil→Nature；髮型 Avenir 未來；家族線 <b>F.D-Glass Key</b>。</p></details>\n      <details><summary>#12 ex 月兔 · 朔望之契、兩個世界</summary>\n        <p><span class=\"lb\">取名</span>原色 <b>夜光</b>；朔望之契＝朔（新月）與望（滿月）的契約；黑橡＝橡實染的傳統黑；冥界兔耳 對 常世兔耳；雪洞＝紙罩燭燈。</p>\n        <p><span class=\"lb en\">英文</span>朔望之契＝<b>New Moon Promise</b>；二兔＝Twin Moon Night <b>Uno／Yato</b>（白珠／黑珠）；常世＝<b>Eternal</b> Rabbit Ears: White 對 冥界＝<b>Underworld</b> Rabbit Ears: Black。</p></details>\n      <details><summary>#13 時之哥德 · 被遺忘的虛無</summary>\n        <p><span class=\"lb\">取名</span>原色 <b>Chronos</b>；Néant＝虛無，「廢忘的奈恩」＝被遺忘的虛無；永恆之臂 禁錮→未來／過去；Loin 遠方→古老；藝術「時計草」＝西番蓮（花形似鐘面）。</p>\n        <p><span class=\"lb en\">英文</span>Chronos（Immortal Chronos 卡）；奈恩三檔 Oblivious→<b>Time</b>／Melancholic Néant；永恆之臂＝L&#39;âme Éternelle: Présent→<b>Avenir／Passé</b>；日夜公演＝<b>Matinée／Soirée</b>；Ash→Platinum Gear Pipe；Loin→Vieux。</p></details>\n      <details><summary>#14 蝶與薔薇 · 靈魂即是蝴蝶</summary>\n        <p><span class=\"lb\">取名</span>原色 <b>Rosé</b>；Psyche＝希臘文靈魂（象徵蝴蝶）→沉沒於月夜的普緒克，滿池蝴蝶由此而來；Giselle＝幽靈舞姬「虛空的」；理的／心神的緞帶＝psyche 兩義項；退紅＝傳統淡紅。</p>\n        <p><span class=\"lb en\">英文</span><b>Moonlit Sunken Psyche</b>（Rosé／Blanc／Azure／Noir）；Giselle of the Void→<b>The Heretical</b>（男 Gervais 同構）；<b>Reason／Mind Butterfly Ribbon</b>；Refret／Refretia→The Longing；黑暗＝Ténèbres；家族線 <b>C.D-Papillon: Lueur／Ombre</b>。</p></details>\n      <details><summary>#15 ex 月夜蝶 · 蝴蝶古語的兩種寫法</summary>\n        <p><span class=\"lb\">取名</span>原色 <b>白妙</b>（萬葉集古語「純白」）；月夜的川平子／加波比良古＝<b>かはひらこ</b>（蝴蝶上古語）兩種寫法；玉響＝一瞬；薄香、淡藤、曙、月白、灰櫻、薄冰全是傳統色名。</p>\n        <p><span class=\"lb en\">英文</span>雛人形讀音成對 <b>Hiina</b>（女）／<b>Hihina</b>（男），Solar 版同構；髮型 Chitose／Hinako；主裙 Moon Butterfly <b>Trance</b>: White→Dusk／Silver／White Night；家族線收尾 <b>F.D-Papillon: White</b>（C.D／F.D 四卡到齊）。</p></details>\n      <details><summary>#16 人偶回憶 · 灰白蕾絲裡的兔子與紀念盒</summary>\n        <p><span class=\"lb\">取名</span>原色角色 <b>索拉納 Solène</b>／<b>阿爾特爾 Altel</b>；Trésor＝法文「寶藏」（回憶的寶物）；Clarté（明亮）＋Douce（柔軟甜美）＋Coton（棉）疊字成一件衣名；Souvenir（回憶／紀念品）與 Douces Oreilles（柔軟的耳朵）、Lapin（兔子）、Chouchou（心肝寶貝）、Lapinette（小母兔）串起整池的兔子人偶主題；Voilage（薄紗窗簾）、Blanche（白，陰性形容詞）延續光影意象。</p>\n        <p><span class=\"lb en\">英文</span>R 眼女版 <b>Radiant</b> 對男版 <b>Radian</b>（少一個 t，疑為官方拼字彩蛋，待下次核對）；男版頭飾 <b>Laureate Halo</b>（桂冠光環）呼應第二套髮型 <b>Aurelius</b>（拉丁「金色的」，羅馬式人名）——女線走法文人名 Solène／Éliane，男線在灰白之外摻了一絲羅馬古典感；<b>Silve</b> 首度出現在 Deux（銀 Argent 的縮寫造字，猜測），與同池 R 眼 Radiant/Radian、藝術道具 Sentimental Lapin Chouchou、Lapinette Stand 都是新詞彙，暫無法對到既有的 C.D／F.D 家族線或月相線索。</p></details>\n    </div>\n  </div>\n  <div class=\"lort\" id=\"lore-melem\">\n    <div class=\"card\">\n      <h3>melem <span class=\"tag gold\">鏡像系列</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\"><b>一句話：</b>名字是迴文（m-e-l-e-m 正反讀相同）——名字本身鏡像對稱；標誌是綿羊牽著烏鴉，走一條暗黑寓言線。</p>\n      <ul class=\"tips\">\n        <li><b>暗黑寓言線</b>#1 鏡 → #2 鳥籠與烏鴉 → #3 迷途羊 → #4 白雪公主毒蘋果。</li>\n        <li><b>後綴＝鏡後的變化</b>物品進鏡室就長出後綴，代表它在鏡中變成了什麼；變體是<b>崩壞三階</b>（完整→侵蝕→碎裂），不是顏色。</li>\n        <li><b>「鏡中的你」001→004</b>從 #1 一路編號到 #4——鏡中的你跟著你走過全部四池；手部道具必拆 L／R。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>melem・逐池詳解 <span class=\"tag ok\">取名＋英文實證</span></h3>\n      <details><summary>#1 鏡 · 迷失鏡中的靈魂</summary>\n        <p><span class=\"lb\">取名</span><b>Miloire</b>≈miroir（法文「鏡」）造字（推測）；Psyche＝迷失鏡中的靈魂；相似＝Simulacrum；眼影盒＝Shadowgaze（雙關）。</p>\n        <p><span class=\"lb en\">英文</span>後綴清一色 <b>: Mirror</b>；Simulacrum、Shadowgaze 全對上；更深後綴詞庫 Lingering Dreams／Illusion／Dawn／Opposite／Fragment／<b>Zero</b>；<b>You in the Mirror001</b> 起跳；黑手套 L／R；藝術卡 Pittoresque「behind the mirror」。</p></details>\n      <details><summary>#2 鴉 · 鏡子把物件變成概念</summary>\n        <p><span class=\"lb\">取名</span>烏鴉羽毛→・理性、鏡光輪→・福音、鳥籠少女→・預感／妄想；向深淵招手 L／R、潛伏於碎片 她／他。</p>\n        <p><span class=\"lb en\">英文</span>聖歌之眼 Another Sky&#39;s→Secret／Everdark Anthem；理性＝<b>Logos</b>、福音＝<b>Faith</b>；官方錯字 <b>The Gaurdian</b>；You in the Mirror002；窺探黑暗→<b>窺探深淵</b>；Mirror in the Mirror。</p></details>\n      <details><summary>#3 迷途羊 · 白引導、黑解放</summary>\n        <p><span class=\"lb\">取名</span>白→黑反轉：往白色虛構的「引導」→往黑色虛構的「解放」；日食羊＝白羊被吞蝕；「鏡花的庇護」用鏡花水月典。</p>\n        <p><span class=\"lb en\">英文</span>Innocent Lost Sheep→<b>Black</b> Shadow／Eternity；White Fiction Leader→<b>Black Fiction Release</b>、White／Black Haze・Horns・Wanderer；日食羊＝<b>Eclipse Sheep</b>；連號變 Mirror<b> 003</b>（帶空格）；收尾＝<b>Distorted Mirror, No Return.</b>（含句號）。</p></details>\n      <details><summary>#4 毒蘋果 · 蘋果的墮落三部曲</summary>\n        <p><span class=\"lb\">取名</span>眼睛三段 誘惑→侵蝕→嫉視；黑／銀→赤反轉；提問之房間＝王后問鏡；紅果實的不可逆性＝咬下去就回不去。</p>\n        <p><span class=\"lb en\">英文</span>三部曲＝Poison Apple <b>Allure→Erosion→Jealousy</b>；<b>Dark→Red→Phantasm</b> Mirror Sorcerer、Argent→Crimson Veil；公主裙 Crimson→<b>Fusion</b>；鏡譽鏡＝<b>Mirror, Mirror on the Wall</b>（原句當品名）；紅果實＝Irreversible Red Fruit；You in the Mirror 004 到齊。</p></details>\n    </div>\n  </div>\n  <div class=\"lort\" id=\"lore-bye\">\n    <div class=\"card\">\n      <h3>by(e) <span class=\"tag gold\">香氛花卉</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\"><b>一句話：</b>名字雙關「by ○○」（香水命名慣例）＋括號 e 讀成「bye」（道別）——與三池「終將消逝之美」互扣。</p>\n      <ul class=\"tips\">\n        <li><b>整池像一瓶香水</b>原版統一掛 SCENT FOR YOU（基調香），三線是香調變化；<b>唯一含彩妝部位</b>（唇／腮紅／眉）的品牌。</li>\n        <li><b>副標全是易逝意象</b>秋牡丹「短暫的愛」、雨中紐約的紅花、用皂泡說「永恆」——名字本身就是矛盾修辭。</li>\n        <li><b>香水線會回收升格</b>Noir Eden 從 #1 配角線升為 #3 主線；線名全走香調（Floral Eve、Citrus Mellow、Elegant Aqua、Fruity Fairy…）。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>by(e)・逐池詳解 <span class=\"tag ok\">取名＋英文實證</span></h3>\n      <details><summary>#1 秋牡丹 · 短暫的愛</summary>\n        <p><span class=\"lb\">取名</span>阿芙蘿黛蒂花束用典：秋牡丹自阿多尼斯之血與女神之淚綻放，花語「短暫的愛」；褪色系列連向香水線 Noir Eden。</p>\n        <p><span class=\"lb en\">英文</span>fade 是整池動詞＝Faded Romance／Mauve／Eden／Mellow；一句話品名＝<b>Someday it will Fade</b>；配件全香氛詞（Airy Bangs／Tail、Aroma Glasses、Shiny Aroma）。</p></details>\n      <details><summary>#2 雨中玫瑰 · 雨中的失物招領</summary>\n        <p><span class=\"lb\">取名</span>「失去色彩的雨中紐約」點名無色之城＝紐約；雨中失物每線一朵玫瑰；佩戴古龍水・辛辣／甜香＝香調當色名。</p>\n        <p><span class=\"lb en\">英文</span><b>Lost in the Rain</b>: Red／Blue／Pink／Sepia Rose；<b>Wearing Cologne: Spicy／Sweet</b>；無色雨中紐約＝Colorless &amp; Rainy NY；歌詞卡 ROSY DESIRE LULLABY。</p></details>\n      <details><summary>#3 永恆皂園 · 用皂泡說永恆</summary>\n        <p><span class=\"lb\">取名</span>乙太＝Aether（古典元素論的「天界物質」）撐起 Heavenly Garden 的「天上」；矛盾修辭——用轉瞬即破的皂泡做永恆花園；Noir Eden 回收升格為主線。</p>\n        <p><span class=\"lb en\">英文</span>乙太＝<b>Ether</b>（Cerulescent／Nocturnal／Fairy）；香皂＝<b>Sabon</b>（Ever Serene: Sabon、Eternal Sabon）；Flower Thoughts - Noir Eden；香水術語 <b>Sillage</b>（留香軌跡）。</p></details>\n    </div>\n  </div>\n  <div class=\"lort\" id=\"lore-common\">\n  <div class=\"seg\" id=\"loreCommonSeg\" style=\"margin-bottom:14px\">\n    <button class=\"on\" data-c=\"lc-name\">命名與語言</button>\n    <button data-c=\"lc-allusion\">典故與含義</button>\n    <button data-c=\"lc-story\">故事與深掘</button>\n  </div>\n  <div class=\"lct show\" id=\"lc-name\">\n    <div class=\"card\">\n      <h3>命名的三層語言 <span class=\"tag ok\">語言分層</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">用什麼語言命名，幾乎就能判斷是哪種池：</p>\n      <ul class=\"tips\">\n        <li><b>品項名 → 法文</b>Lumière、Souvenir、Papillon、Dentelles…（Deux 主體）。</li>\n        <li><b>角色人名 → 拉丁／希臘／日耳曼</b>Psyche、Alma、Bénédicte、Marguerite…。</li>\n        <li><b>和風 ex 池 → 日語古語</b>川平子、玉響、白妙、うたかた…（#5／#12／#15）。</li>\n        <li><b>melem → 英文哲學詞</b>Logos、Simulacrum；<b>By(e) → 英文香調</b>Floral Eve、Citrus Mellow。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>法文詞彙小辭典 <span class=\"tag ok\">Deux 常用</span></h3>\n      <table>\n        <thead><tr><th>詞</th><th>意思</th><th>詞</th><th>意思</th></tr></thead>\n        <tbody>\n          <tr><td>Deux</td><td>二</td><td>Lumière</td><td>光</td></tr>\n          <tr><td>Âme</td><td>靈魂</td><td>Larme</td><td>眼淚</td></tr>\n          <tr><td>Rêve</td><td>夢</td><td>Néant</td><td>虛無</td></tr>\n          <tr><td>Vérité</td><td>真理</td><td>Soleil</td><td>太陽</td></tr>\n          <tr><td>Ciel</td><td>天空</td><td>Perle</td><td>珍珠</td></tr>\n          <tr><td>Chagrin</td><td>悲傷</td><td>Loin</td><td>遠方</td></tr>\n          <tr><td>Avenir</td><td>未來</td><td>Passé</td><td>過去</td></tr>\n          <tr><td>Présent</td><td>現在</td><td>Vieux</td><td>古老</td></tr>\n          <tr><td>Matin</td><td>早晨</td><td>Soirée</td><td>晚會／晚場</td></tr>\n          <tr><td>Rouge</td><td>紅</td><td>Noir</td><td>黑</td></tr>\n          <tr><td>Argent</td><td>銀</td><td>Ombre</td><td>影</td></tr>\n          <tr><td>Lueur</td><td>微光</td><td>Ténèbres</td><td>黑暗</td></tr>\n          <tr><td>Papillon</td><td>蝴蝶</td><td>Fleurir</td><td>綻放</td></tr>\n          <tr><td>Bourgeon</td><td>花苞</td><td>Fleur</td><td>花</td></tr>\n          <tr><td>Dentelles</td><td>蕾絲</td><td>Cache</td><td>遮／藏</td></tr>\n          <tr><td>Rideau</td><td>簾／幕</td><td>Marionnettes</td><td>人偶</td></tr>\n          <tr><td>Lune</td><td>月</td><td>Étoile</td><td>星</td></tr>\n          <tr><td>Grâce</td><td>優雅</td><td>Bénédicte</td><td>蒙福</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"card\">\n      <h3>日語古語・文化詞 <span class=\"tag ok\">和風池</span></h3>\n      <table>\n        <thead><tr><th>詞</th><th>讀音</th><th>意思</th></tr></thead>\n        <tbody>\n          <tr><td>玉響</td><td>tamayura</td><td>一瞬、稍縱即逝</td></tr>\n          <tr><td>うたかた</td><td>utakata</td><td>水面泡沫，喻易逝</td></tr>\n          <tr><td>徒櫻</td><td>adazakura</td><td>易落的櫻，「明日不可恃」</td></tr>\n          <tr><td>かはひらこ</td><td>kawahirako</td><td>「蝴蝶」的上古語</td></tr>\n          <tr><td>常世</td><td>tokoyo</td><td>神話中的永恆之國</td></tr>\n          <tr><td>雪洞</td><td>bonbori</td><td>紙罩燭燈</td></tr>\n          <tr><td>朔望</td><td>sakubō</td><td>新月（朔）與滿月（望）</td></tr>\n          <tr><td>宵</td><td>yoi</td><td>初夜、傍晚</td></tr>\n        </tbody>\n      </table>\n      <p class=\"fine\">補充：<b>白妙</b>在《萬葉集》裡是「枕詞」——冠在「衣、袖、雪」前的固定純白修飾語，是古人專用的詩歌套語。</p>\n    </div>\n    <div class=\"card\">\n      <h3>三品牌英文翻譯策略 <span class=\"tag ok\">一眼認出</span></h3>\n      <ul class=\"tips\">\n        <li><b>Deux</b>保留法文原文（Pure Lumière、Souvenir Eternel…），偶爾英法語序混用。</li>\n        <li><b>melem</b>意譯並升級成哲學詞——理性→Logos、福音→Faith。</li>\n        <li><b>By(e)</b>原生英文，幾乎零翻譯（SCENT FOR YOU、Floral Eve 本來就是英文）。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>官方英文錯字收集 <span class=\"tag hot\">遊戲內實拍</span></h3>\n      <table>\n        <thead><tr><th>錯字</th><th>正確</th><th>出處</th></tr></thead>\n        <tbody>\n          <tr><td>The <b>Gaurdian</b></td><td>Guardian</td><td>melem #2（連鏡室版一起錯）</td></tr>\n          <tr><td>Love <b>Pedal</b></td><td>Petal</td><td>Deux #5 R 眼</td></tr>\n          <tr><td><b>Nobel</b></td><td>Noble</td><td>Deux #9</td></tr>\n          <tr><td><b>Pesch</b></td><td>Pêche</td><td>Deux #9</td></tr>\n          <tr><td><b>Laprèmidi</b></td><td>l&#39;après-midi</td><td>Deux #7（男版掉重音）</td></tr>\n          <tr><td><b>Dajour</b></td><td>d&#39;Azur</td><td>Deux #8 音譯</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n  <div class=\"lct\" id=\"lc-allusion\">\n    <div class=\"card\">\n      <h3>道具的哲學與含義 <span class=\"tag hot\">名字裡的典故</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">不少道具直接借用哲學／神話概念當名字，本身就是一層隱喻。</p>\n      <ul class=\"tips\">\n        <li><b>擬像 Simulacrum</b>（melem #1）布希亞的擬像論——複製品取代真實、假象比真實更真；放進鏡室，正是「鏡中的你已非本人」。</li>\n        <li><b>邏各斯 Logos</b>（melem #2・理性）希臘哲學的「理性／言說／宇宙秩序」；英文版把「理性」直接譯成這個字。</li>\n        <li><b>虛無 Néant</b>（Deux #13）沙特《存在與虛無》的核心詞——意識對存在的否定；「廢忘的奈恩」＝被遺忘的虛無。</li>\n        <li><b>克洛諾斯 Chronos</b>（Deux #13）希臘的「時間」擬人（常與吞食己子的泰坦克洛諾斯相混）；放進時間池。</li>\n        <li><b>普緒克 Psyche</b>（Deux #14、melem #1）希臘文「靈魂、氣息」，以蝴蝶為象徵，也是愛神厄洛斯所戀的公主。</li>\n        <li><b>乙太 Aether</b>（By(e) #3）亞里斯多德的「第五元素」、構成天界的物質——撐起 Heavenly Garden 的「天上」。</li>\n<li><b>莊周夢蝶</b>（#14／#15 胡蝶）莊子夢見自己是蝴蝶，醒來分不清「是我夢見蝶，還是蝶夢見我」——真實與虛幻難分，恰與 Psyche（靈魂＝蝴蝶）及 melem 的鏡／擬像互相呼應。（連結為讀法。）</li>\n        <li><b>鏡花水月</b>（melem #3・鏡花的庇護）佛教與東亞美學：鏡中花、水中月，看得見卻不可得的虛幻。</li>\n        <li><b>無常・物哀</b>（By(e) 整體）日本美學對「易逝」的哀感——皂泡、落櫻、褪色都在說同一件事。</li>\n        <li><b>歸零 Zero</b>（melem #1・Boundary Distortion→Zero）邊界扭曲到「零」：存在被抹除回虛無。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>神話與經典典故 <span class=\"tag hot\">出處</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">名字背後的神話與經典，基本與深入寫在同一條。</p>\n      <details><summary>翁法勒 Omphale · Deux #6 男版主裙</summary>\n        <p>希臘神話呂底亞女王。海克力斯因罪被賣為她的奴隸，穿女裝、做女紅，女王反披他的獅皮——一則<b>性別反轉</b>神話，正好對位「致命之女 Femme Fatale」的男版。</p></details>\n      <details><summary>吉賽爾 Giselle · Deux #14</summary>\n        <p>浪漫芭蕾名劇：農家少女因心碎而死，化為夜裡索命的亡靈「<b>薇麗</b>」。但第二幕她卻<b>反過來保護</b>負心戀人，撐到破曉鐘響、薇麗失去力量為止——以寬恕代替復仇。「虛空的吉賽爾→異端的」正取自這抹幽靈舞姬的哀影。</p></details>\n      <details><summary>普緒克與厄洛斯 Psyche &amp; Eros · Deux #14／melem #1</summary>\n        <p>Psyche 希臘文「靈魂、氣息」，以<b>蝴蝶</b>為象徵，也是愛神厄洛斯所戀的公主。她每夜與愛神相會卻不許看臉；忍不住點起<b>油燈</b>偷看，一滴燈油驚醒他、愛神離去；歷經阿芙蘿黛蒂的試煉後獲永生、重逢。#14 滿池蝴蝶即源於此。</p></details>\n      <details><summary>秋牡丹與阿多尼斯 Anemone &amp; Adonis · By(e) #1</summary>\n        <p>秋牡丹自<b>阿多尼斯之血</b>與<b>阿芙蘿黛蒂之淚</b>中綻放；花語「短暫的愛／被遺棄的希望」——整池「終將消逝之美」的源頭。</p></details>\n      <details><summary>白雪公主 · melem #4</summary>\n        <p>「鏡譽鏡」＝<b>Mirror, Mirror on the Wall</b>（魔鏡魔鏡）、毒蘋果、王后的嫉妒；「紅果實的不可逆性」＝咬下就回不去。</p></details>\n      <details><summary>時計草＝受難花 · Deux #13</summary>\n        <p>無窮的時鐘草＝時計草／西番蓮。花形似鐘面，日名直譯「時計草」，放進時間池；西方名 <b>Passiflora（受難花）</b>是南美傳教士取的——絲狀花冠＝荊冠、五枚花藥＝五傷、三枚柱頭＝三根釘，比擬<b>基督受難</b>，一名雙關。</p></details>\n      <details><summary>獵戶座 Orion · Deux #8</summary>\n        <p>希臘神話的巨人獵人俄里翁，最後被置於天際化為<b>獵戶座</b>；星座主題正好落進藍薔薇的「星／夜」母題。</p></details>\n      <details><summary>卡蜜兒／卡蜜拉 Camille · 名字裡的女戰士</summary>\n        <p>語源是「祭儀侍者」，但在維吉爾《埃涅阿斯紀》裡，<b>卡蜜拉（Camilla）</b>是獻身給狩獵女神黛安娜的<b>處女戰士</b>，快到能掠過麥穗與水面而不留痕——「魔性之女」卡蜜兒的英氣正呼應此。</p></details>\n      <details><summary>瑪格麗特 Marguerite · 也是《浮士德》的悲劇少女</summary>\n        <p>除了「珍珠／雛菊」，Marguerite（葛麗卿）也是歌德《浮士德》裡被引誘、最終走向毀滅又獲救贖的悲劇女主角。（連結為讀法。）</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>顏色的含義 <span class=\"tag ok\">象徵＋傳統色</span></h3>\n      <p class=\"cond\" style=\"margin:10px 0 4px\"><b>常見象徵</b>（一般文化解讀，僅供參考）</p>\n      <ul class=\"tips\">\n        <li><b>白</b>純潔、無垢、空白，也可指消逝／死亡——By(e) 皂園、Deux 白薔薇。</li>\n        <li><b>黑</b>闇、哀悼、深淵，也象徵優雅——melem 基底、Deux 墮天使。</li>\n        <li><b>紅／赤 Rouge・Crimson</b>血、慾望、禁忌之果——Deux 紅寶石、melem 毒蘋果。</li>\n        <li><b>藍 Ciel・Azur</b>憂鬱、夜、遠方、夢——Deux 星月／藍薔薇。</li>\n        <li><b>紫</b>高貴、神秘、黃昏——Deux 時之哥德。</li>\n        <li><b>銀 Argent</b>鏡、月、冷冽——melem 常用。</li>\n      </ul>\n      <p class=\"cond\" style=\"margin:14px 0 4px\"><b>和風傳統色名</b>（真實日本傳統色，多用於 ex 和風池）</p>\n      <ul class=\"tips\">\n        <li><b>白妙 shirotae</b>栲布之白，萬葉集起就用的「純白」古語。</li>\n        <li><b>月白 tsukishiro</b>泛藍的月光白——名為「月白」，實際偏淡藍。</li>\n        <li><b>退紅 arazome</b>極淡的紅（褪過的紅）。</li>\n        <li><b>黑橡 kurotsurubami</b>橡實（つるばみ）染出的深黑。</li>\n        <li><b>灰櫻・薄冰・薄香・淡藤</b>帶灰的櫻粉、近乎透明的冷白、淡雅的香色與藤紫——整組是一張傳統色卡。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>音樂・戲劇・香水術語 <span class=\"tag ok\">其他梗</span></h3>\n      <ul class=\"tips\">\n        <li><b>迴旋曲 Rondo</b>（Deux #8 蔚藍的迴旋曲）主題反覆回歸的曲式（ABACA）。</li>\n        <li><b>頌歌 Anthem</b>（melem #2 聖歌之眼）讚頌／效忠之歌。</li>\n        <li><b>恍惚 Trance</b>（Deux #15 月蝶 Trance）出神、催眠般的夢境狀態。</li>\n        <li><b>人偶劇場 Théâtre de Marionnettes</b>（Deux #13）Matinée＝早場、Soirée＝晚場，日／夜兩場公演。</li>\n        <li><b>留香 Sillage</b>（By(e) #3）香水術語：走過後殘留的香氣軌跡。</li>\n        <li><b>肥皂 Sabon</b>＝法文 savon；<b>古龍水 Cologne</b>源自德國<b>科隆 Köln</b>市。</li>\n        <li><b>蔚藍海岸 Côte d&#39;Azur</b>（Deux #8 Riviera＋d&#39;Azur 合起來）；<b>獵戶座 Orion</b>＝藍薔薇的黑貓。</li>\n      </ul>\n    </div>\n  </div>\n  <div class=\"lct\" id=\"lc-story\">\n    <div class=\"card\">\n      <h3>故事線・把整個品牌串起來看 <span class=\"tag hot\">敘事讀法</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">單看一池只是衣服；連起來看，每個品牌其實在說一個故事（narrative 為社群讀法，部分推測）。</p>\n      <details><summary>melem・暗黑寓言四部曲</summary>\n        <p>一步步走進鏡子深處：<b>#1 鏡</b>——踏入鏡的那一邊，遇見「相似」的擬像；<b>#2 鴉與鳥籠</b>——理性被關進籠中，烏鴉銜來預感與妄想；<b>#3 迷途羊</b>——白色引導與黑色解放二選一，純真的羊被日食吞成黑；<b>#4 毒蘋果</b>——白雪公主的鏡子，誘惑→侵蝕→嫉視，咬下紅果就再也回不去。四池是一則越陷越深、無法回頭的鏡中童話。</p></details>\n      <details><summary>Deux・人偶、靈魂、時間</summary>\n        <p>把母題連起來是一則關於「人偶」的故事：少女其實是<b>娃娃盒裡的人偶</b>（#7 薔薇娃娃盒→#14 胡蝶娃娃盒）；她們有<b>靈魂</b>（Âme #10、Psyche #14）、會<b>墮落</b>（#10 墮天使）、被<b>時間</b>禁錮（#13 克洛諾斯・過去/現在/未來）；而蝴蝶＝靈魂的象徵，暗示<b>重生</b>。貫穿其中的 C.D／F.D 家族縮寫，像是這些人偶背後的「造物者家族」。（整體為推測讀法。）</p></details>\n      <details><summary>By(e)・凋零三部曲</summary>\n        <p>三池都在說「美會消逝」：<b>#1 秋牡丹</b>——花語「短暫的愛」，fade 是全池動詞；<b>#2 雨中玫瑰</b>——無色之城的紅花、來不及的愛；<b>#3 永恆皂園</b>——偏要用轉瞬即破的皂泡蓋一座「永恆」花園。名字 by(e) 本身就是「道別」。</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>藝術道具藏著故事 <span class=\"tag hot\">隱藏敘事</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">每池上方的「藝術」道具不只是裝飾，往往是整池的<b>敘事線索</b>。</p>\n      <ul class=\"tips\">\n        <li><b>Deux・娃娃盒母題</b>「白銀的薔薇娃娃盒」（#7）→「胡蝶的娃娃盒」（#14）——呼應<b>人偶系列</b>：畫中少女其實是被收進盒中的人偶。</li>\n        <li><b>Deux・家族暗線</b>#10「關於一個家族的書」＋署名 Charlotte D. 的「墮落天使的眼淚」→ #11「F.D‑glass key」→ #14「C.D‑蝴蝶」→ #15「F.D‑Papillon」，跨五池的家族縮寫線。</li>\n        <li><b>melem・每池都是一面鏡</b>鏡的那一邊（#1）→鏡的間隙（#2）→夢想與現實的境界（#3）→鏡譽鏡（#4）——藝術品本身就在講「鏡」。</li>\n        <li><b>By(e)・易逝的定格</b>植物花盒／秋牡丹花環（#1）、玫瑰紅飯店窗景（#2）、白日夢漣漪（#3）——都是留不住的一瞬。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>每池的「文字卡」＝主題宣言 <span class=\"tag ok\">Lore 卡</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">每池藝術道具裡藏一張<b>文字／品牌卡</b>，那就是這池的主題定調處。</p>\n      <ul class=\"tips\">\n        <li><b>Deux</b>#5 陰陽櫻歌（和歌）、#6 Le rubis de Deux、#13 IMMORTAL CHRONOS（不朽的克洛諾斯）。</li>\n        <li><b>melem</b>#1 Pittoresque「behind the mirror」、#4 melem mirror。</li>\n        <li><b>By(e)</b>#1 Anemone Bouquet（附花語小詩）、#2 ROSY DESIRE LULLABY（歌詞卡）。</li>\n      </ul>\n      <p class=\"fine\">看不懂一池在講什麼？先找它的文字卡——命名與主題的「原點」都在那。</p>\n    </div>\n    <div class=\"card\">\n      <h3>Deux 的月相與時間母題 <span class=\"tag hot\">貫穿</span></h3>\n      <ul class=\"tips\">\n        <li><b>月相走一輪</b>半月（#4）→ 朔望＝新月與滿月之契（#12）→ 月輪（#13）→ 月夜（#15）。</li>\n        <li><b>#13 把時間攤開講</b>克洛諾斯＋過去／現在／未來＋時計草（花形似鐘）——月光母題在此轉為「時間」。</li>\n      </ul>\n    </div>\n  </div>\n</div>\n", "sec-branddata": "\n  <div class=\"seg\" id=\"bdSeg\" style=\"margin-bottom:14px\">\n    <button class=\"on\" data-v=\"bd-deux\">Deux</button>\n    <button data-v=\"bd-melem\">melem</button>\n    <button data-v=\"bd-bye\">By(e)</button>\n    <button data-v=\"bd-rule\">規律觀察</button>\n    <button data-v=\"bd-color\">染色顏色</button>\n    <button data-v=\"bd-stat\">統計趨勢</button>\n  </div>\n\n  <div class=\"bdt show\" id=\"bd-deux\">\n    <div class=\"card\">\n      <h3>Deux 各池一覽 <span class=\"tag warn\">#4～#16</span></h3>\n      <table>\n        <thead><tr><th>池</th><th>販售期間</th><th>主色調・三色線</th></tr></thead>\n        <tbody>\n          <tr><td class=\"num\">#4</td><td>2023/02/23–04/23</td><td>冰藍白<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色 希耶爾｜染 玫瑰／夕暮／砂糖（另有 鵝黃、雪白、半月）</span></td></tr>\n          <tr><td class=\"num\">#5 ex</td><td>2023/03/24–05/28</td><td>紫黑櫻・和風<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色 宵／黑夜｜染 朧／追憶（另有殘櫻、黎明、玲瓏、紫水、幻白）</span></td></tr>\n          <tr><td class=\"num\">#6</td><td>2023/06/01–08/06</td><td>紅黑<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色 胭脂｜染 諾雅／天藍／罩紗（另有 幽靈、深碧、滅紫）</span></td></tr>\n          <tr><td class=\"num\">#7</td><td>2023/11/01–2024/01/07</td><td>純白<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色 珍珠・空・明亮｜染 丁香花／桃／蜂蜜（另有大地／銀）</span></td></tr>\n          <tr><td class=\"num\">#8</td><td>2024/02/01–04/07</td><td>藍黑<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色 藍（寂靜的玫瑰藍，另有 蔚藍、沙格蘭、夜）｜染 白蘭地／胭脂／玫瑰黑</span></td></tr>\n          <tr><td class=\"num\">#9</td><td>2024/02/23–04/28</td><td>藍白奶油<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色 夢（另有 天空色、珍珠、貴族）｜染 睡眠／黃／玫瑰（另有 光、白、桃）</span></td></tr>\n          <tr><td class=\"num\">#10</td><td>2024/08/01–10/06</td><td>黑灰<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色 靈魂（另有 日光、真理／真實、混亂）｜染 影／黎明／命運（另有 太陽、月）</span></td></tr>\n          <tr><td class=\"num\">#11</td><td>2025/02/01–04/06</td><td>象牙白<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色 拉魯姆（另有 自然、芙麗麗、索蕾）｜染 歐普／莉拉／芙蕾（另有天空、布魯蓉）</span></td></tr>\n          <tr><td class=\"num\">#12 ex</td><td>2025/03/01–05/04</td><td>黑白・月兔和風<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色 夜光（另有 黑橡、白玉、引導、漆黑）｜染 白月／紫苑／薄鼠（另有蒼白、白磁、明／暗）</span></td></tr>\n          <tr><td class=\"num\">#13</td><td>2025/08/01–10/05</td><td>暗紫<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色 克洛諾斯（另有 禁錮、夜公演、洛恩）｜染 紅蓮／青藍／月輪</span></td></tr>\n          <tr><td class=\"num\">#14</td><td>2026/02/01–04/05</td><td>黑粉<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色 玫瑰（另有 波爾多、卡爾曼）｜染 白／青藍／黑（另有灰、藍、紫晶）</span></td></tr>\n          <tr><td class=\"num\">#15 ex</td><td>2026/03/01–05/03</td><td>粉白・月夜蝶和風<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色 白妙（另有 薄香、淡藤、曙）｜染 宵闇／水月／白夜（另有灰櫻、白藍、薄冰）</span></td></tr>\n          <tr><td class=\"num\">#16</td><td>2026/08/01–10/04</td><td>灰白蕾絲・人偶回憶<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色 索拉納／阿爾特爾（銀，其餘染色未提供，待補）｜R眼 雷迪恩特／雷迪恩</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"fine\">結束時間一律週日 22:59；上架 2023 年中起統一 05:00。ex＝extra 特別彈。「原色」為 SR 主裙原色名；<b>#4～#16 已全數</b>以遊戲內「女生／男生」原色分頁核對確認；<span style=\"color:var(--rose)\">#16 目前只核對到角色道具與藝術道具清單（19/19）與販售期間，其他染色資訊之後補上。</span></p>\n    </div>\n    <div class=\"card\">\n      <h3>眼睛角色（成對） <span class=\"tag ok\">對照</span></h3>\n      <ul class=\"tips\">\n        <li><b>#4</b> 法蘭欣／桑蒂埃　<b>#6</b> 路意絲／路易＋卡蜜兒／塞繆爾　<b>#7</b> 安妮／安東尼</li>\n        <li><b>#8</b> 米內特／安莎＋里維埃拉／達祖爾　<b>#9</b> 克拉麗絲／克萊門特＋瑪格麗特／馬克西米利安</li>\n        <li><b>#10</b> 伊內斯／勞爾＋蕾妮　<b>#12</b> 瓏月夜的碎片／月夜的二兔　<b>#13</b> 創世的歷史＋奈恩</li>\n        <li><b>#14</b> 傑斯維／吉賽爾＋盧弗雷／露弗蕾莉亞　<b>#15</b> 希那／希希那＋川平子</li>\n        <li><b>#16</b> 索拉納／阿爾特爾（SR）＋雷迪恩特／雷迪恩（R）</li>\n        <li><b>原色版 → 染色版前綴一覽</b>下表整理各池眼睛的前綴變化。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>原色→染色 前綴對照 <span class=\"tag ok\">Deux 眼睛</span></h3>\n      <table>\n        <thead><tr><th>池</th><th>SR 眼 原色→染色</th><th>R 眼 變化</th></tr></thead>\n        <tbody>\n          <tr><td class=\"num\">#4</td><td>星彩的 → 月光彩虹的</td><td>—</td></tr>\n          <tr><td class=\"num\">#5</td><td>晚櫻的 → 徒櫻的</td><td>八重戀衣 → 泡沫戀衣</td></tr>\n          <tr><td class=\"num\">#6</td><td>紅寶石的 → 矯飾的</td><td>暗黑的 → 閃光的／沉默的</td></tr>\n          <tr><td class=\"num\">#7</td><td>清廉的 → 悠遠的</td><td>靜謐的 → 玲瓏的／虛心的</td></tr>\n          <tr><td class=\"num\">#8</td><td>藍薔薇的 → 闇薔薇</td><td>在寂靜中綻放的 → 沉睡的／盛開在拂曉的</td></tr>\n          <tr><td class=\"num\">#9</td><td>淡色天空的 → 微弱陽光的</td><td>追憶的 → 寂靜的／泡沫的</td></tr>\n          <tr><td class=\"num\">#10</td><td>天空之夜 → 黎明的</td><td>夜天光的 → 天光的／睿智的</td></tr>\n          <tr><td class=\"num\">#11</td><td>照亮朝露 → 照亮葉上的露珠</td><td>—</td></tr>\n          <tr><td class=\"num\">#12</td><td>櫻月夜的 → 瓏月夜的</td><td>常夜的二兔 → 月夜的二兔</td></tr>\n          <tr><td class=\"num\">#13</td><td>無窮的歷史 → 創世的歷史</td><td>廢忘的奈恩 → 光陰的／幽愁的<br>灰燼齒輪管 → 白金齒輪管</td></tr>\n          <tr><td class=\"num\">#14</td><td>虛空的 → 異端的</td><td>蝴蝶的 → 蝶的／慕情的</td></tr>\n          <tr><td class=\"num\">#15</td><td>月影之 → 今日樣之</td><td>—</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"card\">\n      <h3>每池固定結構 <span class=\"tag gold\">Deux</span></h3>\n      <ul class=\"tips\">\n        <li>藝術道具 <b>5 件</b>（extra 彈 6～7 件），含一張品牌文字卡。</li>\n        <li><b>SR 裙</b>＝3 色 × 男女 2 版＝6 格；<b>SR 眼</b>＝1 對角色 ×2＝4 格；<b>R 眼</b>＝另 1 對角色 ×2＝4 格。</li>\n        <li>R 服裝走獨立色名，不進主色線；髮型不染色、掛角色名。</li>\n        <li>帽子／頭飾吃滿 3 色；小配件只出 1～2 色；配件另設對立雙色組（太陽/月、明/暗、未來/過去、白日/黑闇/傍晚）。</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"bdt\" id=\"bd-melem\">\n    <div class=\"card\">\n      <h3>melem 各池一覽 <span class=\"tag warn\">#1～#4</span></h3>\n      <table>\n        <thead><tr><th>池</th><th>販售期間</th><th>主題</th></tr></thead>\n        <tbody>\n          <tr><td class=\"num\">#1</td><td>2023/08/18–10/22</td><td>鏡子<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色主調 黑／深色系</span></td></tr>\n          <tr><td class=\"num\">#2</td><td>2023/12/01–2024/02/04</td><td>烏鴉・鳥籠<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色主調 黑／白</span></td></tr>\n          <tr><td class=\"num\">#3</td><td>2024/11/01–2025/01/05</td><td>迷途羊<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色主調 黑／白／玫瑰</span></td></tr>\n          <tr><td class=\"num\">#4</td><td>2025/11/01–2026/01/04</td><td>白雪公主・毒蘋果<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色主調 黑／紅</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"fine\">#3 起固定 11/1 開池。</p>\n    </div>\n    <div class=\"card\">\n      <h3>變體詞對照 <span class=\"tag ok\">崩壞三階</span></h3>\n      <ul class=\"tips\">\n        <li><b>#1</b>：相似／幻影／斷片；眼＝深潭的／隔絕的米魯瓦爾；鏡室版後綴統一「<b>・梅拉</b>」</li>\n        <li><b>#2</b>：侵蝕／斷絕／晦冥；眼＝秘匿的／常闇的聖歌；#2 起鏡室後綴各道具不同（鏡子／預感／晦冥／理性／福音…）</li>\n        <li><b>#3</b>：帳／泡沫／落花、闇中／影／霧中；眼＝黑影的／永劫的迷失之羊</li>\n        <li><b>#4</b>：真紅／面紗／融解／魅惑／瓦解；眼＝毒蘋果的侵蝕／染上嫉視的毒蘋果</li>\n        <li><b>原色判別</b>：原色＝無後綴的基礎名；<b>鏡室（Mirror）版本</b>才帶變體詞後綴。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>每池固定結構 <span class=\"tag gold\">melem</span></h3>\n      <ul class=\"tips\">\n        <li><b>女生／男生分頁＝無後綴的原版</b>；<b>鏡室分頁＝帶後綴的鏡像版</b>（3 段衰變詞）。原版眼睛：#1 鏡界的米魯瓦爾、#2 異空的聖歌、#3 潔白的迷失的羊、#4 毒蘋果的誘惑。#3 的鏡像版會<b>白→黑反轉</b>（往白色虛構→往黑色虛構、白霞→黑霞、白角→黑角）；#4 則<b>黑／銀→赤反轉</b>（黑之鏡術師→赤的鏡術師、銀色面紗→深紅面紗）。</li>\n        <li>藝術道具 5 件；分類頁固定叫<b>「鏡室」</b>，全道具掛 Mirror 標。</li>\n        <li>變體不是顏色而是<b>崩壞三階</b>：完整態 → 遮蔽/侵蝕態 → 碎裂態。</li>\n        <li>眼睛固定三檔：SR 形容詞 ×2＋R 形容詞 ×1，同一角色換前綴。</li>\n        <li>必有連號道具<b>「鏡中的你」001→004</b> 不跳號；手部道具必拆 L／R 兩件。</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"bdt\" id=\"bd-bye\">\n    <div class=\"card\">\n      <h3>By(e) 各池一覽 <span class=\"tag warn\">#1～#3</span></h3>\n      <table>\n        <thead><tr><th>池</th><th>販售期間</th><th>主題</th></tr></thead>\n        <tbody>\n          <tr><td class=\"num\">#1</td><td>2024/05/24–07/28</td><td>Anemone Bouquet・秋牡丹<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色主調 白／米／花卉</span></td></tr>\n          <tr><td class=\"num\">#2</td><td>2025/05/09–07/13</td><td>Rose in the Rain・玫瑰都會<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色主調 紅／黑</span></td></tr>\n          <tr><td class=\"num\">#3</td><td>2026/05/08–07/12</td><td>Heavenly Garden・皂花永恆花園<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">原色主調 白／銀</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"fine\">固定 5 月開池，一年一彈；開池日逐年略前移（05/24 → 05/09 → 05/08），#4 預計 <b>2027/05 上旬</b>。</p>\n    </div>\n    <div class=\"card\">\n      <h3>三線與英文香水卡 <span class=\"tag ok\">三線制</span></h3>\n      <ul class=\"tips\">\n        <li><b>#1</b>：褪色紫紅（Floral Eve）＋黑（Noir Eden）＋柑橘（Citrus Mellow）</li>\n        <li><b>#2</b>：水藍（Elegant Aqua）＋寶貝粉（Baby Rosy）＋木質（Essence Wood）</li>\n        <li><b>#3</b>：夜色黑（Noir Eden）＋妖精彩（Fruity Fairy）＋綠（Evergreen）</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>每池固定結構 <span class=\"tag gold\">By(e)</span></h3>\n      <ul class=\"tips\">\n        <li><b>女生／男生分頁＝SCENT FOR YOU 標記的原版</b>；香氛道具分頁才是三線變體。原版另有專屬色詞（#1 棕褐色、珊瑚光暈、褪色浪漫；#2 紅、烏鴉、辛辣；#3 淡藍、透明、香皂）。</li>\n        <li>分類頁固定叫<b>「香氛道具」</b>；<b>唯一含彩妝部位</b>（嘴唇／腮紅／眉毛）的品牌。</li>\n        <li><b>三線制</b>：每線＝眼睛＋嘴唇＋腮紅（＋眉毛）＋一張英文香水名卡。</li>\n        <li>主打線配 SR 裙＋髮型；第三線最輕量（只有彩妝小物）。</li>\n        <li>舊線可回收升格：Noir Eden 從 #1 配角線 → #3 主打線。</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"bdt\" id=\"bd-rule\">\n    <div class=\"card\">\n      <h3>原色 vs 染色怎麼判斷 <span class=\"tag ok\">快速判別</span></h3>\n      <ul class=\"tips\">\n        <li><b>最上方大預覽圖</b>角色穿的顏色 ＝ <b>原色</b>（官方預設色）。</li>\n        <li>下方網格中的<b>其他顏色縮圖</b> ＝ <b>可染版本</b>；染出的實際顏色依玩家選擇而異。</li>\n        <li>常見原色多為<b>高飽和或純淨色</b>（白、銀、黑、深紅、粉）；<b>SR 物品的染色選項通常較多</b>。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>開池與販售規律 <span class=\"tag gold\">排程</span></h3>\n      <ul class=\"tips\">\n        <li><b>販售約 2 個月</b>結束一律<b>週日 22:59</b>；2023 年中起上架統一 05:00。</li>\n        <li><b>固定開池月</b>Deux 2～3 月（春季雙彈）＋8 月（命運檔）；By(e) 5 月；melem 自 #3 起固定 11/1。</li>\n        <li><b>Deux extra＝3 月和風</b>#5／#12／#15 皆為櫻／月主題；春季雙彈組合 #4+#5、#8+#9、#11+#12、#14+#15，深淺各一。</li>\n        <li><b>分類頁名</b>Deux＝客製化、melem＝鏡室、By(e)＝香氛道具。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>品項與結構規律 <span class=\"tag ok\">每池</span></h3>\n      <ul class=\"tips\">\n        <li><b>每池 29～30 件</b>Deux 自 #12、By(e) 自 #2 起為 30 件（#4 也是 30）；melem 維持 29 件。</li>\n        <li><b>Deux 收藏格</b>#4＝30、#5～#11＝29、<b>#12 起固定 30</b>。</li>\n        <li><b>Deux 結構</b>藝術 5 件（ex 6～7 含文字卡）、SR 裙 3 色×男女、SR/R 眼各一對角色、髮型掛角色名不染色。</li>\n        <li><b>melem 結構</b>眼睛三檔（SR 形容詞×2＋R×1，同角色換前綴）；必有連號「鏡中的你」；手部道具拆 L／R。</li>\n        <li><b>By(e) 結構</b>三線制（一冷一暖一大地），每線＝眼＋唇＋腮紅（＋眉）＋一張英文香水卡；唯一含彩妝。</li>\n              <li><b>稀有度</b>SR（彩虹標）＞ R（金標）＞ N；SR 物品的染色選項通常最多。</li>\n        <li><b>三種版本＋收藏數</b>每池分「藝術（不分性別）／女生／男生」；畫面右上「收藏 X／Y」＝你的完成度。</li>\n</ul>\n    </div>\n    <div class=\"card\">\n      <h3>命名與成對規律 <span class=\"tag ok\">彩蛋</span></h3>\n      <ul class=\"tips\">\n        <li><b>Deux 一切成雙</b>品項、眼睛角色、髮型、語序全部男女成對（Yvette／Yverre、Hiina／Hihina、Anne Tranquille／Tranquility Antoine）。</li>\n        <li><b>melem 連號</b>「鏡中的你」001→004 跟著你走過四池（#3 起編號帶空格）。</li>\n        <li><b>By(e) 香調命名</b>線名全走香調（Floral Eve、Citrus Mellow、Elegant Aqua…）；舊線會回收升格（Noir Eden #1→#3 主線）。</li>\n              <li><b>手部道具必拆 L／R</b>；melem #2 另有 她／他（Girl／Boy）成對。</li>\n</ul>\n      <p class=\"fine\">以上為玩家實際紀錄整理的觀察，僅供參考，未來排程以官方公告為準。</p>\n    </div>\n  </div>\n  <div class=\"bdt\" id=\"bd-color\">\n    <div class=\"card\">\n      <h3>原色（預設色）使用率 <span class=\"tag hot\">約略佔比</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">各套<b>大預覽圖原色</b>的主色調分布（估算，非官方數據）。</p>\n      <div class=\"cbar\"><div class=\"lbl\"><b>白・夢幻／純潔主力</b><span class=\"pct\">35–40%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:38%;background:linear-gradient(90deg,#e8e4f0,#cfc7e6)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>黑・黑暗／神秘核心</b><span class=\"pct\">25–30%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:28%;background:linear-gradient(90deg,#8a86a0,#4a4560)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>紅粉・玫瑰／蝴蝶</b><span class=\"pct\">15–20%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:18%;background:linear-gradient(90deg,#f3c3d4,#e0728f)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>藍紫・夜／神秘／花</b><span class=\"pct\">12–18%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:15%;background:linear-gradient(90deg,#b9c4e8,#6f7fd0\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>其他・金銀點綴／透明光效</b><span class=\"pct\">5–8%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:7%;background:linear-gradient(90deg,#ecd9a8,#cbb26a)\"></div></div></div>\n    </div>\n    <div class=\"card\">\n      <h3>可染色（染色選項）分布 <span class=\"tag hot\">截圖實測</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">依 19 套遊戲內截圖，統計各池主染色三色線＋主要配色的色系分布——<b>染色把色域大幅拉開</b>，藍／紫／暖比原色明顯變多。</p>\n      <div class=\"cbar\"><div class=\"lbl\"><b>白・銀</b><span class=\"pct\">~24%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:24%;background:linear-gradient(90deg,#e8e4f0,#cfc7e6)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>黑・灰</b><span class=\"pct\">~19%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:19%;background:linear-gradient(90deg,#8a86a0,#4a4560)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>藍</b><span class=\"pct\">~15%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:15%;background:linear-gradient(90deg,#b9c4e8,#6f7fd0)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>紅・粉</b><span class=\"pct\">~14%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:14%;background:linear-gradient(90deg,#f3c3d4,#e0728f)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>紫</b><span class=\"pct\">~13%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:13%;background:linear-gradient(90deg,#d3c0e6,#9a6fc0)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>暖・棕・黃</b><span class=\"pct\">~12%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:12%;background:linear-gradient(90deg,#ecd9a8,#cb9a5a)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>綠</b><span class=\"pct\">~2%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:2%;background:linear-gradient(90deg,#bfe0c0,#6fae74)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>妖精・其他</b><span class=\"pct\">~1%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:1%;background:linear-gradient(90deg,#e6d0f0,#c08fd0)\"></div></div></div>\n      <p class=\"fine\">黑佔比比原本估算高——因為 melem 四池皆黑、By(e) Noir Eden 重複、Deux 多池有黑染色（諾雅／玫瑰黑／影／黑玉／宵闇…）。</p>\n    </div>\n    <div class=\"card\">\n      <h3>原色 vs 可染色 對照 <span class=\"tag ok\">一眼比較</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">同一色系在「原色」與「可染色」的佔比差；箭頭表示染色後的增減。</p>\n      <table>\n        <thead><tr><th>色系</th><th>原色</th><th>可染色</th><th>變化</th></tr></thead>\n        <tbody>\n          <tr><td>白・銀</td><td>35–40%</td><td>~24%</td><td>▼ 減</td></tr>\n          <tr><td>黑・灰</td><td>25–30%</td><td>~19%</td><td>▼ 減</td></tr>\n          <tr><td>紅・粉</td><td>15–20%</td><td>~14%</td><td>≈ 持平</td></tr>\n          <tr><td>藍</td><td rowspan=\"2\" style=\"vertical-align:middle\">12–18%<br><span style=\"font-size:11px;color:var(--ink-soft)\">(藍紫合計)</span></td><td>~15%</td><td>▲ 增</td></tr>\n          <tr><td>紫</td><td>~13%</td><td>▲ 增</td></tr>\n          <tr><td>暖・棕・黃</td><td>5–8%<br><span style=\"font-size:11px;color:var(--ink-soft)\">(含其他)</span></td><td>~12%</td><td>▲ 大增</td></tr>\n          <tr><td>綠</td><td>—</td><td>~2%</td><td>▲ 新增</td></tr>\n        </tbody>\n      </table>\n      <p class=\"fine\">重點：原色集中在白／黑（展示用），染色把<b>藍・紫・暖</b>大幅補進來——這才是實際可搭出的色域。數字依遊戲內截圖統整。</p>\n    </div>\n    <div class=\"card\">\n      <h3>各池染色主色（實測） <span class=\"tag warn\">Deux 三色線</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">各池 SR 主裙的三色染色線（取自遊戲內截圖）。</p>\n      <table>\n        <thead><tr><th>池</th><th>主染色三色</th></tr></thead>\n        <tbody>\n          <tr><td class=\"num\">#4</td><td>玫瑰／夕暮／砂糖</td></tr>\n          <tr><td class=\"num\">#5</td><td>朧／追憶／殘櫻</td></tr>\n          <tr><td class=\"num\">#6</td><td>諾雅／天藍／罩紗</td></tr>\n          <tr><td class=\"num\">#7</td><td>丁香花／桃／蜂蜜</td></tr>\n          <tr><td class=\"num\">#8</td><td>白蘭地／胭脂／玫瑰黑</td></tr>\n          <tr><td class=\"num\">#9</td><td>睡眠／黃／玫瑰</td></tr>\n          <tr><td class=\"num\">#10</td><td>影／黎明／命運</td></tr>\n          <tr><td class=\"num\">#11</td><td>歐普／莉拉／芙蕾</td></tr>\n          <tr><td class=\"num\">#12</td><td>白月／薄鼠／紫苑</td></tr>\n          <tr><td class=\"num\">#13</td><td>紅蓮／青藍／月輪</td></tr>\n          <tr><td class=\"num\">#14</td><td>白／青藍／黑</td></tr>\n          <tr><td class=\"num\">#15</td><td>宵闇／水月／白夜</td></tr>\n        </tbody>\n      </table>\n      <p class=\"fine\">melem 鏡室以黑白灰為主、#4 首見真紅；By(e) 三線見「品牌資料→By(e)」。</p>\n    </div>\n    <div class=\"card\">\n      <h3>各家染色策略 <span class=\"tag ok\">色彩規律</span></h3>\n      <ul class=\"tips\">\n        <li><b>Deux・深淺交替</b>以淺深交替為主；連深只出現在「extra→夏彈」或「夏彈→次年 2 月彈」；同年春季雙彈必一深一淺。</li>\n        <li><b>Deux・色相輪替</b>同一色相連用不超過兩池就換；紅只出現過一次（#6・2023）；藍主場到 2024，之後全是無彩＋紫＋粉。</li>\n        <li><b>melem・重點色從無到有</b>基底永遠黑白灰——#1/#2 純無彩、#3 淡點綴、#4 首見飽和紅。</li>\n        <li><b>By(e)・三線恆定</b>九線中只有黑（Noir Eden）重複；每池「一冷一暖一大地」；封面色與內容色可脫鉤（#2 封面紅、內容藍粉棕）。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>色彩時間演進 <span class=\"tag hot\">趨勢</span></h3>\n      <ul class=\"timeline\">\n        <li><b>2023</b>光／粉／紅——Deux 星月、白薔薇；紅寶石唯一的紅檔。</li>\n        <li><b>2024</b>藍／黑／花——藍薔薇、藍白奶油主場；melem 鴉登場帶入黑。</li>\n        <li><b>2025</b>白蝶／暗紫——晨露、月兔、時之哥德轉深紫黑。</li>\n        <li><b>2026</b>粉蝶／光系——蝶與薔薇、月夜蝶；蝴蝶成為新主 motif。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Motif 演進 <span class=\"tag ok\">主題母題</span></h3>\n      <ul class=\"tips\">\n        <li><b>月光</b>貫穿 Deux 全期（Lune／Starlight／月兔／月夜蝶）。</li>\n        <li><b>玫瑰</b>2023–2024 主力（紅寶石、藍薔薇、白薔薇、By(e) 玫瑰雨）。</li>\n        <li><b>蝴蝶</b>2026 新主母題（Psyche→#14／#15 滿池蝶）。</li>\n        <li><b>鏡／影</b>melem 專屬，貫穿四池的暗黑寓言。</li>\n      </ul>\n    </div>\n  </div>\n  <div class=\"bdt\" id=\"bd-stat\">\n    <div class=\"card\">\n      <h3>總覽數字 <span class=\"tag ok\">統計</span></h3>\n      <div class=\"row\"><span>總套裝數</span><span class=\"r t\">19 套（Deux 12＋melem 4＋By(e) 3）</span></div>\n      <div class=\"row\"><span>時間跨度</span><span class=\"r t\">2023/02～2026/06</span></div>\n      <div class=\"row\"><span>每池品項</span><span class=\"r t\">29～30 件</span></div>\n      <div class=\"row\"><span>開池月份</span><span class=\"r t\">2·3·5·8·11 月</span></div>\n    </div>\n    <div class=\"card\">\n      <h3>品牌定位 <span class=\"tag gold\">一句話</span></h3>\n      <ul class=\"tips\">\n        <li><b>Deux</b>最長壽、最均衡百搭——光暗對比＋高客製化，經典 motif 全包（月光、玫瑰、蝴蝶、光影）。</li>\n        <li><b>melem</b>黑暗系代表——風格最統一，黑白灰基底、哥特劇場感；#4 首度引入飽和紅。</li>\n        <li><b>By(e)</b>優雅花卉系——花束／花園／玫瑰雨主題，白＋accent 色，唯一含彩妝。</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>價值趨勢 <span class=\"tag hot\">保值</span></h3>\n      <ul class=\"tips\">\n        <li><b>不復刻＝越舊越貴</b>品 4 是國際服首個品牌池、最貴。</li>\n        <li><b>品牌變多後稀釋</b>#7 起品牌增加，單池價值低於 #4／#5，但放久仍會漲。</li>\n        <li><b>蠟燭染色會過期</b>melem 絕版染色年份越高通常越值錢。</li>\n      </ul>\n      <p class=\"fine\">以上為玩家觀察，僅供參考，實際以官方公告與市場為準。</p>\n    </div>\n  </div>\n\n", "sec-feedback": "\n  <div class=\"card\" style=\"text-align:center\">\n    <h3 style=\"justify-content:center\">意見專欄 <span class=\"tag warn\">聯絡站主</span></h3>\n    <p class=\"cond\" style=\"font-size:14.5px\">想<b>補充規則</b>、發現<b>有錯誤</b>——請私訊 IG：</p>\n    <a class=\"ig-btn\" href=\"https://www.instagram.com/diana0520_art?igsh=MWZoajRvM3c5enUyZw==\" target=\"_blank\" rel=\"noopener\">📷 @diana0520_art</a>\n    <img class=\"ig-qr\" src=\"data:image/jpeg;base64,\" alt=\"Instagram QR code\">\n    <p class=\"fine\">點按鈕或掃描 QR code 直接開啟 Instagram。</p>\n  </div>\n"};
